            <div className="pt-8 border-t border-slate-100 space-y-3">
              <button onClick={handleExport} className="w-full flex items-center justify-center gap-3 bg-slate-100 py-4 rounded-2xl text-[10px] font-black uppercase text-slate-600"><Download size={16} /> Exportar Backup</button>
