                              isAnimationActive={true}
                              animationBegin={200}
                              animationDuration={1500}
                              animationEasing="ease-out"
                            >
                              {chartData.map((_, i) => <Cell key={i} fill={chart.color[i % chart.color.length]} stroke="none" className="transition-all duration-300 hover:opacity-80 cursor-pointer" />)}
                            </Pie>
                            <Tooltip formatter={(val: any) => chart.formatter(val)} />
                            <Legend 
                              iconType="circle" 
                              formatter={(value, entry: any, index: number) => (
                                <span className="text-[10px] font-bold text-slate-600 ml-1">
                                  {isOperatorChart ? `${index + 1}º ` : ''}{value} ({chart.formatter(entry.payload.value)})
                                </span>
                              )} 
                            />
                          </PieChart>
                        </ResponsiveContainer>
                      ) : (
                        <div className="h-full flex items-center justify-center text-slate-300 font-bold text-xs uppercase text-center">Nenhum registro para {getMonthName(dashboardMonth)}</div>
                      )}
