                            <button type="button" onClick={(evt) => { evt.stopPropagation(); handleDeleteReportItem(e.id); }} className="text-red-400 p-1.5 hover:bg-red-50 rounded-lg transition-colors group" title="Excluir"><Trash2 size={12} className="group-hover:text-red-600" /></button>
                          </td>
                        </tr>
                      ))}
                      <tr className="bg-slate-800 text-white font-black text-[10px]">
                        <td colSpan={5} className="px-4 py-3 text-right uppercase tracking-widest">Totais Registrados:</td>
