                <div className="flex gap-2">
                  <input type="text" value={newOpName} onChange={e => setNewOpName(e.target.value)} placeholder="Novo operador..." className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2 text-xs font-bold focus:ring-2 focus:ring-blue-500/10 outline-none" />
                  <button onClick={() => { if (newOpName && !operators.includes(newOpName)) { setOperators(prev => [...prev, newOpName]); setNewOpName(''); } }} className="bg-blue-600 text-white p-2.5 rounded-xl hover:bg-blue-700 transition-colors shadow-sm"><Plus size={18} /></button>
