  Save, X, Edit2, LogOut, Calendar, CalendarDays, TrendingUp, AlertTriangle, CheckSquare, Square, FileSpreadsheet, Info, ChevronLeft, ChevronRight, FileDown, AlertCircle, ImageIcon, Target, LayoutDashboard, Users
} from 'lucide-react';
