            <div className="flex flex-col items-center min-w-[140px]">
              <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Referência</span>
              <span className="text-xs font-black text-slate-700 capitalize">{getMonthName(dashboardMonth)}</span>
            </div>
            <button onClick={() => changeMonth(1)} className="p-1 hover:bg-slate-100 rounded-lg text-slate-400 transition-colors"><ChevronRight size={18} /></button>
          </div>
