                  </div>
                </div>
              </button>

              <div className="grid grid-cols-2 gap-4 md:col-span-2 lg:col-span-2">
                <button 
                  onClick={() => setSelectedTimeframe('today')} 
                  className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                    selectedTimeframe === 'today' 
                    ? 'bg-slate-800 border-slate-700 shadow-xl shadow-slate-200 text-white' 
                    : 'bg-white border-slate-100 hover:border-slate-300 text-slate-800'
                  }`}
                >
                  <div className="flex items-center justify-between mb-3">
                    <div className={`p-2 rounded-lg ${selectedTimeframe === 'today' ? 'bg-white/20' : 'bg-slate-100 text-slate-600'}`}>
                      <Calendar size={18} />
                    </div>
                    <span className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'today' ? 'text-slate-400' : 'text-slate-400'}`}>
                      Hoje
                    </span>
                  </div>
                  <div className="space-y-1">
                    <div className="text-xl font-black">{formatWeight(totals.today)}</div>
                    <p className={`text-[8px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'today' ? 'text-slate-400' : 'text-slate-400'}`}>
                      Últimas 24h
                    </p>
                  </div>
                </button>

                <button 
                  onClick={() => setSelectedTimeframe('yesterday')} 
                  className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                    selectedTimeframe === 'yesterday' 
                    ? 'bg-emerald-600 border-emerald-500 shadow-xl shadow-emerald-200 text-white' 
                    : 'bg-white border-slate-100 hover:border-emerald-200 text-slate-800'
                  }`}
                >
                  <div className="flex items-center justify-between mb-3">
                    <div className={`p-2 rounded-lg ${selectedTimeframe === 'yesterday' ? 'bg-white/20' : 'bg-emerald-50 text-emerald-600'}`}>
                      <TrendingUp size={18} />
                    </div>
                    <span className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>
                      Ontem
                    </span>
                  </div>
                  <div className="space-y-1">
                    <div className="text-xl font-black">{formatWeight(totals.yesterday)}</div>
                    <p className={`text-[8px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>
                      Anterior
                    </p>
                  </div>
                </button>
              </div>

              <button 
                onClick={() => setSelectedTimeframe('week')} 
                className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                  selectedTimeframe === 'week' 
                  ? 'bg-violet-600 border-violet-500 shadow-xl shadow-violet-200 text-white' 
                  : 'bg-white border-slate-100 hover:border-violet-200 text-slate-800'
                }`}
              >
                <div className="flex items-center justify-between mb-3">
                  <div className={`p-2 rounded-lg ${selectedTimeframe === 'week' ? 'bg-white/20' : 'bg-violet-50 text-violet-600'}`}>
                    <CalendarDays size={18} />
                  </div>
                  <span className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>
                    Esta Semana
                  </span>
                </div>
                <div className="space-y-1">
                  <div className="text-xl font-black">{formatWeight(totals.week)}</div>
                  <p className={`text-[8px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>
                    Acumulado (Dom-Sáb)
                  </p>
                </div>
              </button>
            </div>

            {/* SEÇÃO: ANALISAR GRÁFICOS (CAIXA DE SELEÇÃO) */}
            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 space-y-4 no-print">
              <div className="flex items-center gap-3 border-b border-slate-50 pb-4">
                <div className="w-10 h-10 bg-blue-50 text-blue-600 rounded-xl flex items-center justify-center">
                  <PieChartIcon size={20} />
                </div>
                <div>
                  <h3 className="text-sm font-black text-slate-800 uppercase tracking-tight leading-none">Análise de Gráficos</h3>
                  <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Escolha uma métrica para visualização detalhada</p>
                </div>
              </div>

              <div className="relative group">
                <select 
                  value={selectedChartId || ''} 
                  onChange={(e) => setSelectedChartId(e.target.value === '' ? null : e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-xs font-black text-slate-700 outline-none focus:ring-4 focus:ring-blue-500/10 transition-all cursor-pointer appearance-none uppercase tracking-widest pr-12"
                >
                  <option value="">Nenhum gráfico selecionado...</option>
                  <option value="all">📊 Mostrar Todos os Gráficos</option>
                  {allCharts.map(chart => (
                    <option key={chart.id} value={chart.id}>{chart.title}</option>
                  ))}
                </select>
                <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400 group-hover:text-blue-600 transition-colors">
                  <ChevronDown size={20} />
                </div>
              </div>
            </div>

            {selectedChartId === null ? (
              <div className="bg-white/50 border-2 border-dashed border-slate-200 rounded-3xl p-12 text-center flex flex-col items-center gap-4 transition-all duration-500 no-print">
                 <div className="w-16 h-16 bg-white rounded-2xl flex items-center justify-center text-slate-300 shadow-sm border border-slate-100">
                    <EyeOff size={32} />
                 </div>
                 <div className="space-y-1">
                    <p className="text-xs font-black text-slate-400 uppercase tracking-widest">Aguardando Seleção</p>
                    <p className="text-[10px] text-slate-400 italic">Selecione um gráfico na caixa acima para carregar as informações.</p>
                 </div>
              </div>
            ) : (
              <>
                <div className="flex items-center gap-2 px-2 no-print-section animate-in fade-in duration-700">
                  <span className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></span>
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Analisando: <span className="text-blue-600">{selectedChartId === 'all' ? 'Todos os Indicadores' : allCharts.find(c => c.id === selectedChartId)?.title}</span> • Período: <span className="text-slate-600">{selectedTimeframe === 'today' ? 'Hoje' : selectedTimeframe === 'yesterday' ? 'Ontem' : selectedTimeframe === 'week' ? 'Esta Semana' : getMonthName(dashboardMonth)}</span></p>
                </div>

                <div className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 transition-all duration-500 animate-in slide-in-from-bottom-4 ${selectedChartId !== 'all' ? 'lg:grid-cols-1 max-w-2xl mx-auto' : ''}`}>
                  {visibleCharts.map((chart, idx) => {
                    let chartData: any[] = [];
                    let dataKey = chart.key;
                    const isOperatorChart = !chart.key.startsWith('comparison_');
                    if (chart.key === 'comparison_prod_ecob') {
                      const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                      const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                      chartData = [{ name: 'Produção', value: totalProd }, { name: 'Eco B', value: totalEcoB }].filter(d => d.value > 0);
                      dataKey = 'value';
                    } else if (chart.key === 'comparison_ecob_recycled') {
                      const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                      const totalRecycled = filteredDataForCharts.reduce((acc, c) => {
                        if (c.machine.toLowerCase().includes('erema')) return acc + (c.netWeight || 0);
                        return acc;
                      }, 0);
                      chartData = [{ name: 'Eco B Gerado', value: totalEcoB }, { name: 'Reciclado Erema', value: totalRecycled }].filter(d => d.value > 0);
                      dataKey = 'value';
                    } else if (chart.key === 'comparison_prod_borra') {
                      const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                      const totalBorra = filteredDataForCharts.reduce((acc, c) => acc + (c.borraTotal || 0), 0);
                      chartData = [{ name: 'Produção', value: totalProd }, { name: 'Borra', value: totalBorra }].filter(d => d.value > 0);
                      dataKey = 'value';
                    } else if (chart.key === 'comparison_time') {
                      let totalAvailable = 0;
                      let totalDowntime = 0;
                      filteredDataForCharts.forEach(item => {
                         const shiftDuration = getShiftDuration(item.shift);
                         if (item.isNoWorkDay) { totalAvailable += shiftDuration; totalDowntime += shiftDuration; } else { const stops = (item.manutencaoMin || 0) + (item.processoMin || 0) + (item.outrosMin || 0); totalAvailable += shiftDuration; totalDowntime += stops; }
                      });
                      const totalRunning = Math.max(0, totalAvailable - totalDowntime);
                      chartData = [{ name: 'Produção', value: totalRunning }, { name: 'Parada', value: totalDowntime }].filter(d => d.value > 0);
                      dataKey = 'value';
                    } else {
                      chartData = stats.filter(s => (s[chart.key as keyof OperatorStat] as number) > 0).sort((a, b) => (b[chart.key as keyof OperatorStat] as number) - (a[chart.key as keyof OperatorStat] as number));
                    }
                    const cardId = `chart-card-${idx}`;
                    return (
                      <div key={idx} id={cardId} className={`bg-white rounded-3xl p-6 shadow-sm border border-slate-100 min-h-[460px] flex flex-col hover:shadow-xl transition-all duration-500 hover:-translate-y-1 group/card ${selectedChartId !== 'all' ? 'min-h-[500px]' : ''}`}>
                        <div className="flex justify-between items-start mb-4">
                          <h3 className="font-black text-xs uppercase tracking-widest text-slate-800 group-hover/card:text-blue-600 transition-colors">{chart.title}</h3>
                          <button 
                            onClick={(e) => { e.stopPropagation(); handleDownloadChartPNG(cardId, chart.title); }}
                            className="download-chart-btn p-1.5 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-lg transition-all no-print"
                            title="Baixar PNG"
                          >
                            <ImageIcon size={16} />
                          </button>
                        </div>
                        <div className="flex-1">
                          {chartData.length > 0 ? (
                            <ResponsiveContainer width="100%" height="100%">
                              <PieChart>
                                <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} dataKey={dataKey} nameKey="name" label={renderCustomizedLabel} paddingAngle={2} isAnimationActive={!isGeneratingPDF} animationBegin={200} animationDuration={1500} animationEasing="ease-out">
                                  {chartData.map((_, i) => <Cell key={i} fill={chart.color[i % chart.color.length]} stroke="none" className="transition-all duration-300 hover:opacity-80 cursor-pointer" />)}
                                </Pie>
                                <Tooltip formatter={(val: any) => chart.formatter(val)} />
                                <Legend iconType="circle" formatter={(value, entry: any, index: number) => (<span className="text-[10px] font-bold text-slate-600 ml-1">{isOperatorChart ? `${index + 1}º ` : ''}{value} ({chart.formatter(entry.payload.value)})</span>)} />
                              </PieChart>
                            </ResponsiveContainer>
                          ) : (
                            <div className="h-full flex items-center justify-center text-slate-300 font-bold text-xs uppercase text-center">Nenhum registro para {getMonthName(dashboardMonth)}</div>
                          )}
                        </div>
                        <div className="mt-4 pt-3 border-t border-slate-50">
                          <p className="text-[9px] font-medium text-slate-400 italic leading-relaxed flex items-start gap-1.5"><Info size={10} className="mt-0.5 shrink-0 text-blue-400" />{chart.description}</p>
                        </div>
                      </div>
                    );
                  })}
