                  <div className="space-y-1">
                    <div className="text-xl font-black">{formatWeight(totals.today)}</div>
                    <p className={`text-[8px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'today' ? 'text-slate-400' : 'text-slate-400'}`}>
                      Últimas 24h
                    </p>
                  </div>
                </button>

                <button 
                  onClick={() => setSelectedTimeframe('yesterday')} 
                  className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                    selectedTimeframe === 'yesterday' 
                    ? 'bg-emerald-600 border-emerald-500 shadow-xl shadow-emerald-200 text-white' 
                    : 'bg-white border-slate-100 hover:border-emerald-200 text-slate-800'
                  }`}
                >
                  <div className="flex items-center justify-between mb-3">
                    <div className={`p-2 rounded-lg ${selectedTimeframe === 'yesterday' ? 'bg-white/20' : 'bg-emerald-50 text-emerald-600'}`}>
                      <TrendingUp size={18} />
                    </div>
                    <span className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>
                      Ontem
                    </span>
                  </div>
                  <div className="space-y-1">
                    <div className="text-xl font-black">{formatWeight(totals.yesterday)}</div>
                    <p className={`text-[8px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>
                      Anterior
                    </p>
                  </div>
                </button>
              </div>

              <button 
                onClick={() => setSelectedTimeframe('week')} 
                className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                  selectedTimeframe === 'week' 
                  ? 'bg-violet-600 border-violet-500 shadow-xl shadow-violet-200 text-white' 
                  : 'bg-white border-slate-100 hover:border-violet-200 text-slate-800'
                }`}
              >
                <div className="flex items-center justify-between mb-3">
                  <div className={`p-2 rounded-lg ${selectedTimeframe === 'week' ? 'bg-white/20' : 'bg-violet-50 text-violet-600'}`}>
                    <CalendarDays size={18} />
                  </div>
                  <span className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>
                    Esta Semana
                  </span>
                </div>
                <div className="space-y-1">
                  <div className="text-xl font-black">{formatWeight(totals.week)}</div>
                  <p className={`text-[8px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>
                    Acumulado (Dom-Sáb)
                  </p>
                </div>
              </button>
            </div>

