                  </div>
                </div>
              </button>

              <div className="grid grid-cols-2 gap-4 md:col-span-2 lg:col-span-2">
                <button 
                  onClick={() => setSelectedTimeframe('today')} 
                  className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                    selectedTimeframe === 'today' 
                    ? 'bg-slate-800 border-slate-700 shadow-xl shadow-slate-200 text-white' 
                    : 'bg-white border-slate-100 hover:border-slate-300 text-slate-800'
                  }`}
                >
                  <div className="flex items-center justify-between mb-3">
                    <div className={`p-2 rounded-lg ${selectedTimeframe === 'today' ? 'bg-white/20' : 'bg-slate-100 text-slate-600'}`}>
                      <Calendar size={18} />
