                  className={`flex flex-col p-4 rounded-2xl border transition-all duration-300 ${
                    selectedTimeframe === 'yesterday' 
                    ? 'bg-emerald-600 border-emerald-500 shadow-xl shadow-emerald-200 text-white' 
                    : 'bg-white border-slate-100 hover:border-emerald-200 text-slate-800'
                  }`}
                >
                  <div className="flex items-center justify-between mb-3">
                    <div className={`p-2 rounded-lg ${selectedTimeframe === 'yesterday' ? 'bg-white/20' : 'bg-emerald-50 text-emerald-600'}`}>
                      <TrendingUp size={18} />
                    </div>
                    <span className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>
                      Ontem
