  Plus, Settings, BarChart3, FileText, Search, 
  Printer, ShieldCheck, Download, Upload, Trash2, Cpu, 
  Save, X, Edit2, LogOut, Calendar, CalendarDays, TrendingUp, AlertTriangle, CheckSquare, Square, FileSpreadsheet, Info, ChevronLeft, ChevronRight, FileDown, AlertCircle, ImageIcon, Target, LayoutDashboard, Users, PieChart as PieChartIcon, EyeOff, ChevronDown, Filter
} from 'lucide-react';
