                      <td className="px-4 py-4 text-right">{e.ecoA}</td>
                      <td className="px-4 py-4 text-right text-red-500">{e.borraTotal}</td>
                      <td className="px-4 py-4 text-right no-print">
                        <button onClick={() => { setEditingEntry(e); setIsModalOpen(true); }} className="text-blue-500 p-1.5 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 size={12} /></button>
                        <button onClick={() => handleDeleteReportItem(e.id)} className="text-red-400 p-1.5 hover:bg-red-50 rounded-lg transition-colors"><Trash2 size={12} /></button>
                      </td>
