                  <span className="flex items-center gap-3"><Users size={18} className="text-blue-500" /> Gerenciar Equipe</span>
                  <ChevronRight size={16} className="text-slate-300 group-hover:text-blue-500" />
                </button>
                <button onClick={() => { setIsShiftModalOpen(true); setIsMenuOpen(false); }} className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-blue-50 text-slate-700 rounded-2xl text-[10px] font-black uppercase transition-all group">
                  <span className="flex items-center gap-3"><Clock size={18} className="text-blue-500" /> Gerenciar Turnos</span>
                  <ChevronRight size={16} className="text-slate-300 group-hover:text-blue-500" />
