              <div className="pt-4 border-t border-slate-100 space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Segurança e Dados</label>
                <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 p-4 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase transition-all hover:bg-emerald-100">
