  const totals = useMemo(() => {
    const now = new Date();
    const todayStr = now.toLocaleDateString('sv-SE');
    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');
    const startOfWeek = new Date(now);
    startOfWeek.setHours(0,0,0,0);
    startOfWeek.setDate(now.getDate() - now.getDay());
    const baseFiltered = productionData.filter(e => {
      const matchesOp = dashOperator ? e.operator === dashOperator : true;
      const matchesMac = dashMachine ? e.machine === dashMachine : true;
      return matchesOp && matchesMac;
    });
    const results = { month: 0, today: 0, yesterday: 0, week: 0, range: 0, rangeCast1: 0, rangeCast2: 0 };
    baseFiltered.forEach(e => {
      if (dashStartDate || dashEndDate) {
        let inRange = true;
        if (dashStartDate && e.date < dashStartDate) inRange = false;
        if (dashEndDate && e.date > dashEndDate) inRange = false;
        if (inRange) {
          results.range += e.netWeight;
          if (e.machine === 'Cast 1') results.rangeCast1 += e.netWeight;
          if (e.machine === 'Cast 2') results.rangeCast2 += e.netWeight;
        }
      }
      if (e.date.startsWith(dashboardMonth)) results.month += e.netWeight;
      if (e.date === todayStr) results.today += e.netWeight;
      if (e.date === yesterdayStr) results.yesterday += e.netWeight;
      const entryDate = new Date(e.date + 'T00:00:00');
      if (entryDate >= startOfWeek) results.week += e.netWeight;
    });
    return results;
  }, [productionData, dashboardMonth, dashOperator, dashMachine, dashStartDate, dashEndDate]);

  const projection = useMemo(() => {
    const today = new Date();
    const lastDayOfMonth = new Date(today.getFullYear(), today.getMonth() + 1, 0).getDate();
    const currentDay = today.getDate();
    const daysRemaining = Math.max(1, lastDayOfMonth - currentDay + 1);
    const remainingToGoal = Math.max(0, goalValue - totals.month);
    const dailyTargetNeeded = remainingToGoal / daysRemaining;
    return { daysRemaining, remainingToGoal, dailyTargetNeeded };
  }, [totals.month, goalValue]);

  const stats = useMemo(() => {
    const initialStats: Record<string, OperatorStat> = {};
    operators.forEach(op => {
      initialStats[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
    });
    filteredDataForCharts.forEach(e => {
      if (!initialStats[e.operator]) {
        initialStats[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      }
      initialStats[e.operator].prod += (e.netWeight || 0);
      initialStats[e.operator].ecoA += (e.ecoA || 0);
      initialStats[e.operator].ecoBP += (e.ecoBP || 0);
      initialStats[e.operator].ecoBM += (e.ecoBM || 0);
      initialStats[e.operator].borra += (e.borraTotal || 0);
      initialStats[e.operator].p_manut += (e.manutencaoMin || 0);
      initialStats[e.operator].p_proc += (e.processoMin || 0);
      initialStats[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(initialStats);
  }, [filteredDataForCharts, operators]);

  const isRangeActive = !!(dashStartDate || dashEndDate);

  const allCharts = [
    { id: 'prod', title: '🏆 Produção Líquida', key: 'prod', color: COLORS, formatter: formatWeight, description: 'Distribuição da produção total de material acabado entre os operadores no período.' },
    { id: 'ecoA', title: '♻️ Eco A (KG)', key: 'ecoA', color: ['#10b981', '#34d399', '#6ee7b7'], formatter: formatWeight, description: 'Volume total de material reciclado do tipo Eco A gerado durante o processo.' },
    { id: 'ecoBP', title: '♻️ Eco B Produção', key: 'ecoBP', color: ['#3b82f6', '#60a5fa', '#93c5fd'], formatter: formatWeight, description: 'Resíduos tipo Eco B originados diretamente da operação normal das máquinas.' },
    { id: 'ecoBM', title: '♻️ Eco B Manutenção', key: 'ecoBM', color: ['#8b5cf6', '#a78bfa', '#c4b5fd'], formatter: formatWeight, description: 'Resíduos tipo Eco B gerados especificamente em processos de manutenção e ajuste.' },
    { id: 'borra', title: '🗑️ Borra Total', key: 'borra', color: ['#f43f5e', '#fb7185', '#fda4af'], formatter: formatWeight, description: 'Desperdício não reaproveitável (purga) gerado por cada operador/máquina.' },
    { id: 'p_manut', title: '⏱️ Paradas (Min)', key: 'p_manut', color: ['#ef4444', '#f59e0b', '#64748b'], formatter: formatMinutes, description: 'Tempo total em minutos que as máquinas ficaram inoperantes por diversos motivos.' },
    { id: 'comp_prod_ecob', title: '📊 Líquido vs Eco B', key: 'comparison_prod_ecob', color: ['#3b82f6', '#8b5cf6'], formatter: formatWeight, description: 'Comparação proporcional entre o material final produzido e o volume de Eco B gerado.' },
    { id: 'comp_ecob_rec', title: '📊 Eco B vs Reciclado', key: 'comparison_ecob_recycled', color: ['#f59e0b', '#10b981'], formatter: formatWeight, description: 'Análise entre o material de descarte (Eco B) gerado na extrusão e o volume recuperado pela Erema.' },
    { id: 'comp_prod_borra', title: '📊 Líquido vs Borra', key: 'comparison_prod_borra', color: ['#3b82f6', '#ef4444'], formatter: formatWeight, description: 'Análise de eficiência comparando o peso líquido produzido contra o desperdício total.' },
    { id: 'comp_time', title: '⏱️ Tempo Máquina (Min)', key: 'comparison_time', color: ['#3b82f6', '#ef4444'], formatter: formatMinutes, description: 'Indicador de disponibilidade: tempo de operação ativa vs tempo total de paradas.' }
  ];

  const visibleCharts = useMemo(() => {
    if (selectedChartId === null) return [];
    if (selectedChartId === 'all') return allCharts;
    return allCharts.filter(c => c.id === selectedChartId);
  }, [selectedChartId]);

  const handleSaveDashboardPDF = async () => {
    if (!dashboardRef.current || isGeneratingPDF) return;
    setIsGeneratingPDF(true);
    try {
      const canvas = await html2canvas(dashboardRef.current, { scale: 2, useCORS: true, backgroundColor: '#f8fafc' });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pageWidth = pdf.internal.pageSize.getWidth();
      const margin = 10;
      const contentWidth = pageWidth - (margin * 2);
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(18);
      pdf.text("Manupackaging - Controle de Produção", margin, 15);
      const imgProps = pdf.getImageProperties(imgData);
      const pdfImgHeight = (imgProps.height * contentWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', margin, 35, contentWidth, pdfImgHeight);
      pdf.save(`dashboard_producao_${dashboardMonth}.pdf`);
    } catch (error) { alert("Erro ao gerar PDF."); }
    finally { setIsGeneratingPDF(false); }
  };

  const handleDownloadChartPNG = async (id: string, title: string) => {
    const element = document.getElementById(id);
    if (!element) return;
    try {
      const canvas = await html2canvas(element, { scale: 3, backgroundColor: '#ffffff' });
      const url = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = url;
      link.download = `grafico_${title.replace(/\s/g, '_')}.png`;
      link.click();
    } catch (e) { alert("Erro ao salvar imagem."); }
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-slate-200/50 rounded-2xl w-fit">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Painel de Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios Analíticos</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-[100vw] mx-auto p-4 space-y-6 overflow-x-hidden">
        {activeTab === 'dashboard' ? (
          <div ref={dashboardRef} className="space-y-6 max-w-6xl mx-auto">
            <div className="bg-white rounded-3xl p-5 shadow-sm border border-slate-100 flex flex-wrap items-center gap-4 no-print">
              <div className="flex items-center gap-2 mr-2">
                <div className="w-8 h-8 bg-blue-50 text-blue-600 rounded-lg flex items-center justify-center"><Filter size={16} /></div>
                <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Filtros</span>
              </div>
              <div className="flex-1 min-w-[180px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Operador</label>
                <select value={dashOperator} onChange={(e) => setDashOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none">
                  <option value="">Todos os Operadores</option>
                  {operators.map(op => <option key={op} value={op}>{op}</option>)}
                </select>
              </div>
              <div className="flex-1 min-w-[180px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Máquina</label>
                <select value={dashMachine} onChange={(e) => setDashMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none">
                  <option value="">Todas as Máquinas</option>
                  {activeMachines.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="flex-1 min-w-[150px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Data Inicial</label>
                <input type="date" value={dashStartDate} onChange={(e) => setDashStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none" />
              </div>
              <div className="flex-1 min-w-[150px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Data Final</label>
                <input type="date" value={dashEndDate} onChange={(e) => setDashEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none" />
              </div>
              {(dashOperator || dashMachine || dashStartDate || dashEndDate) && (
                <button onClick={() => { setDashOperator(''); setDashMachine(''); setDashStartDate(''); setDashEndDate(''); }} className="self-end px-4 py-2.5 text-red-500 hover:bg-red-50 rounded-xl text-[10px] font-black uppercase">Limpar</button>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <button 
                onClick={() => setSelectedTimeframe('month')} 
                className={`flex flex-col p-6 rounded-2xl border transition-all duration-300 h-full ${ 
                  selectedTimeframe === 'month' 
                  ? 'bg-blue-600 border-blue-500 shadow-xl text-white' 
                  : 'bg-white border-slate-100 text-slate-800 shadow-sm' 
                }`}
              >
                <div className="flex items-center justify-between mb-4">
                  <div className={`p-3 rounded-xl ${selectedTimeframe === 'month' ? 'bg-white/20' : 'bg-blue-50 text-blue-600'}`}>
                    <Target size={24} />
                  </div>
                  <div className="text-right">
                    <span className={`text-[10px] font-black uppercase tracking-widest block ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>
                      Meta Mensal
                    </span>
                    <span className={`text-[9px] font-bold ${selectedTimeframe === 'month' ? 'text-blue-200' : 'text-slate-400'}`}>
                      Alvo: {formatWeight(goalValue)}
                    </span>
                  </div>
                </div>
                <div className="space-y-4">
                  <div>
                    <div className="text-2xl font-black leading-none mb-1">{formatWeight(totals.month)}</div>
                    <p className={`text-[9px] font-bold uppercase tracking-tighter ${selectedTimeframe === 'month' ? 'text-blue-200' : 'text-slate-400'}`}>Produzido até agora</p>
                  </div>
                  <div className="space-y-1.5">
                    <div className="w-full bg-black/10 h-2.5 rounded-full overflow-hidden border border-white/10">
                      <div className={`h-full transition-all duration-700 ${selectedTimeframe === 'month' ? 'bg-white' : 'bg-blue-500'}`} style={{ width: `${Math.min((totals.month / (goalValue || 1)) * 100, 100)}%` }}></div>
                    </div>
                    <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-tighter">
                      <span>{((totals.month / (goalValue || 1)) * 100).toFixed(1)}%</span>
                      <span>Faltam {formatWeight(projection.remainingToGoal)}</span>
                    </div>
                  </div>
                  <div className={`p-3 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/20' : 'bg-slate-50 border-slate-100'}`}>
                    <div className="flex justify-between items-center">
                      <div className="space-y-0.5">
                        <p className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'month' ? 'text-blue-200' : 'text-slate-400'}`}>Média p/ bater meta</p>
                        <p className="text-sm font-black">{formatWeight(projection.dailyTargetNeeded)}/dia</p>
                      </div>
                      <div className="text-right">
                        <p className={`text-[9px] font-black uppercase tracking-widest ${selectedTimeframe === 'month' ? 'text-blue-200' : 'text-slate-400'}`}>Dias Restantes</p>
                        <p className="text-sm font-black">{projection.daysRemaining} dias</p>
                      </div>
                    </div>
                  </div>
                  {isRangeActive && (
                    <div className="pt-2 border-t border-white/20">
                       <p className="text-[9px] font-black uppercase tracking-widest text-blue-200">Total no Filtro</p>
                       <p className="text-sm font-black">{formatWeight(totals.range)}</p>
                    </div>
                  )}
                </div>
              </button>
              <button onClick={() => setSelectedTimeframe('yesterday')} className={`flex flex-col p-6 rounded-2xl border transition-all duration-300 h-full ${ selectedTimeframe === 'yesterday' ? 'bg-emerald-600 border-emerald-500 shadow-xl text-white' : 'bg-white border-slate-100 text-slate-800 shadow-sm' }`}>
                <div className="flex items-center justify-between mb-4">
                  <div className={`p-3 rounded-xl ${selectedTimeframe === 'yesterday' ? 'bg-white/20' : 'bg-emerald-50 text-emerald-600'}`}>
                    {isRangeActive ? <Cpu size={24} /> : <TrendingUp size={24} />}
                  </div>
                  <span className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>
                    {isRangeActive ? 'Total Cast 1' : 'Ontem'}
                  </span>
                </div>
                <div className="space-y-3">
                  <div className="text-2xl font-black">{formatWeight(isRangeActive ? totals.rangeCast1 : totals.yesterday)}</div>
                  <p className="text-[9px] font-bold uppercase tracking-tighter opacity-80">{isRangeActive ? 'Produção Cast 1 no Período' : 'Produção do Dia Anterior'}</p>
                </div>
              </button>
              <button onClick={() => setSelectedTimeframe('week')} className={`flex flex-col p-6 rounded-2xl border transition-all duration-300 h-full ${ selectedTimeframe === 'week' ? 'bg-violet-600 border-violet-500 shadow-xl text-white' : 'bg-white border-slate-100 text-slate-800 shadow-sm' }`}>
                <div className="flex items-center justify-between mb-4">
                  <div className={`p-3 rounded-xl ${selectedTimeframe === 'week' ? 'bg-white/20' : 'bg-violet-50 text-violet-600'}`}>
                    {isRangeActive ? <Cpu size={24} /> : <CalendarDays size={24} />}
                  </div>
                  <span className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>
                    {isRangeActive ? 'Total Cast 2' : 'Esta Semana'}
                  </span>
                </div>
                <div className="space-y-3">
                  <div className="text-2xl font-black">{formatWeight(isRangeActive ? totals.rangeCast2 : totals.week)}</div>
                  <p className="text-[9px] font-bold uppercase tracking-tighter opacity-80">{isRangeActive ? 'Produção Cast 2 no Período' : 'Acumulado da Semana'}</p>
                </div>
              </button>
            </div>

            <div className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 space-y-4 no-print">
              <div className="relative group">
                <select value={selectedChartId || ''} onChange={(e) => setSelectedChartId(e.target.value === '' ? null : e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 text-xs font-black text-slate-700 outline-none appearance-none uppercase tracking-widest pr-12">
                  <option value="all">📊 Mostrar Todos os Gráficos</option>
                  {allCharts.map(chart => ( <option key={chart.id} value={chart.id}>{chart.title}</option> ))}
                  <option value="">Nenhum gráfico selecionado...</option>
                </select>
                <div className="absolute right-5 top-1/2 -translate-y-1/2 pointer-events-none text-slate-400"> <ChevronDown size={20} /> </div>
              </div>
            </div>

            <div className={`grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 transition-all duration-500 animate-in slide-in-from-bottom-4 ${selectedChartId !== 'all' ? 'lg:grid-cols-1 max-w-2xl mx-auto' : ''}`}>
              {visibleCharts.map((chart, idx) => {
                let chartData: any[] = [];
                let dataKey = chart.key;
                const isOperatorChart = !chart.key.startsWith('comparison_');
                if (chart.key === 'comparison_prod_ecob') {
                  const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                  const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                  chartData = [{ name: 'Produção', value: totalProd }, { name: 'Eco B', value: totalEcoB }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_prod_borra') {
                  const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                  const totalBorra = filteredDataForCharts.reduce((acc, c) => acc + (c.borraTotal || 0), 0);
                  chartData = [{ name: 'Produção', value: totalProd }, { name: 'Borra', value: totalBorra }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_ecob_recycled') {
                  const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                  const totalRecycled = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoA || 0), 0);
                  chartData = [{ name: 'Eco B', value: totalEcoB }, { name: 'Reciclado', value: totalRecycled }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_time') {
                  let totalAvailable = 0; let totalDowntime = 0;
                  filteredDataForCharts.forEach(item => { const shiftDuration = getShiftDuration(item.shift); totalAvailable += shiftDuration; totalDowntime += (item.manutencaoMin || 0) + (item.processoMin || 0) + (item.outrosMin || 0); });
                  const totalRunning = Math.max(0, totalAvailable - totalDowntime);
                  chartData = [{ name: 'Operação', value: totalRunning }, { name: 'Parada', value: totalDowntime }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else {
                  chartData = stats.filter(s => (s[chart.key as keyof OperatorStat] as number) > 0).sort((a, b) => (b[chart.key as keyof OperatorStat] as number) - (a[chart.key as keyof OperatorStat] as number));
                }
                const cardId = `chart-card-${idx}`;
                return (
                  <div key={idx} id={cardId} className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 min-h-[460px] flex flex-col group/card transition-all hover:shadow-xl">
                    <div className="flex justify-between items-start mb-4">
                      <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">{chart.title}</h3>
                      <button onClick={() => handleDownloadChartPNG(cardId, chart.title)} className="p-1.5 text-slate-300 hover:text-blue-600 no-print"> <ImageIcon size={16} /> </button>
                    </div>
                    <div className="flex-1">
                      {chartData.length > 0 ? (
                        <ResponsiveContainer width="100%" height="100%">
                          <PieChart>
                            <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} dataKey={isOperatorChart ? chart.key : dataKey} nameKey="name" label={renderCustomizedLabel} paddingAngle={2}>
                              {chartData.map((_, i) => <Cell key={i} fill={chart.color[i % chart.color.length]} />)}
                            </Pie>
                            <Tooltip formatter={(val: any) => chart.formatter(val)} />
