                 <p className="text-[10px] font-black uppercase tracking-widest text-blue-100">Meta Mensal</p>
                 <h2 className="text-3xl font-black mt-2">{formatWeight(totals.month)}</h2>
                 <p className="text-[11px] mt-1 opacity-80">Objetivo: {formatWeight(goalValue)}</p>
                 <div className="mt-4 w-full bg-white/20 h-2 rounded-full overflow-hidden">
                    <div className="bg-white h-full" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
              </div>
              <div className="p-6 bg-emerald-600 rounded-3xl text-white shadow-xl">
                 <p className="text-[10px] font-black uppercase tracking-widest text-emerald-100">Produção Ontem</p>
                 <h2 className="text-3xl font-black mt-2">{formatWeight(totals.yesterday)}</h2>
                 <p className="text-[11px] mt-1 opacity-80">Acumulado diário</p>
              </div>
              <div className="p-6 bg-violet-600 rounded-3xl text-white shadow-xl">
                 <p className="text-[10px] font-black uppercase tracking-widest text-violet-100">Produção Semanal</p>
                 <h2 className="text-3xl font-black mt-2">{formatWeight(totals.week)}</h2>
                 <p className="text-[11px] mt-1 opacity-80">Últimos 7 dias</p>
              </div>
