    operators.forEach(op => {
      initialStats[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
    });
    filteredDataForCharts.forEach(e => {
      if (!initialStats[e.operator]) {
        initialStats[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      }
      initialStats[e.operator].prod += (e.netWeight || 0);
      initialStats[e.operator].ecoA += (e.ecoA || 0);
      initialStats[e.operator].ecoBP += (e.ecoBP || 0);
      initialStats[e.operator].ecoBM += (e.ecoBM || 0);
      initialStats[e.operator].borra += (e.borraTotal || 0);
      initialStats[e.operator].p_manut += (e.manutencaoMin || 0);
      initialStats[e.operator].p_proc += (e.processoMin || 0);
      initialStats[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(initialStats);
  }, [filteredDataForCharts, operators]);

  const allCharts = [
    { id: 'prod', title: '🏆 Produção Líquida', key: 'prod', color: COLORS, formatter: formatWeight, description: 'Distribuição da produção total de material acabado por operador.' },
    { id: 'ecoA', title: '♻️ Eco A (KG)', key: 'ecoA', color: ['#10b981', '#34d399', '#6ee7b7'], formatter: formatWeight, description: 'Volume total de material reciclado Eco A gerado.' },
    { id: 'ecoBP', title: '♻️ Eco B Produção', key: 'ecoBP', color: ['#3b82f6', '#60a5fa', '#93c5fd'], formatter: formatWeight, description: 'Resíduos Eco B originados do processo produtivo.' },
    { id: 'ecoBM', title: '♻️ Eco B Manutenção', key: 'ecoBM', color: ['#8b5cf6', '#a78bfa', '#c4b5fd'], formatter: formatWeight, description: 'Resíduos Eco B originados de manutenções e ajustes.' },
    { id: 'borra', title: '🗑️ Borra Total', key: 'borra', color: ['#f43f5e', '#fb7185', '#fda4af'], formatter: formatWeight, description: 'Desperdício não reaproveitável (purga) gerado.' },
    { id: 'p_manut', title: '⏱️ Paradas (Min)', key: 'p_manut', color: ['#ef4444', '#f59e0b', '#64748b'], formatter: formatMinutes, description: 'Tempo total de máquinas inativas por operador.' },
    { id: 'comp_prod_ecob', title: '📊 Líquido vs Eco B', key: 'comparison_prod_ecob', color: ['#3b82f6', '#8b5cf6'], formatter: formatWeight, description: 'Proporção entre material final e resíduos Eco B.' },
    { id: 'comp_ecob_rec', title: '📊 Eco B vs Reciclado', key: 'comparison_ecob_recycled', color: ['#f59e0b', '#10b981'], formatter: formatWeight, description: 'Volume de resíduos gerados vs volume recuperado (Erema).' },
    { id: 'comp_prod_borra', title: '📊 Líquido vs Borra', key: 'comparison_prod_borra', color: ['#3b82f6', '#ef4444'], formatter: formatWeight, description: 'Análise de rendimento vs desperdício total.' },
    { id: 'comp_time', title: '⏱️ Tempo Máquina (Min)', key: 'comparison_time', color: ['#3b82f6', '#ef4444'], formatter: formatMinutes, description: 'Relação entre tempo de operação ativa e tempo de paradas.' }
  ];

  const handleSaveDashboardPDF = async () => {
    if (!dashboardRef.current || isGeneratingPDF) return;
    setIsGeneratingPDF(true);
    try {
      const canvas = await html2canvas(dashboardRef.current, { scale: 2, useCORS: true, backgroundColor: '#f8fafc' });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pageWidth = pdf.internal.pageSize.getWidth();
      const margin = 10;
      const contentWidth = pageWidth - (margin * 2);
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(18);
      pdf.text("Manupackaging - Controle de Produção", margin, 15);
      const imgProps = pdf.getImageProperties(imgData);
      const pdfImgHeight = (imgProps.height * contentWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', margin, 35, contentWidth, pdfImgHeight);
      pdf.save(`dashboard_producao_${dashboardMonth}.pdf`);
    } catch (error) { alert("Erro ao gerar PDF."); }
    finally { setIsGeneratingPDF(false); }
  };

  const handleDownloadChartPNG = async (id: string, title: string) => {
    const element = document.getElementById(id);
    if (!element) return;
    try {
      const canvas = await html2canvas(element, { scale: 3, backgroundColor: '#ffffff' });
      const url = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = url;
      link.download = `grafico_${title.replace(/\s/g, '_')}.png`;
      link.click();
    } catch (e) { alert("Erro ao salvar imagem."); }
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
  }

  const isGoalReached = totals.month >= goalValue;

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-slate-200/50 rounded-2xl w-fit">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' ? (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            <div className="bg-white rounded-3xl p-5 shadow-sm border border-slate-100 flex flex-wrap items-center gap-4 no-print">
              <div className="flex-1 min-w-[180px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Operador</label>
                <select value={dashOperator} onChange={(e) => setDashOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none">
                  <option value="">Todos</option>
                  {operators.map(op => <option key={op} value={op}>{op}</option>)}
                </select>
              </div>
              <div className="flex-1 min-w-[180px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Máquina</label>
                <select value={dashMachine} onChange={(e) => setDashMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none">
                  <option value="">Todas</option>
                  {activeMachines.map(m => <option key={m} value={m}>{m}</option>)}
                </select>
              </div>
              <div className="flex-1 min-w-[150px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Data Inicial</label>
                <input type="date" value={dashStartDate} onChange={(e) => setDashStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none" />
              </div>
              <div className="flex-1 min-w-[150px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Data Final</label>
                <input type="date" value={dashEndDate} onChange={(e) => setDashEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none" />
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <button 
                onClick={() => setSelectedTimeframe('month')} 
                className={`p-6 rounded-3xl text-left transition-all relative overflow-hidden ${
                  selectedTimeframe === 'month' 
                    ? (isGoalReached ? 'bg-blue-600 animate-goal-reached' : 'bg-blue-600') 
                    : 'bg-white border border-slate-100'
                } ${selectedTimeframe === 'month' ? 'text-white shadow-xl' : 'text-slate-800'}`}
              >
                 {isGoalReached && <div className="absolute top-2 right-2 text-white/40"><Target size={40} /></div>}
                 <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Meta Mensal {isGoalReached && '🏆'}</p>
                 <h2 className="text-3xl font-black mt-2">{formatWeight(totals.month)}</h2>

                 <div className="flex justify-between items-end mt-1">
                   <div className="flex flex-col">
                     <p className="text-[11px] opacity-80 font-bold">Objetivo: {formatWeight(goalValue)}</p>
                     {!isGoalReached && <p className={`text-[10px] font-black uppercase mt-1 ${selectedTimeframe === 'month' ? 'text-white' : 'text-red-600'}`}>Falta: {formatWeight(totals.remaining)}</p>}
                   </div>
                   <div className="flex flex-col items-end">
                     {!isGoalReached && <p className={`text-[8px] font-black uppercase opacity-90 ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-500'}`}>Média Nec: {formatWeight(totals.dailyRequired)}/dia</p>}
                   </div>
                 </div>

                 <div className={`mt-4 w-full h-2 rounded-full overflow-hidden ${selectedTimeframe === 'month' ? 'bg-white/20' : 'bg-slate-100'}`}>
                    <div className={`${selectedTimeframe === 'month' ? 'bg-white' : 'bg-blue-600'} h-full transition-all duration-1000`} style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
              </button>

              <button onClick={() => setSelectedTimeframe('yesterday')} className={`p-6 rounded-3xl text-left transition-all ${selectedTimeframe === 'yesterday' ? 'bg-emerald-600 text-white shadow-xl' : 'bg-white border border-slate-100 text-slate-800'}`}>
                 <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>Produção Ontem</p>
                 <h2 className="text-3xl font-black mt-2">{formatWeight(totals.yesterday)}</h2>
                 <p className="text-[11px] mt-1 opacity-80 font-bold">Acumulado diário</p>
              </button>

              <button onClick={() => setSelectedTimeframe('week')} className={`p-6 rounded-3xl text-left transition-all ${selectedTimeframe === 'week' ? 'bg-violet-600 text-white shadow-xl' : 'bg-white border border-slate-100 text-slate-800'}`}>
                 <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>Produção Semanal</p>
                 <h2 className="text-3xl font-black mt-2">{formatWeight(totals.week)}</h2>
                 <p className="text-[11px] mt-1 opacity-80 font-bold">Últimos 7 dias</p>
              </button>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allCharts.map((chart, idx) => {
                let chartData: any[] = [];
                let dataKey = chart.key;
                const isOperatorChart = !chart.key.startsWith('comparison_');

                if (chart.key === 'comparison_prod_ecob') {
                  const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                  const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                  chartData = [{ name: 'Produção', value: totalProd }, { name: 'Eco B', value: totalEcoB }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_prod_borra') {
                  const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                  const totalBorra = filteredDataForCharts.reduce((acc, c) => acc + (c.borraTotal || 0), 0);
                  chartData = [{ name: 'Produção', value: totalProd }, { name: 'Borra', value: totalBorra }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_ecob_recycled') {
                  const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                  const totalRecycled = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoA || 0), 0);
                  chartData = [{ name: 'Eco B', value: totalEcoB }, { name: 'Reciclado', value: totalRecycled }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_time') {
                  let totalAvailable = 0; let totalDowntime = 0;
                  filteredDataForCharts.forEach(item => { const shiftDuration = getShiftDuration(item.shift); totalAvailable += shiftDuration; totalDowntime += (item.manutencaoMin || 0) + (item.processoMin || 0) + (item.outrosMin || 0); });
                  const totalRunning = Math.max(0, totalAvailable - totalDowntime);
                  chartData = [{ name: 'Operação', value: totalRunning }, { name: 'Parada', value: totalDowntime }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else {
                  chartData = stats.filter(s => (s[chart.key as keyof OperatorStat] as number) > 0).map(s => ({
                    ...s,
                    value: s[chart.key as keyof OperatorStat]
                  }));
                }

                if (chartData.length === 0) return null;
                const cardId = `chart-card-${idx}`;
                return (
                  <div key={idx} id={cardId} className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 h-[520px] flex flex-col group/card hover:shadow-xl transition-all">
                    <div className="flex justify-between items-start mb-2">
                      <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">{chart.title}</h3>
                      <button onClick={() => handleDownloadChartPNG(cardId, chart.title)} className="p-1.5 text-slate-300 hover:text-blue-600 no-print"> <ImageIcon size={16} /> </button>
                    </div>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wider mb-4 leading-tight">{chart.description}</p>
                    <div className="flex-1">
                       <ResponsiveContainer width="100%" height="100%">
                         <PieChart>
                           <Pie data={chartData} cx="50%" cy="50%" innerRadius={60} outerRadius={85} dataKey={isOperatorChart ? chart.key : dataKey} nameKey="name" label={renderCustomizedLabel} paddingAngle={2}>
                             {chartData.map((_, i) => <Cell key={i} fill={chart.color[i % chart.color.length]} />)}
                           </Pie>
                           <Tooltip formatter={(v: any) => chart.formatter(v)} />
                           <Legend 
                            iconType="circle" 
                            align="center" 
                            verticalAlign="bottom" 
                            formatter={(value, entry: any) => {
                              const val = entry.payload.value;
                              return <span className="text-slate-700">{value}: <span className="font-black">{chart.formatter(val)}</span></span>;
                            }}
                            wrapperStyle={{ fontSize: '10px', paddingTop: '20px' }} 
                          />
                         </PieChart>
                       </ResponsiveContainer>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        ) : (
          <div className="bg-white rounded-3xl shadow-sm border border-slate-100 overflow-hidden animate-in fade-in duration-300">
            <div className="p-4 border-b border-slate-100 flex flex-wrap items-center justify-between gap-4">
               <div className="relative flex-1 min-w-[300px]">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                 <input type="text" value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} placeholder="Pesquisar..." className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-xs font-bold outline-none" />
               </div>
               <div className="flex items-center gap-2">
                 {selectedIds.length > 0 && (
                   <button onClick={handleBulkDelete} className="px-4 py-3 bg-red-600 text-white rounded-2xl text-[10px] font-black uppercase flex items-center gap-2 animate-in fade-in zoom-in duration-200 shadow-lg shadow-red-200 hover:bg-red-700 transition-all">
                      <Trash2 size={16}/> Excluir ({selectedIds.length})
                   </button>
                 )}
                 <button onClick={handleExportCSV} className="px-4 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase flex items-center gap-2"><FileSpreadsheet size={16}/> CSV</button>
                 <button onClick={() => window.print()} className="p-3 bg-slate-800 text-white rounded-2xl"><Printer size={18}/></button>
               </div>
            </div>
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-6 py-4 w-12 text-center">
                      <input 
                        type="checkbox" 
                        checked={filteredReports.length > 0 && filteredReports.every(r => selectedIds.includes(r.id))}
                        onChange={handleSelectAll}
                        className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                      />
                    </th>
                    <th className="px-6 py-4">Data</th>
                    <th className="px-6 py-4">Operador</th>
                    <th className="px-6 py-4">Máquina</th>
                    <th className="px-6 py-4 text-right">Bruto (Kg)</th>
                    <th className="px-6 py-4 text-right">Líquido (Kg)</th>
                    <th className="px-6 py-4 text-right">Eco A</th>
                    <th className="px-6 py-4 text-right">Paradas (Min)</th>
                    <th className="px-6 py-4 text-right no-print">Ações</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-xs font-bold">
                  {filteredReports.map((e) => (
                    <tr key={e.id} className={`hover:bg-slate-50 transition-colors ${selectedIds.includes(e.id) ? 'bg-blue-50/50' : ''}`}>
                      <td className="px-6 py-4 text-center">
                        <input 
                          type="checkbox" 
                          checked={selectedIds.includes(e.id)}
                          onChange={() => handleSelectOne(e.id)}
                          className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                        />
                      </td>
                      <td className="px-6 py-4">{e.date}</td>
                      <td className="px-6 py-4">{e.operator}</td>
                      <td className="px-6 py-4 uppercase font-black text-slate-500">{e.machine}</td>
                      <td className="px-6 py-4 text-right">{e.grossWeight}</td>
                      <td className="px-6 py-4 text-right text-blue-600 font-black">{e.netWeight}</td>
                      <td className="px-6 py-4 text-right text-emerald-600">{e.ecoA}</td>
                      <td className="px-6 py-4 text-right text-red-500">{e.manutencaoMin + e.processoMin + e.outrosMin}</td>
                      <td className="px-6 py-4 text-right no-print">
                        <div className="flex justify-end gap-2">
                          <button onClick={() => {setEditingEntry(e); setIsModalOpen(true);}} className="p-2 text-blue-500 hover:bg-blue-50 rounded-lg"><Edit2 size={14}/></button>
                          <button onClick={() => handleDeleteReportItem(e.id)} className="p-2 text-red-500 hover:bg-red-50 rounded-lg"><Trash2 size={14}/></button>
                        </div>
                      </td>
                    </tr>
                  ))}
                  <tr className="bg-slate-800 text-white font-black">
                    <td colSpan={4} className="px-6 py-4 text-right uppercase">Totais:</td>
                    <td className="px-6 py-4 text-right">{reportSums.grossWeight}</td>
                    <td className="px-6 py-4 text-right text-blue-400">{reportSums.netWeight}</td>
                    <td className="px-6 py-4 text-right text-emerald-400">{reportSums.ecoA}</td>
                    <td className="px-6 py-4 text-right text-red-400">{reportSums.manutencaoMin + reportSums.processoMin + reportSums.outrosMin}</td>
                    <td className="no-print"></td>
                  </tr>
                </tbody>
              </table>
            </div>
          </div>
        )}
      </main>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
          <div className="relative w-85 bg-white shadow-2xl p-0 flex flex-col h-full animate-in slide-in-from-right duration-300">
            <div className="bg-[#1e293b] p-8 text-white">
              <h2 className="text-xl font-black uppercase tracking-tighter flex items-center gap-3"><Settings size={26} className="text-blue-500" /> Configurações</h2>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Meta Mensal (KG)</label>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-100 p-4 rounded-2xl font-black text-blue-600 outline-none" />
              </div>
              <div className="grid grid-cols-1 gap-3">
                <button onClick={() => { setIsOperatorModalOpen(true); setIsMenuOpen(false); }} className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-blue-50 text-slate-700 rounded-2xl text-[10px] font-black uppercase transition-all">
                   <span>Gerenciar Equipe</span>
                   <ChevronRight size={16}/>
                </button>
              </div>
              <div className="pt-4 border-t border-slate-100 space-y-3">
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 p-4 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase hover:bg-emerald-100 transition-all"><Upload size={18}/> Importar Backup</button>
                 <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
                 <button onClick={handleExportBackup} className="w-full flex items-center gap-3 p-4 bg-blue-50 text-blue-700 rounded-2xl text-[10px] font-black uppercase hover:bg-blue-100 transition-all"><Download size={18}/> Exportar Backup</button>
                 <button onClick={handleResetSystem} className="w-full flex items-center gap-3 p-4 bg-red-50 text-red-700 rounded-2xl text-[10px] font-black uppercase hover:bg-red-100 transition-all"><RotateCcw size={18}/> Resetar Sistema</button>
              </div>
              <button onClick={handleSaveDashboardPDF} className="w-full p-4 bg-slate-800 hover:bg-black text-white rounded-2xl text-[10px] font-black uppercase transition-all flex items-center justify-center gap-3 shadow-xl shadow-slate-200">
                <FileDown size={18} /> Exportar Dashboard PDF
              </button>
            </div>
            <div className="p-6 bg-slate-50 border-t border-slate-100">
              <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full p-4 bg-white border border-red-100 text-red-600 rounded-2xl text-[10px] font-black uppercase flex items-center justify-center gap-2 hover:bg-red-50 transition-all">
                <LogOut size={16}/> Sair do Sistema
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmDialog.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-3xl p-8 w-full max-w-sm shadow-2xl space-y-6">
            <div className="flex flex-col items-center text-center space-y-4">
