                    <div key={idx} className="grid grid-cols-2 gap-3">
                      {machine.shifts.map((shift, sIdx) => {
                         const isNight = shift.name.toLowerCase().includes('noturno');
                         return (
                           <div key={sIdx} className={`flex flex-col gap-2 p-3 rounded-2xl border ${isNight ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-100'}`}>
                              <div className={`${isNight ? 'bg-slate-700 border-slate-600' : 'bg-white border-slate-200'} p-1.5 rounded-xl border w-full`}>
                                <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest block text-center">Turno</span>
                                <span className={`text-[10px] font-black uppercase block text-center ${isNight ? 'text-white' : 'text-slate-700'}`}>{shift.name}</span>
                              </div>
                              <div className="flex flex-col items-center">
                                <span className={`text-xs font-bold ${isNight ? 'text-slate-200' : 'text-slate-800'}`}>{shift.team[0]}</span>
                                <span className="text-[9px] text-blue-500 font-bold uppercase">Operador</span>
                              </div>
                           </div>
                         );
                      })}
                    </div>
                  ))}
                </div>
              </div>

              {/* Fita Adesiva */}
              <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
                <div className="bg-orange-900 p-4 text-white flex items-center justify-between">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 bg-orange-500/20 rounded-xl flex items-center justify-center text-orange-400 border border-orange-500/10">
                      <Layers size={20} />
                    </div>
                    <div>
                      <h2 className="text-sm font-black uppercase tracking-tighter">Setor: Fita Adesiva</h2>
                      <p className="text-[9px] text-orange-300/60 font-bold uppercase tracking-widest">Ghezzi, Lintech & Wutec</p>
                    </div>
                  </div>
                </div>
                <div className="p-4 grid grid-cols-2 gap-3">
                   {PERSONNEL_DATA.fitaAdesiva.map((machine, idx) => (
                      <div key={idx} className="bg-slate-50 rounded-2xl p-3 border border-slate-200">
                         <h3 className="text-xs font-black text-slate-700 uppercase mb-3 flex items-center gap-2">
                           <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div> {machine.name}
                         </h3>
                         <div className="space-y-2">
                            {machine.shifts.map((shift, sIdx) => {
                               const isNight = shift.name.toLowerCase().includes('noturno');
                               return (
                                 <div key={sIdx} className={`p-2 rounded-xl border ${isNight ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
                                    <div className={`text-[9px] font-black uppercase tracking-widest mb-1.5 border-b pb-1 ${isNight ? 'text-slate-400 border-slate-700' : 'text-slate-400 border-slate-50'}`}>{shift.name}</div>
                                    <div className="space-y-1">
                                      {shift.team.map((person, pIdx) => {
                                        const role = getRole(machine.name, pIdx);
                                        return (
                                          <div key={pIdx} className="flex justify-between items-center">
                                            <span className={`text-[10px] font-bold ${isNight ? 'text-slate-200' : 'text-slate-700'}`}>{person}</span>
                                            <span className={`text-[8px] font-black px-1 py-0.5 rounded uppercase ${
                                              role === 'Operador' 
                                                ? (isNight ? 'bg-blue-900/40 text-blue-300' : 'bg-blue-50 text-blue-600') 
                                                : (isNight ? 'bg-orange-900/40 text-orange-300' : 'bg-orange-50 text-orange-600')
                                            }`}>{role.substring(0,3)}</span>
                                          </div>
                                        )
                                      })}
                                    </div>
                                 </div>
                               );
                            })}
                         </div>
                      </div>
                   ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
          <div className="relative w-85 bg-white shadow-2xl p-0 flex flex-col h-full animate-in slide-in-from-right duration-300">
            <div className="bg-[#1e293b] p-8 text-white">
              <h2 className="text-xl font-black uppercase tracking-tighter flex items-center gap-3"><Settings size={26} className="text-blue-500" /> Configurações</h2>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Meta Mensal (KG)</label>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-100 p-4 rounded-2xl font-black text-blue-600 outline-none" />
              </div>
              <div className="grid grid-cols-1 gap-3">
                <button onClick={() => { setIsOperatorModalOpen(true); setIsMenuOpen(false); }} className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-blue-50 text-slate-700 rounded-2xl text-[10px] font-black uppercase transition-all">
                   <span>Gerenciar Equipe</span>
                   <ChevronRight size={16}/>
                </button>
              </div>
              <div className="pt-4 border-t border-slate-100 space-y-3">
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 p-4 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase hover:bg-emerald-100 transition-all"><Upload size={18}/> Importar Backup</button>
                 <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
                 <button onClick={handleExportBackup} className="w-full flex items-center gap-3 p-4 bg-blue-50 text-blue-700 rounded-2xl text-[10px] font-black uppercase hover:bg-blue-100 transition-all"><Download size={18}/> Exportar Backup</button>
                 <button onClick={handleResetSystem} className="w-full flex items-center gap-3 p-4 bg-red-50 text-red-700 rounded-2xl text-[10px] font-black uppercase hover:bg-red-100 transition-all"><RotateCcw size={18}/> Resetar Sistema</button>
              </div>
              <button onClick={handleSaveDashboardPDF} className="w-full p-4 bg-slate-800 hover:bg-black text-white rounded-2xl text-[10px] font-black uppercase transition-all flex items-center justify-center gap-3 shadow-xl shadow-slate-200">
                <FileDown size={18} /> Exportar Dashboard PDF
              </button>
            </div>
            <div className="p-6 bg-slate-50 border-t border-slate-100">
              <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full p-4 bg-white border border-red-100 text-red-600 rounded-2xl text-[10px] font-black uppercase flex items-center justify-center gap-2 hover:bg-red-50 transition-all">
                <LogOut size={16}/> Sair do Sistema
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmDialog.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-3xl p-8 w-full max-w-sm shadow-2xl space-y-6">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="w-16 h-16 bg-red-100 text-red-600 rounded-2xl flex items-center justify-center"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">{confirmDialog.title}</h3>
              <p className="text-slate-500 text-sm font-medium">{confirmDialog.message}</p>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setConfirmDialog(prev => ({...prev, isOpen: false}))} className="flex-1 px-4 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-[10px] uppercase hover:bg-slate-200 transition-all">Cancelar</button>
              <button onClick={confirmDialog.onConfirm} className="flex-1 px-4 py-3 bg-red-600 text-white rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-red-700 transition-all">Confirmar</button>
            </div>
          </div>
        </div>
      )}

      <LaunchModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} availableShifts={shifts} initialData={editingEntry} />
      <OperatorModal isOpen={isOperatorModalOpen} onClose={() => setIsOperatorModalOpen(false)} operators={operators} onUpdate={setOperators} />
      <ShiftModal isOpen={isShiftModalOpen} onClose={() => setIsShiftModalOpen(false)} onSave={(newShift) => setShifts(prev => [...prev, { ...newShift, id: Math.random().toString(36).substr(2, 9) }])} />
    </div>
  );
};

export default App;

