  const [dashOperator, setDashOperator] = useState('');
  const [dashMachine, setDashMachine] = useState('');
  const [dashStartDate, setDashStartDate] = useState('');
  const [dashEndDate, setDashEndDate] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      let data = saved ? JSON.parse(saved) : INITIAL_DATA;
      if (Array.isArray(data)) {
        return data.map((item: any) => ({
          ...item,
          id: item.id || Math.random().toString(36).substr(2, 9)
        }));
      }
      return INITIAL_DATA;
    } catch (e) {
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_operators');
      return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
    } catch (e) {
      return DEFAULT_OPERATORS;
    }
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_shifts');
      return saved ? JSON.parse(saved) : [
        { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '5', name: 'Comercial', startTime: '08:00', endTime: '18:00', type: 'Diurno' }
      ];
    } catch (e) {
      return [
        { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' }
      ];
    }
  });

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec'];

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_shifts', JSON.stringify(shifts)); }, [shifts]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_active_tab', activeTab); }, [activeTab]);
  useEffect(() => { localStorage.setItem('manupackaging_timeframe', selectedTimeframe); }, [selectedTimeframe]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);
  const [isOperatorModalOpen, setIsOperatorModalOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleSaveEntry = (newEntry: Omit<ProductionEntry, 'id'> & { id?: string }) => {
    if (newEntry.id) {
      setProductionData(prev => prev.map(e => e.id === newEntry.id ? (newEntry as ProductionEntry) : e));
    } else {
      setProductionData(prev => [{ ...newEntry, id: Math.random().toString(36).substr(2, 9) } as ProductionEntry, ...prev]);
    }
  };

  const handleDeleteReportItem = (id: string) => {
    if (!id) return;
    setConfirmDialog({
      isOpen: true,
      title: 'Excluir Registro',
      message: 'Tem certeza que deseja excluir permanentemente este registro de produção?',
      onConfirm: () => {
        setProductionData(prev => prev.filter(item => item.id !== id));
        setConfirmDialog(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const handleSelectAll = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.checked) {
      const visibleIds = filteredReports.map(r => r.id);
      setSelectedIds(prev => Array.from(new Set([...prev, ...visibleIds])));
    } else {
      const visibleIds = filteredReports.map(r => r.id);
      setSelectedIds(prev => prev.filter(id => !visibleIds.includes(id)));
    }
  };

  const handleSelectOne = (id: string) => {
    setSelectedIds(prev => 
      prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]
    );
  };

  const handleBulkDelete = () => {
    if (selectedIds.length === 0) return;
    setConfirmDialog({
      isOpen: true,
      title: 'Excluir Selecionados',
      message: `Tem certeza que deseja excluir ${selectedIds.length} registros selecionados?`,
      onConfirm: () => {
        setProductionData(prev => prev.filter(item => !selectedIds.includes(item.id)));
        setSelectedIds([]);
        setConfirmDialog(prev => ({ ...prev, isOpen: false }));
      }
    });
  };

  const handleExportBackup = () => {
    const backup = {
      productionData,
      goalValue,
      shifts,
      operators,
      version: '1.0.0',
      exportedAt: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `backup_manupackaging_${new Date().toLocaleDateString('sv-SE')}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    const dataToExport = filteredReports;
    if (dataToExport.length === 0) {
      alert('Nenhum dado para exportar.');
      return;
    }
    const headers = ['Data', 'Operador', 'Máquina', 'Turno', 'Peso Bruto', 'Tara', 'Peso Líquido', 'Volumes', 'Tubetes', 'Eco A', 'Eco B (P)', 'Eco B (M)', 'Borra Total', 'Manutencao (min)', 'Processo (min)', 'Outros (min)'];
    const rows = dataToExport.map(e => [e.date, `"${e.operator}"`, `"${e.machine}"`, `"${e.shift}"`, e.grossWeight, e.tara, e.netWeight, e.volumes, e.tubetes, e.ecoA, e.ecoBP, e.ecoBM, e.borraTotal, e.manutencaoMin, e.processoMin, e.outrosMin]);
    const csvContent = [headers.join(','), ...rows.map(row => row.join(','))].join('\n');
    const blob = new Blob(["\ufeff" + csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `producao_manupackaging_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (data.productionData) setProductionData(data.productionData);
        if (data.goalValue) setGoalValue(Number(data.goalValue));
        if (data.shifts) setShifts(data.shifts);
        if (data.operators) setOperators(data.operators);
        alert('Backup carregado com sucesso!');
      } catch (err) {
        alert('Erro ao processar o arquivo de backup.');
      }
    };
    reader.readAsText(file);
  };

  const handleResetSystem = () => {
    setConfirmDialog({
      isOpen: true,
      title: 'Resetar Sistema',
      message: 'ATENÇÃO: Isso apagará todos os dados de produção, turnos e equipe, restaurando o sistema para as configurações originais. Esta ação não pode ser desfeita!',
      onConfirm: () => {
        localStorage.clear();
        window.location.reload();
      }
    });
  };

  const formatWeight = (val: number) => {
    if (val >= 1000) {
      return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    }
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const getShiftDuration = (shiftName: string) => {
    const shift = shifts.find(s => s.name === shiftName);
    if (!shift) return 720;
    const [h1, m1] = shift.startTime.split(':').map(Number);
    const [h2, m2] = shift.endTime.split(':').map(Number);
    let minutes = (h2 * 60 + m2) - (h1 * 60 + m1);
    if (minutes < 0) minutes += 1440;
    return minutes === 0 ? 1440 : minutes;
  };

  const totals = useMemo(() => {
    const now = new Date();
    const todayStr = now.toLocaleDateString('sv-SE');
    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');
    const startOfWeek = new Date(now);
    startOfWeek.setHours(0,0,0,0);
    startOfWeek.setDate(now.getDate() - now.getDay());

    const currentYear = parseInt(dashboardMonth.split('-')[0]);
    const currentMonth = parseInt(dashboardMonth.split('-')[1]) - 1;
    const isCurrentMonth = now.getFullYear() === currentYear && now.getMonth() === currentMonth;
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const currentDay = isCurrentMonth ? now.getDate() : daysInMonth;

    const baseFiltered = productionData.filter(e => {
      const matchesOp = dashOperator ? e.operator === dashOperator : true;
      const matchesMac = dashMachine ? e.machine === dashMachine : true;
      return matchesOp && matchesMac;
    });

    const results = { 
      month: 0, 
      today: 0, 
      yesterday: 0, 
      week: 0, 
      range: 0, 
      projection: 0,
      remaining: 0,
      dailyRequired: 0
    };

    baseFiltered.forEach(e => {
      if (e.date.startsWith(dashboardMonth)) results.month += (e.netWeight || 0);
      if (e.date === todayStr) results.today += (e.netWeight || 0);
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
      const entryDate = new Date(e.date + 'T00:00:00');
      if (entryDate >= startOfWeek) results.week += (e.netWeight || 0);
    });

    results.projection = currentDay > 0 ? (results.month / currentDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);

    const daysRemaining = Math.max(0, daysInMonth - currentDay);
    results.dailyRequired = daysRemaining > 0 ? results.remaining / daysRemaining : results.remaining;

    return results;
  }, [productionData, dashboardMonth, dashOperator, dashMachine, goalValue]);

  const filteredDataForCharts = useMemo(() => {
    return productionData.filter(e => {
      const matchesOp = dashOperator ? e.operator === dashOperator : true;
      const matchesMac = dashMachine ? e.machine === dashMachine : true;
      const matchesStart = dashStartDate ? e.date >= dashStartDate : true;
      const matchesEnd = dashEndDate ? e.date <= dashEndDate : true;
      const matchesMonth = !dashStartDate && !dashEndDate ? e.date.startsWith(dashboardMonth) : true;
      return matchesOp && matchesMac && matchesStart && matchesEnd && matchesMonth;
    });
  }, [productionData, dashOperator, dashMachine, dashStartDate, dashEndDate, dashboardMonth]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const matchesSearch = searchTerm 
        ? Object.values(e).some(val => String(val).toLowerCase().includes(searchTerm.toLowerCase()))
        : true;
      const matchesStart = filterStartDate ? e.date >= filterStartDate : true;
      const matchesEnd = filterEndDate ? e.date <= filterEndDate : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportSums = useMemo(() => {
    return filteredReports.reduce((acc, curr) => ({
      grossWeight: acc.grossWeight + (curr.grossWeight || 0),
      netWeight: acc.netWeight + (curr.netWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      manutencaoMin: acc.manutencaoMin + (curr.manutencaoMin || 0),
      processoMin: acc.processoMin + (curr.processoMin || 0),
      outrosMin: acc.outrosMin + (curr.outrosMin || 0),
    }), { grossWeight: 0, netWeight: 0, ecoA: 0, manutencaoMin: 0, processoMin: 0, outrosMin: 0 });
  }, [filteredReports]);

  const stats = useMemo(() => {
    const initialStats: Record<string, OperatorStat> = {};
    operators.forEach(op => {
      initialStats[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
    });
    filteredDataForCharts.forEach(e => {
      if (!initialStats[e.operator]) {
        initialStats[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      }
      initialStats[e.operator].prod += (e.netWeight || 0);
      initialStats[e.operator].ecoA += (e.ecoA || 0);
      initialStats[e.operator].ecoBP += (e.ecoBP || 0);
      initialStats[e.operator].ecoBM += (e.ecoBM || 0);
      initialStats[e.operator].borra += (e.borraTotal || 0);
      initialStats[e.operator].p_manut += (e.manutencaoMin || 0);
      initialStats[e.operator].p_proc += (e.processoMin || 0);
      initialStats[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(initialStats);
  }, [filteredDataForCharts, operators]);

  const allCharts = [
    { id: 'prod', title: '🏆 Produção Líquida', key: 'prod', color: COLORS, formatter: formatWeight, description: 'Distribuição da produção total de material acabado por operador.' },
    { id: 'ecoA', title: '♻️ Eco A (KG)', key: 'ecoA', color: ['#10b981', '#34d399', '#6ee7b7'], formatter: formatWeight, description: 'Volume total de material reciclado Eco A gerado.' },
    { id: 'ecoBP', title: '♻️ Eco B Produção', key: 'ecoBP', color: ['#3b82f6', '#60a5fa', '#93c5fd'], formatter: formatWeight, description: 'Resíduos Eco B originados do processo produtivo.' },
    { id: 'ecoBM', title: '♻️ Eco B Manutenção', key: 'ecoBM', color: ['#8b5cf6', '#a78bfa', '#c4b5fd'], formatter: formatWeight, description: 'Resíduos Eco B originados de manutenções e ajustes.' },
    { id: 'borra', title: '🗑️ Borra Total', key: 'borra', color: ['#f43f5e', '#fb7185', '#fda4af'], formatter: formatWeight, description: 'Desperdício não reaproveitável (purga) gerado.' },
    { id: 'p_manut', title: '⏱️ Paradas (Min)', key: 'p_manut', color: ['#ef4444', '#f59e0b', '#64748b'], formatter: formatMinutes, description: 'Tempo total de máquinas inativas por operador.' },
    { id: 'comp_prod_ecob', title: '📊 Líquido vs Eco B', key: 'comparison_prod_ecob', color: ['#3b82f6', '#8b5cf6'], formatter: formatWeight, description: 'Proporção entre material final e resíduos Eco B.' },
    { id: 'comp_ecob_rec', title: '📊 Eco B vs Reciclado', key: 'comparison_ecob_recycled', color: ['#f59e0b', '#10b981'], formatter: formatWeight, description: 'Volume de resíduos gerados vs volume recuperado (Erema).' },
    { id: 'comp_prod_borra', title: '📊 Líquido vs Borra', key: 'comparison_prod_borra', color: ['#3b82f6', '#ef4444'], formatter: formatWeight, description: 'Análise de rendimento vs desperdício total.' },
    { id: 'comp_time', title: '⏱️ Tempo Máquina (Min)', key: 'comparison_time', color: ['#3b82f6', '#ef4444'], formatter: formatMinutes, description: 'Relação entre tempo de operação ativa e tempo de paradas.' }
  ];

  const handleSaveDashboardPDF = async () => {
    if (!dashboardRef.current || isGeneratingPDF) return;
    setIsGeneratingPDF(true);
    try {
      const canvas = await html2canvas(dashboardRef.current, { scale: 2, useCORS: true, backgroundColor: '#f8fafc' });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF('p', 'mm', 'a4');
      const pageWidth = pdf.internal.pageSize.getWidth();
      const margin = 10;
      const contentWidth = pageWidth - (margin * 2);
      pdf.setFont("helvetica", "bold");
      pdf.setFontSize(18);
      pdf.text("Manupackaging - Controle de Produção", margin, 15);
      const imgProps = pdf.getImageProperties(imgData);
      const pdfImgHeight = (imgProps.height * contentWidth) / imgProps.width;
      pdf.addImage(imgData, 'PNG', margin, 35, contentWidth, pdfImgHeight);
      pdf.save(`dashboard_producao_${dashboardMonth}.pdf`);
    } catch (error) { alert("Erro ao gerar PDF."); }
    finally { setIsGeneratingPDF(false); }
  };

  const handleDownloadChartPNG = async (id: string, title: string) => {
    const element = document.getElementById(id);
    if (!element) return;
    try {
      const canvas = await html2canvas(element, { scale: 3, backgroundColor: '#ffffff' });
      const url = canvas.toDataURL('image/png');
      const link = document.createElement('a');
      link.href = url;
      link.download = `grafico_${title.replace(/\s/g, '_')}.png`;
      link.click();
    } catch (e) { alert("Erro ao salvar imagem."); }
  };

  const getRole = (machineName: string, index: number) => {
    const name = machineName.toLowerCase();
    if (name.includes('cast')) return index === 0 ? 'Operador' : 'Auxiliar';
    if (name.includes('ghezzi')) return index === 0 ? 'Operador' : 'Auxiliar';
    if (name.includes('lintech') || name.includes('wutec') || name.includes('erema')) return 'Operador';
    return 'Operador';
  };

  const personnelStats = useMemo(() => {
    let totalStaff = 0;
    let totalOperators = 0;
    let totalAuxiliaries = 0;
    let totalVacancies = 0;

    const processPerson = (name: string, role: string) => {
      const isVacancy = name === '(Contratar)' || name === 'Auxiliar';
      if (isVacancy) {
        totalVacancies++;
      } else {
        totalStaff++;
        if (role === 'Operador') totalOperators++;
        else totalAuxiliaries++;
      }
    };

    PERSONNEL_DATA.extrusao.forEach(shift => {
      shift.machines.forEach(mach => {
        mach.team.forEach((person, idx) => {
          const role = getRole(mach.name, idx);
          processPerson(person, role);
        });
      });
    });

    PERSONNEL_DATA.erema.forEach(mach => {
      mach.shifts.forEach(shift => {
        shift.team.forEach((person, idx) => {
          const role = getRole(mach.name, idx);
          processPerson(person, role);
        });
      });
    });

    PERSONNEL_DATA.fitaAdesiva.forEach(mach => {
      mach.shifts.forEach(shift => {
        shift.team.forEach((person, idx) => {
          const role = getRole(mach.name, idx);
          processPerson(person, role);
        });
      });
    });

    return { totalStaff, totalOperators, totalAuxiliaries, totalVacancies };
  }, []);

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
  }

  const isGoalReached = totals.month >= goalValue;

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-slate-200/50 rounded-2xl w-fit">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            <div className="bg-white rounded-3xl p-5 shadow-sm border border-slate-100 flex flex-wrap items-center gap-4 no-print">
              <div className="flex-1 min-w-[180px]">
                <label className="text-[9px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1 block">Operador</label>
                <select value={dashOperator} onChange={(e) => setDashOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-100 rounded-xl px-4 py-2.5 text-[11px] font-bold text-slate-700 outline-none">
                  <option value="">Todos</option>
