                   </button>
                 )}
                 <button onClick={handleExportCSV} className="px-4 py-3 bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase flex items-center gap-2"><FileSpreadsheet size={16}/> CSV</button>
                 <button onClick={() => window.print()} className="p-3 bg-slate-800 text-white rounded-2xl"><Printer size={18}/></button>
               </div>
            </div>
            <div className="overflow-x-auto custom-scrollbar">
              <table className="w-full text-left border-collapse min-w-[1200px]">
                <thead>
                  <tr className="bg-slate-50 text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100">
                    <th className="px-6 py-4 w-12 text-center">
                      <input 
                        type="checkbox" 
                        checked={filteredReports.length > 0 && filteredReports.every(r => selectedIds.includes(r.id))}
                        onChange={handleSelectAll}
                        className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
                      />
