  const syncStructureWithEmployeeChange = (oldEmployee: Employee | null, newEmployeeData: Partial<Employee>, action: string) => {
    // This function ensures that if a role/shift/machine changes, the slots in personnelStructure update accordingly.
    // 1. If moving TO a new slot, ensure that slot exists in structure.
    // 2. If moving FROM an old slot (and leaving it empty), remove that slot from structure.

    setPersonnelStructure(prevStructure => {
        const newStructure = JSON.parse(JSON.stringify(prevStructure)); // Deep clone

        // Helper to add slot
        const ensureSlotExists = (sector: string, machine: string, shift: string, role: string) => {
            if (sector === 'Extrusão') {
                const sIdx = newStructure.extrusao.findIndex((s: any) => s.shift === shift);
                if (sIdx >= 0) {
                    const mIdx = newStructure.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                    if (mIdx >= 0) {
                        const roles = newStructure.extrusao[sIdx].machines[mIdx].roles;
                        // Only add if we need a new slot. 
                        // Strategy: We check if there's a vacancy. If all slots of this role are full, add one.
                        // Actually simpler: Just check if we are creating a new type of role or if we want to expand.
                        // User wants: "Change Aux to Op -> Op slot appears".
                        // So we simply append the role.
                        // But we should check if there is already an EMPTY slot of this role?
                        // No, simpler logic: "Auto-Healing".
                        // We will recalculate slots based on employees later? No, that's too heavy.

                        // Current logic: Just push the role if needed.
                        // To avoid duplicates if the user just edits the name:
                        // We only add if this specific operation needs a "destination".
                    }
                }
            }
            // Implementation complexity: It's easier to manipulate the structure directly where we find it.
        };

        // Let's implement specific logic:

        // 1. ADD DESTINATION SLOT
        if (newEmployeeData.status !== 'Desligado') {
            const destSector = newEmployeeData.sector === 'Extrusão' ? 'extrusao' : (newEmployeeData.sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva');
            const destMachine = newEmployeeData.machine!;
            const destShift = newEmployeeData.shift!;
            const destRole = newEmployeeData.role!;

            if (destSector === 'extrusao') {
                const sIdx = newStructure.extrusao.findIndex((s: any) => s.shift === destShift);
                if (sIdx >= 0) {
                    const mIdx = newStructure.extrusao[sIdx].machines.findIndex((m: any) => m.name === destMachine);
                    if (mIdx >= 0) {
                        const currentRoles = newStructure.extrusao[sIdx].machines[mIdx].roles;
                        // Count how many employees are currently in this role at this place
                        const employeesInRole = employees.filter(e => e.sector === 'Extrusão' && e.machine === destMachine && e.shift === destShift && e.role === destRole && e.status !== 'Desligado').length;
                        const slotsInRole = currentRoles.filter((r: string) => r === destRole).length;

                        // If we are moving someone here (or creating), and we don't have enough slots (filled + 1 > slots), add one.
                        // Note: "employees" state hasn't updated yet in this closure, or is about to.
                        // Let's just blindly ADD the role if it doesn't exist? No.
                        // Let's add the role.
                        newStructure.extrusao[sIdx].machines[mIdx].roles.push(destRole);
                    }
                }
            } else {
                // Erema or Fita
                const sectorArr = newStructure[destSector];
                const mIdx = sectorArr.findIndex((m: any) => m.name === destMachine);
                if (mIdx >= 0) {
                    const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === destShift);
                    if (sIdx >= 0) {
                        newStructure[destSector][mIdx].shifts[sIdx].roles.push(destRole);
                    }
                }
            }
        }

        // 2. REMOVE SOURCE SLOT (If it became empty)
        if (oldEmployee && action !== 'Contratação') {
             // Logic: Check if the OLD slot is now extraneous.
             // But wait, we added a slot above blindly. We should probably refine this.
             // Better approach:
             // We can't know for sure which *index* of role array was occupied.
             // But we can count.

             // Let's use a "Cleanup" strategy.
             // Go through the specific modified locations (Source and Dest) and balance them.

             const balanceLocation = (sectorName: string, machName: string, shiftName: string) => {
                 // Count active employees for this location
                 const sectorKey = sectorName === 'Extrusão' ? 'extrusao' : (sectorName === 'Reciclagem' ? 'erema' : 'fitaAdesiva');

                 // Get all employees for this location (EXCLUDING the one being modified, then add new if applicable)
                 const activeEmps = employees.filter(e => 
                    e.id !== oldEmployee?.id && // Exclude self (old state)
                    e.sector === sectorName && 
                    e.machine === machName && 
                    e.shift === shiftName && 
                    e.status !== 'Desligado'
                 );

                 // If this is the destination of the current operation, add 1 placeholder for the new guy
                 const isDest = newEmployeeData.sector === sectorName && newEmployeeData.machine === machName && newEmployeeData.shift === shiftName && newEmployeeData.status !== 'Desligado';

                 const targetCounts: Record<string, number> = {};
                 activeEmps.forEach(e => {
                     targetCounts[e.role] = (targetCounts[e.role] || 0) + 1;
                 });
                 if (isDest && newEmployeeData.role) {
                     targetCounts[newEmployeeData.role] = (targetCounts[newEmployeeData.role] || 0) + 1;
                 }

                 // Now update structure to match targetCounts exactly? 
                 // No, we might want empty slots (vacancies).
                 // User wants: "Change Aux to Op -> Remove Aux vacancy, Add Op vacancy".
                 // This implies: Structure should match (Active Employees) + (Explicit Vacancies).
                 // But we don't track explicit vacancies separately from structure.

                 // Heuristic: 
                 // If we are REMOVING a person from a role (Moving Aux -> Op), and that leaves an Aux slot empty, remove the slot.
                 // If we are ADDING a person to a role (Op), and there is no empty slot, add the slot.

                 return targetCounts;
             };

             // This is getting complicated to do generically.
             // Let's stick to the direct "Remove Old / Add New" on top of existing structure.

             const srcSector = oldEmployee.sector === 'Extrusão' ? 'extrusao' : (oldEmployee.sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva');
             const srcMachine = oldEmployee.machine;
             const srcShift = oldEmployee.shift;
             const srcRole = oldEmployee.role;

             // Remove ONE instance of srcRole from srcLocation
             if (srcSector === 'extrusao') {
                 const sIdx = newStructure.extrusao.findIndex((s: any) => s.shift === srcShift);
                 if (sIdx >= 0) {
                     const mIdx = newStructure.extrusao[sIdx].machines.findIndex((m: any) => m.name === srcMachine);
                     if (mIdx >= 0) {
                         const roles = newStructure.extrusao[sIdx].machines[mIdx].roles;
                         const rIdx = roles.indexOf(srcRole);
                         if (rIdx >= 0) roles.splice(rIdx, 1);
                     }
                 }
             } else {
                 const sectorArr = newStructure[srcSector];
                 const mIdx = sectorArr.findIndex((m: any) => m.name === srcMachine);
                 if (mIdx >= 0) {
                     const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === srcShift);
                     if (sIdx >= 0) {
                         const roles = sectorArr[mIdx].shifts[sIdx].roles;
                         const rIdx = roles.indexOf(srcRole);
                         if (rIdx >= 0) roles.splice(rIdx, 1);
                     }
                 }
             }
        }

        return newStructure;
    });
  };

  const handleEmployeeAction = (data: Partial<Employee>, action: string, details?: string) => {
    const timestamp = new Date().toISOString();

    // Identificar colaborador antigo para limpeza de estrutura
    const oldEmployee = data.id ? employees.find(e => e.id === data.id) || null : null;

    // Create new log entry
    const newLog: PersonnelLog = {
        id: Math.random().toString(36).substr(2, 9),
        date: timestamp,
        employeeName: data.name || 'Desconhecido',
        action: action as any,
        details: details || '',
        user: 'Admin'
    };
    setPersonnelLogs(prev => [newLog, ...prev]);

    // Sync Structure logic
    // We only modify structure if it's a structural change (Hire, Move, Role Change, Terminate)
    if (['Contratação', 'Alteração', 'Transferência', 'Desligamento'].includes(action)) {
        syncStructureWithEmployeeChange(oldEmployee, data, action);
    }

    if (data.id) {
        // Update existing
        setEmployees(prev => prev.map(e => e.id === data.id ? { ...e, ...data, updatedAt: timestamp } : e));
    } else {
        // Create new
