                <span className={`text-[9px] font-bold truncate ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Contratar)</span>
                <span className={`text-[7px] font-black px-1 py-0.5 rounded uppercase ${
                    isNight ? 'bg-red-900/40 text-red-400' : 'bg-red-100 text-red-600'
