              </div>
              {/* Grid 2x2 exato para os 4 turnos */}
              <div className="p-3 grid grid-cols-2 gap-2">
                {personnelStructure.extrusao.map((shift, idx) => {
                  const isNight = shift.shift.toLowerCase().includes('noturno');
                  return (
                    <div key={idx} className={`${isNight ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-200'} rounded-xl p-2 border transition-colors flex flex-col`}>
                      <div className="flex items-center gap-1.5 mb-2">
                        <Clock size={12} className="text-slate-400" />
                        <h3 className={`text-[10px] font-black uppercase ${isNight ? 'text-white' : 'text-slate-700'}`}>{shift.shift}</h3>
                      </div>
                      {/* Grid 2x2 para as máquinas dentro do turno */}
                      <div className="grid grid-cols-2 gap-2 flex-1">
                        {shift.machines.map((machine, mIdx) => (
                          <div key={mIdx} className={`${isNight ? 'bg-slate-700 border-slate-600' : 'bg-white border-slate-100'} rounded-lg p-1.5 shadow-sm border h-full flex flex-col`}>
                            <div className="flex justify-between items-center mb-1.5">
                                <h4 className="text-[8px] font-black text-slate-400 uppercase tracking-widest truncate">{machine.name}</h4>
                                <button onClick={() => handleAddSlot('extrusao', machine.name, shift.shift)} className="text-blue-400 hover:text-blue-600 transition-colors p-0.5 rounded hover:bg-blue-50">
                                    <Plus size={10} />
                                </button>
                            </div>
                            <div className="space-y-1 flex-1">
                              {machine.roles.map((role, pIdx) => {
                                return (
                                  <div key={pIdx}>
                                    {renderPersonnelSlot('extrusao', machine.name, shift.shift, role, isNight, pIdx, machine.roles)}
                                  </div>
                                );
                              })}
                            </div>
                          </div>
                        ))}
                      </div>
                    </div>
                  );
                })}
              </div>
            </div>

            {/* Layout Lado a Lado para Reciclagem e Fita (Grid 2 colunas) */}
            <div className="grid grid-cols-2 gap-2">
              {/* Erema - Reciclagem */}
              <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
                <div className="bg-emerald-900 p-3 text-white flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-emerald-500/20 rounded-lg flex items-center justify-center text-emerald-400 border border-emerald-500/10">
                      <Factory size={16} />
                    </div>
                    <div>
                      <h2 className="text-xs font-black uppercase tracking-tighter">Setor: Reciclagem</h2>
                      <p className="text-[8px] text-emerald-300/60 font-bold uppercase tracking-widest">Erema</p>
                    </div>
                  </div>
                </div>
                <div className="p-3 flex-1">
                  {personnelStructure.erema.map((machine, idx) => (
                    <div key={idx} className="grid grid-cols-2 gap-2 h-full">
                      {machine.shifts.map((shift, sIdx) => {
                         const isNight = shift.name.toLowerCase().includes('noturno');
                         return (
                           <div key={sIdx} className={`flex flex-col gap-1.5 p-2 rounded-xl border ${isNight ? 'bg-slate-800 border-slate-700' : 'bg-slate-50 border-slate-100'}`}>
                              <div className={`${isNight ? 'bg-slate-700 border-slate-600' : 'bg-white border-slate-200'} p-1 rounded-lg border w-full relative group`}>
                                <span className={`text-[9px] font-black uppercase block text-center truncate ${isNight ? 'text-white' : 'text-slate-700'}`}>{shift.name}</span>
                                <button onClick={() => handleAddSlot('erema', machine.name, shift.name)} className="absolute right-1 top-1/2 -translate-y-1/2 text-emerald-400 hover:text-emerald-600 transition-colors p-0.5 rounded opacity-0 group-hover:opacity-100">
                                    <Plus size={10} />
                                </button>
                              </div>
                              <div className="flex flex-col gap-1 justify-center flex-1">
                                {shift.roles.map((role, pIdx) => (
                                    <div key={pIdx}>
                                        {renderPersonnelSlot('erema', machine.name, shift.name, role, isNight, pIdx, shift.roles)}
                                    </div>
                                ))}
                              </div>
                           </div>
                         );
                      })}
                    </div>
                  ))}
                </div>
              </div>

              {/* Fita Adesiva */}
              <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden flex flex-col">
                <div className="bg-orange-900 p-3 text-white flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <div className="w-8 h-8 bg-orange-500/20 rounded-lg flex items-center justify-center text-orange-400 border border-orange-500/10">
                      <Layers size={16} />
                    </div>
                    <div>
                      <h2 className="text-xs font-black uppercase tracking-tighter">Setor: Fita Adesiva</h2>
                      <p className="text-[8px] text-orange-300/60 font-bold uppercase tracking-widest">Ghezzi/Lintech/Wutec</p>
                    </div>
                  </div>
                </div>
                {/* Grid para as máquinas de Fita */}
                <div className="p-3 grid grid-cols-2 gap-2 flex-1 content-start">
                   {personnelStructure.fitaAdesiva.map((machine, idx) => (
                      <div key={idx} className={`bg-slate-50 rounded-xl p-2 border border-slate-200 ${idx === 2 ? 'col-span-2' : ''}`}> {/* Wutec ocupa 2 colunas se for a ultima */}
                         <div className="flex justify-between items-center mb-2">
                             <h3 className="text-[9px] font-black text-slate-700 uppercase flex items-center gap-1.5">
                               <div className="w-1.5 h-1.5 rounded-full bg-orange-500"></div> {machine.name}
                             </h3>
                         </div>
                         <div className={`grid ${machine.shifts.length > 1 ? 'grid-cols-2' : 'grid-cols-1'} gap-2`}>
                            {machine.shifts.map((shift, sIdx) => {
                               const isNight = shift.name.toLowerCase().includes('noturno');
                               return (
                                 <div key={sIdx} className={`p-1.5 rounded-lg border ${isNight ? 'bg-slate-800 border-slate-700' : 'bg-white border-slate-100'}`}>
                                    <div className={`text-[8px] font-black uppercase tracking-widest mb-1 border-b pb-0.5 truncate flex justify-between items-center ${isNight ? 'text-slate-400 border-slate-700' : 'text-slate-400 border-slate-50'}`}>
                                        {shift.name}
                                        <button onClick={() => handleAddSlot('fitaAdesiva', machine.name, shift.name)} className="text-orange-400 hover:text-orange-600 transition-colors p-0.5 rounded">
                                            <Plus size={10} />
                                        </button>
                                    </div>
                                    <div className="space-y-1">
                                      {shift.roles.map((role, pIdx) => {
                                        return (
                                            <div key={pIdx}>
                                                {renderPersonnelSlot('fitaAdesiva', machine.name, shift.name, role, isNight, pIdx, shift.roles)}
                                            </div>
                                        )
                                      })}
                                    </div>
                                 </div>
                               );
                            })}
                         </div>
                      </div>
                   ))}
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end">
          <div className="absolute inset-0 bg-slate-900/40 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}></div>
          <div className="relative w-85 bg-white shadow-2xl p-0 flex flex-col h-full animate-in slide-in-from-right duration-300">
            <div className="bg-[#1e293b] p-8 text-white">
              <h2 className="text-xl font-black uppercase tracking-tighter flex items-center gap-3"><Settings size={26} className="text-blue-500" /> Configurações</h2>
            </div>
            <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar">
              <div className="space-y-3">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Meta Mensal (KG)</label>
                <input type="number" value={goalValue} onChange={(e) => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-100 p-4 rounded-2xl font-black text-blue-600 outline-none" />
              </div>

              {/* DASHBOARD FILTERS MOVED HERE */}
              <div className="space-y-3 border-t border-slate-100 pt-4">
                 <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1 flex items-center gap-2"><Filter size={12}/> Filtros do Dashboard</h3>
                 <div className="grid grid-cols-2 gap-3">
                   <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Operador</label>
                      <select value={dashOperator} onChange={(e) => setDashOperator(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-[10px] font-bold text-slate-700 outline-none">
                        <option value="">Todos</option>
                        {operators.map(op => <option key={op} value={op}>{op}</option>)}
                      </select>
                   </div>
                   <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Máquina</label>
                      <select value={dashMachine} onChange={(e) => setDashMachine(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-[10px] font-bold text-slate-700 outline-none">
                        <option value="">Todas</option>
                        {activeMachines.map(m => <option key={m} value={m}>{m}</option>)}
                      </select>
                   </div>
                   <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Data Inicial</label>
                      <input type="date" value={dashStartDate} onChange={(e) => setDashStartDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-[10px] font-bold text-slate-700 outline-none" />
                   </div>
                   <div>
                      <label className="text-[9px] font-bold text-slate-400 uppercase">Data Final</label>
                      <input type="date" value={dashEndDate} onChange={(e) => setDashEndDate(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-[10px] font-bold text-slate-700 outline-none" />
                   </div>
                 </div>
              </div>

              <div className="grid grid-cols-1 gap-3 pt-4 border-t border-slate-100">
                <button onClick={() => { setIsOperatorModalOpen(true); setIsMenuOpen(false); }} className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-blue-50 text-slate-700 rounded-2xl text-[10px] font-black uppercase transition-all">
                   <span>Gerenciar Equipe (Produção)</span>
                   <ChevronRight size={16}/>
                </button>
                <button onClick={() => { setIsRoleModalOpen(true); setIsMenuOpen(false); }} className="w-full flex items-center justify-between p-4 bg-slate-50 hover:bg-indigo-50 text-slate-700 rounded-2xl text-[10px] font-black uppercase transition-all">
                   <span>Gerenciar Funções</span>
                   <ChevronRight size={16}/>
                </button>
              </div>
              <div className="pt-4 border-t border-slate-100 space-y-3">
                 <button onClick={() => fileInputRef.current?.click()} className="w-full flex items-center gap-3 p-4 bg-emerald-50 text-emerald-700 rounded-2xl text-[10px] font-black uppercase hover:bg-emerald-100 transition-all"><Upload size={18}/> Importar Backup</button>
                 <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />
                 <button onClick={handleExportBackup} className="w-full flex items-center gap-3 p-4 bg-blue-50 text-blue-700 rounded-2xl text-[10px] font-black uppercase hover:bg-blue-100 transition-all"><Download size={18}/> Exportar Backup</button>
                 <button onClick={handleResetSystem} className="w-full flex items-center gap-3 p-4 bg-red-50 text-red-700 rounded-2xl text-[10px] font-black uppercase hover:bg-red-100 transition-all"><RotateCcw size={18}/> Resetar Sistema</button>
              </div>
              <button onClick={handleSaveDashboardPDF} className="w-full p-4 bg-slate-800 hover:bg-black text-white rounded-2xl text-[10px] font-black uppercase transition-all flex items-center justify-center gap-3 shadow-xl shadow-slate-200">
                <FileDown size={18} /> Exportar Dashboard PDF
              </button>
            </div>
            <div className="p-6 bg-slate-50 border-t border-slate-100">
              <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full p-4 bg-white border border-red-100 text-red-600 rounded-2xl text-[10px] font-black uppercase flex items-center justify-center gap-2 hover:bg-red-50 transition-all">
                <LogOut size={16}/> Sair do Sistema
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmDialog.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
          <div className="bg-white rounded-3xl p-8 w-full max-w-sm shadow-2xl space-y-6">
            <div className="flex flex-col items-center text-center space-y-4">
              <div className="w-16 h-16 bg-red-100 text-red-600 rounded-2xl flex items-center justify-center"><AlertTriangle size={32} /></div>
              <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">{confirmDialog.title}</h3>
              <p className="text-slate-500 text-sm font-medium">{confirmDialog.message}</p>
            </div>
            <div className="flex gap-3">
              <button onClick={() => setConfirmDialog(prev => ({...prev, isOpen: false}))} className="flex-1 px-4 py-3 bg-slate-100 text-slate-600 rounded-xl font-black text-[10px] uppercase hover:bg-slate-200 transition-all">Cancelar</button>
              <button onClick={confirmDialog.onConfirm} className="flex-1 px-4 py-3 bg-red-600 text-white rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-red-700 transition-all">Confirmar</button>
            </div>
          </div>
        </div>
      )}

      <LaunchModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} availableShifts={shifts} initialData={editingEntry} />
      <OperatorModal isOpen={isOperatorModalOpen} onClose={() => setIsOperatorModalOpen(false)} operators={operators} onUpdate={setOperators} />
      <ShiftModal isOpen={isShiftModalOpen} onClose={() => setIsShiftModalOpen(false)} onSave={(newShift) => setShifts(prev => [...prev, { ...newShift, id: Math.random().toString(36).substr(2, 9) }])} />

      {/* New Personnel Modals */}
      <EmployeeModal 
        isOpen={isEmployeeModalOpen} 
        onClose={() => setIsEmployeeModalOpen(false)} 
        onSave={handleEmployeeAction}
        availableShifts={shifts}
        availableMachines={activeMachines}
        availableRoles={jobRoles} // Pass dynamic roles
        initialData={selectedEmployee}
        slotInfo={newEmployeeSlot}
      />
      <RoleModal 
        isOpen={isRoleModalOpen}
        onClose={() => setIsRoleModalOpen(false)}
        roles={jobRoles}
        onUpdate={setJobRoles}
      />
      <HistoryModal 
        isOpen={isHistoryModalOpen} 
        onClose={() => setIsHistoryModalOpen(false)} 
        logs={personnelLogs} 
      />

    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { X, UserPlus, Save, Briefcase, MapPin, UserX, Stethoscope, Plane, Trash2 } from 'lucide-react';
import { Shift, Employee } from '../types';

interface EmployeeModalProps {
  isOpen: boolean;
  onClose: () => void;
  onSave: (data: Partial<Employee>, action: string, reason?: string) => void;
  availableShifts: Shift[];
  availableMachines: string[];
  availableRoles: string[]; // Added roles prop
  initialData?: Employee | null;
  slotInfo?: { sector: string; machine: string; shift: string; role: string }; // role is now string
}

type ModalAction = 'update' | 'vacation' | 'medical' | 'terminate' | 'transfer' | 'create' | 'delete';

const EmployeeModal: React.FC<EmployeeModalProps> = ({ isOpen, onClose, onSave, availableShifts, availableMachines, availableRoles, initialData, slotInfo }) => {
  const [actionType, setActionType] = useState<ModalAction>('update');
  const [formData, setFormData] = useState<Partial<Employee>>({
    name: '',
    role: 'Operador',
    sector: '',
    machine: '',
    shift: '',
    status: 'Ativo',
  });

  const [extraData, setExtraData] = useState({
    reason: '',
    startDate: new Date().toISOString().split('T')[0],
    duration: 30,
    returnDate: ''
  });

  useEffect(() => {
    if (isOpen) {
      if (initialData) {
        setFormData({ ...initialData });
        setActionType('update');
      } else if (slotInfo) {
        setFormData({
          name: '',
          role: slotInfo.role,
          sector: slotInfo.sector,
          machine: slotInfo.machine,
          shift: slotInfo.shift,
          status: 'Ativo'
        });
        setActionType('create');
      }
      // Reset extra data
      setExtraData({
        reason: '',
        startDate: new Date().toISOString().split('T')[0],
        duration: 30,
        returnDate: ''
      });
    }
  }, [isOpen, initialData, slotInfo]);

  // Calcular data de retorno automaticamente
  useEffect(() => {
    if (extraData.startDate && extraData.duration) {
      const date = new Date(extraData.startDate);
      date.setDate(date.getDate() + Number(extraData.duration));
      setExtraData(prev => ({ ...prev, returnDate: date.toISOString().split('T')[0] }));
    }
  }, [extraData.startDate, extraData.duration]);

  if (!isOpen) return null;

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Validações básicas
    if (!formData.name && actionType === 'create') return alert("Nome obrigatório");

    let finalData = { ...formData };
    let actionLog = '';
    let detailsLog = '';

    if (actionType === 'create') {
        actionLog = 'Contratação';
        detailsLog = `Admissão para ${formData.sector} - ${formData.machine} (${formData.role})`;
    } else if (actionType === 'update') {
        actionLog = 'Alteração';
        detailsLog = 'Atualização de dados cadastrais';
    } else if (actionType === 'vacation') {
        finalData.status = 'Férias';
        finalData.returnDate = extraData.returnDate;
        actionLog = 'Férias';
        detailsLog = `${extraData.duration} dias. Retorno em ${new Date(extraData.returnDate).toLocaleDateString('pt-BR')}`;
    } else if (actionType === 'medical') {
        finalData.status = 'Atestado';
        finalData.returnDate = extraData.returnDate;
        finalData.statusDetails = extraData.reason;
        actionLog = 'Atestado';
        detailsLog = `${extraData.duration} dias. Motivo: ${extraData.reason}`;
    } else if (actionType === 'terminate') {
        finalData.status = 'Desligado';
        actionLog = 'Desligamento';
        detailsLog = `Motivo: ${extraData.reason}`;
    } else if (actionType === 'transfer') {
        actionLog = 'Transferência';
        detailsLog = `Para ${formData.machine} - ${formData.shift}`;
    } else if (actionType === 'delete') {
        actionLog = 'Exclusão';
        detailsLog = 'Remoção definitiva de colaborador e vaga.';
    }

    onSave(finalData, actionLog, detailsLog);
    onClose();
  };

  const isEditing = !!initialData;

  return (
    <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 bg-slate-900/60 backdrop-blur-sm">
      <div className="bg-white rounded-[2rem] w-full max-w-lg shadow-2xl relative overflow-hidden animate-in zoom-in-95 duration-200 flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className={`text-white p-6 flex items-center justify-between ${
            actionType === 'delete' ? 'bg-red-700' :
            actionType === 'terminate' ? 'bg-red-500' : 
            actionType === 'vacation' ? 'bg-orange-600' :
            actionType === 'medical' ? 'bg-purple-600' :
            'bg-[#1e293b]'
        } transition-colors duration-300`}>
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-white border border-white/20">
              {actionType === 'delete' ? <Trash2 size={24} /> :
               actionType === 'terminate' ? <UserX size={24} /> : 
               actionType === 'vacation' ? <Plane size={24} /> :
               actionType === 'medical' ? <Stethoscope size={24} /> :
               <UserPlus size={24} />}
            </div>
            <div>
              <h2 className="text-xl font-black tracking-tight uppercase leading-none">
                {actionType === 'create' ? 'Contratar' : formData.name}
              </h2>
              <p className="text-[10px] text-white/70 font-bold uppercase tracking-widest mt-1">
                {isEditing ? (actionType === 'delete' ? 'Excluir Registro' : 'Gerenciar Colaborador') : 'Novo Cadastro'}
              </p>
            </div>
          </div>
          <button onClick={onClose} className="hover:bg-white/10 p-2 rounded-xl transition-colors text-white/70 hover:text-white">
            <X size={24} />
          </button>
        </div>

        {/* Action Selector (Only if editing) */}
        {isEditing && (
            <div className="flex p-2 bg-slate-100 gap-1 overflow-x-auto no-scrollbar border-b border-slate-200">
                <button onClick={() => setActionType('update')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${actionType === 'update' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200'}`}>Dados</button>
                <button onClick={() => setActionType('vacation')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${actionType === 'vacation' ? 'bg-orange-100 text-orange-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200'}`}>Férias</button>
                <button onClick={() => setActionType('medical')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${actionType === 'medical' ? 'bg-purple-100 text-purple-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200'}`}>Atestado</button>
                <button onClick={() => setActionType('transfer')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${actionType === 'transfer' ? 'bg-blue-100 text-blue-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200'}`}>Transferir</button>
                <button onClick={() => setActionType('terminate')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${actionType === 'terminate' ? 'bg-red-50 text-red-600 shadow-sm' : 'text-slate-500 hover:bg-slate-200'}`}>Desligar</button>
                <button onClick={() => setActionType('delete')} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase whitespace-nowrap transition-all ${actionType === 'delete' ? 'bg-red-600 text-white shadow-sm' : 'bg-slate-200 text-slate-500 hover:bg-red-100 hover:text-red-600'}`}>Excluir</button>
            </div>
        )}

        {/* Form Body */}
        <form onSubmit={handleSubmit} className="p-6 space-y-6 overflow-y-auto custom-scrollbar flex-1">

          {/* Dados Básicos (Update / Create / Transfer) */}
          {(actionType === 'update' || actionType === 'create' || actionType === 'transfer') && (
            <div className="space-y-4 animate-in fade-in slide-in-from-left-4">
                <div>
                  <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1.5 flex items-center gap-2">Nome Completo</label>
                  <input type="text" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} disabled={actionType === 'transfer'} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none focus:ring-2 focus:ring-blue-500/20" placeholder="Nome..." />
                </div>

                <div className="grid grid-cols-2 gap-4">
                    <div>
                        <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-1.5">Função</label>
                        <select value={formData.role} onChange={e => setFormData({...formData, role: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3.5 text-sm font-bold outline-none">
                            {availableRoles.map(role => (
                                <option key={role} value={role}>{role}</option>
                            ))}
                        </select>
                    </div>
                    <div>
