  const handleEmployeeAction = (data: Partial<Employee>, action: string, details?: string) => {
    const timestamp = new Date().toISOString();

    // Identificar colaborador antigo para limpeza de estrutura
    const oldEmployee = data.id ? employees.find(e => e.id === data.id) || null : null;

    // Create new log entry
    const newLog: PersonnelLog = {
        id: Math.random().toString(36).substr(2, 9),
        date: timestamp,
        employeeName: data.name || 'Desconhecido',
        action: action as any,
        details: details || '',
        user: 'Admin'
    };
    setPersonnelLogs(prev => [newLog, ...prev]);

    // Handle full deletion
    if (action === 'Exclusão' && oldEmployee) {
        // 1. Remove Employee Record
        setEmployees(prev => prev.filter(e => e.id !== oldEmployee.id));

        // 2. Remove Slot from Structure
        setPersonnelStructure(prevStructure => {
            const newStruct = JSON.parse(JSON.stringify(prevStructure));
            const { sector, machine, shift, role } = oldEmployee;

            // Helper to remove ONE instance of the role
            const removeRoleInstance = (roles: string[]) => {
                const idx = roles.indexOf(role);
                if (idx > -1) roles.splice(idx, 1);
            };

            if (sector === 'Extrusão') {
                const sIdx = newStruct.extrusao.findIndex((s: any) => s.shift === shift);
                if (sIdx >= 0) {
                    const mIdx = newStruct.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                    if (mIdx >= 0) removeRoleInstance(newStruct.extrusao[sIdx].machines[mIdx].roles);
                }
            } else {
                const secKey = sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva';
                const sectorArr = newStruct[secKey];
                const mIdx = sectorArr.findIndex((m: any) => m.name === machine);
                if (mIdx >= 0) {
                    const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === shift);
                    if (sIdx >= 0) removeRoleInstance(sectorArr[mIdx].shifts[sIdx].roles);
                }
            }
            return newStruct;
        });
        return; // Stop here for deletion
    }

    // Sync Structure logic
    // We only modify structure if it's a structural change (Hire, Move, Role Change, Terminate)
    if (['Contratação', 'Alteração', 'Transferência', 'Desligamento'].includes(action)) {
        syncStructureWithEmployeeChange(oldEmployee, data, action);
    }

    // Special case for 'Contratação' from a 'Vaga' placeholder:
    // If we are hiring into a slot that was temporally named 'Vaga', we need to remove that 'Vaga' placeholder 
    // because syncStructureWithEmployeeChange will add the REAL role slot.
    if (action === 'Contratação' && newEmployeeSlot && newEmployeeSlot.role === 'Vaga') {
         setPersonnelStructure(prev => {
            const newStruct = JSON.parse(JSON.stringify(prev));
            const { sector, machine, shift } = newEmployeeSlot;

            // Helper to remove first 'Vaga' occurrence
            const removeVaga = (roles: string[]) => {
                const idx = roles.indexOf('Vaga');
                if (idx > -1) roles.splice(idx, 1);
            };

            if (sector === 'Extrusão') {
                 const sIdx = newStruct.extrusao.findIndex((s: any) => s.shift === shift);
                 if (sIdx >= 0) {
                     const mIdx = newStruct.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                     if (mIdx >= 0) removeVaga(newStruct.extrusao[sIdx].machines[mIdx].roles);
                 }
            } else {
                 const secKey = sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva';
                 const sectorArr = newStruct[secKey];
                 const mIdx = sectorArr.findIndex((m: any) => m.name === machine);
                 if (mIdx >= 0) {
                     const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === shift);
                     if (sIdx >= 0) removeVaga(sectorArr[mIdx].shifts[sIdx].roles);
                 }
            }
            return newStruct;
         });
    }

    if (data.id) {
        // Update existing
        setEmployees(prev => prev.map(e => e.id === data.id ? { ...e, ...data, updatedAt: timestamp } : e));
    } else {
        // Create new
        setEmployees(prev => [...prev, { 
            ...data, 
            id: Math.random().toString(36).substr(2, 9), 
            updatedAt: timestamp 
        } as Employee]);
    }
  };

  // ------------------------------------

  const formatWeight = (val: number) => {
    if (val >= 1000) {
      return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    }
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const getShiftDuration = (shiftName: string) => {
    const shift = shifts.find(s => s.name === shiftName);
    if (!shift) return 720;
    const [h1, m1] = shift.startTime.split(':').map(Number);
    const [h2, m2] = shift.endTime.split(':').map(Number);
    let minutes = (h2 * 60 + m2) - (h1 * 60 + m1);
    if (minutes < 0) minutes += 1440;
    return minutes === 0 ? 1440 : minutes;
  };

  const totals = useMemo(() => {
    const now = new Date();
    const todayStr = now.toLocaleDateString('sv-SE');
    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');
    const startOfWeek = new Date(now);
    startOfWeek.setHours(0,0,0,0);
    startOfWeek.setDate(now.getDate() - now.getDay());

    const currentYear = parseInt(dashboardMonth.split('-')[0]);
    const currentMonth = parseInt(dashboardMonth.split('-')[1]) - 1;
    const isCurrentMonth = now.getFullYear() === currentYear && now.getMonth() === currentMonth;
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const currentDay = isCurrentMonth ? now.getDate() : daysInMonth;

    const baseFiltered = productionData.filter(e => {
      const matchesOp = dashOperator ? e.operator === dashOperator : true;
      const matchesMac = dashMachine ? e.machine === dashMachine : true;
      return matchesOp && matchesMac;
    });

    const results = { 
      month: 0, 
      today: 0, 
      yesterday: 0, 
      week: 0, 
      range: 0, 
      projection: 0,
      remaining: 0,
      dailyRequired: 0
    };

    baseFiltered.forEach(e => {
      if (e.date.startsWith(dashboardMonth)) results.month += (e.netWeight || 0);
      if (e.date === todayStr) results.today += (e.netWeight || 0);
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
      const entryDate = new Date(e.date + 'T00:00:00');
      if (entryDate >= startOfWeek) results.week += (e.netWeight || 0);
    });

    results.projection = currentDay > 0 ? (results.month / currentDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);

    const daysRemaining = Math.max(0, daysInMonth - currentDay);
    results.dailyRequired = daysRemaining > 0 ? results.remaining / daysRemaining : results.remaining;

    return results;
  }, [productionData, dashboardMonth, dashOperator, dashMachine, goalValue]);

  const filteredDataForCharts = useMemo(() => {
    // Dates Setup
    const now = new Date();
    const todayStr = now.toLocaleDateString('sv-SE');
    const yesterday = new Date(now);
    yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');
    const startOfWeek = new Date(now);
    startOfWeek.setHours(0,0,0,0);
    startOfWeek.setDate(now.getDate() - now.getDay());

    return productionData.filter(e => {
      const matchesOp = dashOperator ? e.operator === dashOperator : true;
      const matchesMac = dashMachine ? e.machine === dashMachine : true;

      // 1. Manual Date Filter has priority
      if (dashStartDate || dashEndDate) {
        const matchesStart = dashStartDate ? e.date >= dashStartDate : true;
        const matchesEnd = dashEndDate ? e.date <= dashEndDate : true;
        return matchesOp && matchesMac && matchesStart && matchesEnd;
      }

      // 2. Timeframe Selection
      let matchesTime = false;
      if (selectedTimeframe === 'month') {
        matchesTime = e.date.startsWith(dashboardMonth);
      } else if (selectedTimeframe === 'yesterday') {
        matchesTime = e.date === yesterdayStr;
      } else if (selectedTimeframe === 'week') {
        const entryDate = new Date(e.date + 'T00:00:00');
        matchesTime = entryDate >= startOfWeek;
      } else if (selectedTimeframe === 'today') {
        matchesTime = e.date === todayStr;
      } else {
        // Fallback
        matchesTime = e.date.startsWith(dashboardMonth);
      }

      return matchesOp && matchesMac && matchesTime;
    });
  }, [productionData, dashOperator, dashMachine, dashStartDate, dashEndDate, dashboardMonth, selectedTimeframe]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const matchesSearch = searchTerm 
        ? Object.values(e).some(val => String(val).toLowerCase().includes(searchTerm.toLowerCase()))
        : true;
      const matchesStart = filterStartDate ? e.date >= filterStartDate : true;
      const matchesEnd = filterEndDate ? e.date <= filterEndDate : true;
      return matchesSearch && matchesStart && matchesEnd;
    });
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportSums = useMemo(() => {
    return filteredReports.reduce((acc, curr) => ({
      grossWeight: acc.grossWeight + (curr.grossWeight || 0),
      netWeight: acc.netWeight + (curr.netWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      manutencaoMin: acc.manutencaoMin + (curr.manutencaoMin || 0),
      processoMin: acc.processoMin + (curr.processoMin || 0),
      outrosMin: acc.outrosMin + (curr.outrosMin || 0),
    }), { grossWeight: 0, netWeight: 0, ecoA: 0, manutencaoMin: 0, processoMin: 0, outrosMin: 0 });
  }, [filteredReports]);

  const stats = useMemo(() => {
    const initialStats: Record<string, OperatorStat> = {};
    operators.forEach(op => {
      initialStats[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
    });
    filteredDataForCharts.forEach(e => {
      if (!initialStats[e.operator]) {
        initialStats[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      }
      initialStats[e.operator].prod += (e.netWeight || 0);
      initialStats[e.operator].ecoA += (e.ecoA || 0);
      initialStats[e.operator].ecoBP += (e.ecoBP || 0);
      initialStats[e.operator].ecoBM += (e.ecoBM || 0);
      initialStats[e.operator].borra += (e.borraTotal || 0);
      initialStats[e.operator].p_manut += (e.manutencaoMin || 0);
      initialStats[e.operator].p_proc += (e.processoMin || 0);
      initialStats[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(initialStats);
  }, [filteredDataForCharts, operators]);

  const personnelStats = useMemo(() => {
    let totalStaff = 0;
    let totalOperators = 0;
    let totalAuxiliaries = 0;
    let totalVacancies = 0;

    employees.forEach(emp => {
        if (emp.status === 'Ativo') {
            totalStaff++;
            if (emp.role.includes('Operador') || emp.role === 'Líder de Turno') totalOperators++;
            else totalAuxiliaries++;
        }
    });

    // Vacancies logic based on dynamic structure
    let expectedSlots = 0;
    personnelStructure.extrusao.forEach(s => s.machines.forEach(m => expectedSlots += m.roles.length));
    personnelStructure.erema.forEach(m => m.shifts.forEach(s => expectedSlots += s.roles.length));
    personnelStructure.fitaAdesiva.forEach(m => m.shifts.forEach(s => expectedSlots += s.roles.length));

    const activeEmployeesCount = employees.filter(e => e.status !== 'Desligado').length;
    totalVacancies = Math.max(0, expectedSlots - activeEmployeesCount);

    return { totalStaff, totalOperators, totalAuxiliaries, totalVacancies };
  }, [employees, personnelStructure]);

  // Helper to render an employee card or a vacancy button
  const renderPersonnelSlot = (
    sector: 'extrusao' | 'erema' | 'fitaAdesiva', 
    machine: string, 
    shift: string, 
    role: string, 
    isNight: boolean,
    slotIndex: number, // Added slotIndex to determine which employee to pick
    siblingsRoles: string[] // Added siblingsRoles to count occurrences
  ) => {
    const fullSectorName = sector === 'extrusao' ? 'Extrusão' : sector === 'erema' ? 'Reciclagem' : 'Fita Adesiva';

    // Check if this slot is a placeholder "Vaga"
    if (role === 'Vaga') {
        return (
            <div className="flex items-center gap-1 group/slot">
                <button 
                    onClick={() => {
                        setNewEmployeeSlot({ sector: fullSectorName, machine, shift, role: 'Vaga' });
                        setSelectedEmployee(null);
                        setIsEmployeeModalOpen(true);
                    }}
                    className={`flex-1 flex items-center justify-between p-1 rounded border border-dashed transition-all ${
                        isNight 
                        ? 'border-red-800 bg-red-900/20 hover:bg-red-900/30' 
                        : 'border-red-300 bg-red-50 hover:bg-red-100'
                    }`}
                >
                    <span className={`text-[9px] font-bold truncate ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Adicionar)</span>
                    <span className={`text-[7px] font-black px-1 py-0.5 rounded uppercase ${
                        isNight ? 'bg-red-900/40 text-red-400' : 'bg-red-100 text-red-600'
                    }`}>Vaga</span>
                </button>
                <button 
                  onClick={() => handleRemoveSlot(sector, machine, shift, slotIndex)}
                  className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover/slot:opacity-100 transition-opacity"
                  title="Remover Vaga"
                >
                  <UserMinus size={12}/>
                </button>
            </div>
        );
    }

    // Count how many times this specific role appears in the list BEFORE this current index
    const roleOccurrenceIndex = siblingsRoles.slice(0, slotIndex).filter(r => r === role).length;

    // Get all employees for this slot type
    const potentialEmployees = employees.filter(e => 
        e.sector === fullSectorName && 
        e.machine === machine && 
        e.shift === shift && 
        e.role === role &&
        e.status !== 'Desligado'
    );

    // Pick the one corresponding to our index
    const employee = potentialEmployees[roleOccurrenceIndex];

    // If we expected an employee for a "named" role (e.g. "Operador 1") but found none, show a hiring button for that specific role.
    if (!employee) {
        return (
            <div className="flex items-center gap-1 group/slot">
                <button 
                    onClick={() => {
                        setNewEmployeeSlot({ sector: fullSectorName, machine, shift, role });
                        setSelectedEmployee(null);
                        setIsEmployeeModalOpen(true);
                    }}
                    className={`flex-1 flex items-center justify-between p-1 rounded border border-dashed transition-all ${
                        isNight 
                        ? 'border-red-800 bg-red-900/20 hover:bg-red-900/30' 
                        : 'border-red-300 bg-red-50 hover:bg-red-100'
                    }`}
                >
                    <span className={`text-[9px] font-bold truncate ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Adicionar)</span>
                    <span className={`text-[7px] font-black px-1 py-0.5 rounded uppercase ${
                        isNight ? 'bg-red-900/40 text-red-400' : 'bg-red-100 text-red-600'
                    }`}>{role.split(' ')[0]}</span>
                </button>
                <button 
                  onClick={() => handleRemoveSlot(sector, machine, shift, slotIndex)}
                  className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover/slot:opacity-100 transition-opacity"
                  title="Remover Vaga"
                >
                  <UserMinus size={12}/>
                </button>
            </div>
        );
    }

    // Determine styles based on status
    let bgClass = isNight ? 'bg-slate-800/50' : 'bg-slate-50';
    let textClass = isNight ? 'text-slate-200' : 'text-slate-700';

    // Dynamic Badge Color Logic
    let badgeClass = 'bg-slate-200 text-slate-600';
    if (role === 'Líder de Turno') badgeClass = isNight ? 'bg-purple-900/40 text-purple-300' : 'bg-purple-100 text-purple-600';
    else if (role.includes('Operador')) badgeClass = isNight ? 'bg-blue-900/40 text-blue-300' : 'bg-blue-100 text-blue-600';
    else if (role.includes('Auxiliar')) badgeClass = isNight ? 'bg-orange-900/40 text-orange-300' : 'bg-orange-100 text-orange-600';
    else badgeClass = isNight ? 'bg-slate-700 text-slate-300' : 'bg-slate-200 text-slate-600';

    if (employee.status === 'Férias') {
        bgClass = isNight ? 'bg-orange-900/20 border-orange-800' : 'bg-orange-50 border-orange-200';
        textClass = 'text-orange-600';
    } else if (employee.status === 'Atestado') {
        bgClass = isNight ? 'bg-purple-900/20 border-purple-800' : 'bg-purple-50 border-purple-200';
        textClass = 'text-purple-600';
    }

    return (
        <div className="flex items-center gap-1 group/slot">
            <button 
                onClick={() => {
                    setSelectedEmployee(employee);
                    setNewEmployeeSlot(undefined);
                    setIsEmployeeModalOpen(true);
                }}
                className={`flex-1 flex items-center justify-between p-1 rounded border transition-all hover:brightness-95 ${bgClass} ${isNight ? 'border-transparent' : 'border-transparent'}`}
            >
                <span className={`text-[9px] font-bold truncate ${textClass}`}>
                    {employee.name}
                </span>
                <div className="flex gap-1">
                    {employee.status !== 'Ativo' && (
                        <span className="text-[7px] font-black px-1 py-0.5 rounded uppercase bg-white/50 text-slate-500">
                            {employee.status[0]}
                        </span>
                    )}
                    <span className={`text-[7px] font-black px-1 py-0.5 rounded uppercase ${badgeClass}`}>
                        {role.split(' ')[0].substring(0, 3)}{role.split(' ')[1] || ''}
                    </span>
                </div>
            </button>
            <button 
                onClick={() => handleRemoveSlot(sector, machine, shift, slotIndex, employee)}
                className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover/slot:opacity-100 transition-opacity"
                title="Remover Colaborador/Vaga"
            >
                <UserMinus size={12}/>
            </button>
        </div>
    );
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
  }

  const isGoalReached = totals.month >= goalValue;

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-slate-200/50 rounded-2xl w-fit">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            {/* Filter div was removed from here */}

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <button 
                onClick={() => setSelectedTimeframe('month')} 
                className={`p-6 rounded-3xl text-left transition-all relative overflow-hidden ${
                  selectedTimeframe === 'month' 
                    ? (isGoalReached ? 'bg-blue-600 animate-goal-reached' : 'bg-blue-600') 
                    : 'bg-white border border-slate-100'
                } ${selectedTimeframe === 'month' ? 'text-white shadow-xl' : 'text-slate-800'}`}
              >
                 {isGoalReached && <div className="absolute top-2 right-2 text-white/40"><Target size={40} /></div>}

                 {/* Header Reestruturado */}
                 <div className="flex justify-between items-start mb-3">
                    <div>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Desempenho</p>
                        <h2 className={`text-lg font-black uppercase tracking-tight ${selectedTimeframe === 'month' ? 'text-white' : 'text-slate-800'}`}>Meta Mensal</h2>
                    </div>
                    <div className={`p-2 rounded-xl ${selectedTimeframe === 'month' ? 'bg-white/20' : 'bg-slate-100'}`}>
                        {isGoalReached ? <Target size={20} className="text-white"/> : <Target size={20} className="text-slate-400"/>}
                    </div>
                 </div>

                 {/* Destaque Principal */}
                 <div className="flex items-end gap-2 mb-4">
                    <span className="text-4xl font-black">{formatWeight(totals.month)}</span>
                    <span className={`text-xs font-bold mb-1.5 ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>
                        / {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%
                    </span>
                 </div>

                 {/* Barra de Progresso Melhorada */}
                 <div className={`w-full h-3 rounded-full overflow-hidden mb-5 ${selectedTimeframe === 'month' ? 'bg-black/20' : 'bg-slate-100'}`}>
                    <div className={`${selectedTimeframe === 'month' ? 'bg-white' : 'bg-blue-600'} h-full transition-all duration-1000 ease-out`} style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>

                 {/* Grid de Detalhes */}
                 <div className="grid grid-cols-2 gap-3">
                   <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                      <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Objetivo</p>
                      <p className="text-xs font-black">{formatWeight(goalValue)}</p>
                   </div>
                   {!isGoalReached && (
                       <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                          <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-red-400'}`}>Falta</p>
                          <p className="text-xs font-black">{formatWeight(totals.remaining)}</p>
                       </div>
                   )}
                   {!isGoalReached && (
                       <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                          <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Média Nec.</p>
                          <p className="text-xs font-black">{formatWeight(totals.dailyRequired)}/dia</p>
                       </div>
                   )}
                   <div className={`p-2 rounded-xl border relative group/proj cursor-help ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                      <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-emerald-500'}`}>Projeção</p>
                      <p className="text-xs font-black">{formatWeight(totals.projection)}</p>
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-48 p-3 bg-slate-800 text-white text-[10px] rounded-xl shadow-xl opacity-0 group-hover/proj:opacity-100 transition-opacity pointer-events-none z-50">
                          <p className="font-bold mb-1">O que é isso?</p>
                          <p className="leading-relaxed opacity-80 font-medium">Estimativa do resultado final do mês se o ritmo atual (média diária) for mantido.</p>
                          <div className="absolute -bottom-1 left-1/2 -translate-x-1/2 w-2 h-2 bg-slate-800 rotate-45"></div>
                      </div>
                   </div>
                 </div>
              </button>

              <button onClick={() => setSelectedTimeframe('yesterday')} className={`p-6 rounded-3xl text-left transition-all ${selectedTimeframe === 'yesterday' ? 'bg-emerald-600 text-white shadow-xl' : 'bg-white border border-slate-100 text-slate-800'}`}>
                 <div className="flex justify-between items-start mb-4">
                     <div>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>Diário</p>
