import React, { useState, useEffect } from 'react';
import { 
  Briefcase, 
  Clock, 
  Plus, 
  Factory, 
  Layers, 
  LayoutDashboard, 
  Users, 
  Menu,
  X,
  User,
} from 'lucide-react';
import { 
  ProductionEntry, 
  Shift, 
  Employee, 
  PersonnelLog, 
  PersonnelStructure,
  SectorStructureExtrusao,
  SectorStructureStandard
} from './types';
import { INITIAL_DATA, PERSONNEL_DATA, DEFAULT_OPERATORS } from './constants';
import ShiftModal from './components/ShiftModal';
import EmployeeModal from './components/EmployeeModal';
import OperatorModal from './components/OperatorModal';

export const App = () => {
  const [activeTab, setActiveTab] = useState('personnel'); // Set default to personnel to show the snippet content
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // Data State
  const [operators, setOperators] = useState<string[]>(DEFAULT_OPERATORS);
  const [shifts, setShifts] = useState<Shift[]>([
    { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
    { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
    { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
    { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
  ]);
  const [roles, setRoles] = useState<string[]>(['Operador', 'Líder', 'Auxiliar', 'Extrusor', 'Bobinador']);

  const [personnelStructure, setPersonnelStructure] = useState<PersonnelStructure>({
    extrusao: [],
    erema: [],
    fitaAdesiva: []
  });

  useEffect(() => {
    const extrusao: SectorStructureExtrusao[] = PERSONNEL_DATA.extrusao.map(s => ({
      shift: s.shift,
      machines: s.machines.map(m => ({
        name: m.name,
        roles: m.team
      }))
    }));

    const erema: SectorStructureStandard[] = PERSONNEL_DATA.erema.map(m => ({
      name: m.name,
      shifts: m.shifts.map(s => ({
        name: s.name,
        roles: s.team
      }))
    }));

    const fitaAdesiva: SectorStructureStandard[] = PERSONNEL_DATA.fitaAdesiva.map(m => ({
      name: m.name,
      shifts: m.shifts.map(s => ({
        name: s.name,
        roles: s.team
      }))
    }));

    setPersonnelStructure({ extrusao, erema, fitaAdesiva });
  }, []);

  // Modals
  const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [isOperatorModalOpen, setIsOperatorModalOpen] = useState(false);

  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [selectedSlot, setSelectedSlot] = useState<{sector: string, machine: string, shift: string, role: string} | undefined>(undefined);

  const handleAddSlot = (sector: keyof PersonnelStructure, machineName: string, shiftName: string) => {
    setPersonnelStructure(prev => {
        const newStructure = { ...prev };

        if (sector === 'extrusao') {
            const shiftIndex = newStructure.extrusao.findIndex(s => s.shift === shiftName);
            if (shiftIndex >= 0) {
                const machineIndex = newStructure.extrusao[shiftIndex].machines.findIndex(m => m.name === machineName);
                if (machineIndex >= 0) {
                    // Create a copy of the array before pushing
                    const machines = [...newStructure.extrusao[shiftIndex].machines];
                    machines[machineIndex] = {
                        ...machines[machineIndex],
                        roles: [...machines[machineIndex].roles, 'Vago']
                    };
                    newStructure.extrusao[shiftIndex] = {
                        ...newStructure.extrusao[shiftIndex],
                        machines
                    };
                }
            }
        } else {
            // erema or fitaAdesiva
            const sectorData = [...(newStructure[sector] as SectorStructureStandard[])];
            const machineIndex = sectorData.findIndex(m => m.name === machineName);
            if (machineIndex >= 0) {
                const shifts = [...sectorData[machineIndex].shifts];
                const shiftIndex = shifts.findIndex(s => s.name === shiftName);
                if (shiftIndex >= 0) {
                    shifts[shiftIndex] = {
                        ...shifts[shiftIndex],
                        roles: [...shifts[shiftIndex].roles, 'Vago']
                    };
                    sectorData[machineIndex] = {
                        ...sectorData[machineIndex],
                        shifts
                    };
                    newStructure[sector] = sectorData as any;
                }
            }
        }
        return newStructure;
    });
  };

  const handleSlotClick = (sector: string, machine: string, shift: string, role: string, index: number) => {
      const isVago = role === 'Vago';
      setSelectedSlot({ sector, machine, shift, role: isVago ? 'Operador' : role });
      setSelectedEmployee(isVago ? null : {
          id: 'temp-id',
          name: role,
          role: 'Operador',
          sector,
          machine,
          shift,
          status: 'Ativo',
          updatedAt: new Date().toISOString()
      });
      setIsEmployeeModalOpen(true);
  };

  const renderPersonnelSlot = (
    sector: string, 
    machine: string, 
    shift: string, 
    role: string, 
    isNight: boolean, 
    index: number,
    allRoles: string[]
  ) => {
    const isVago = role === 'Vago' || !role;

    return (
      <div 
        onClick={() => handleSlotClick(sector, machine, shift, role, index)}
        className={`
          flex items-center gap-2 p-1.5 rounded-lg cursor-pointer transition-all border
