                </button>
                <button 
                  onClick={() => handleRemoveSlot(sector, machine, shift, slotIndex)}
                  className="p-1 text-slate-300 hover:text-red-500 opacity-0 group-hover/slot:opacity-100 transition-opacity"
                  title="Remover Vaga"
                >
                  <UserMinus size={12}/>
                </button>
            </div>
        );
    }

    let bgClass = isNight ? 'bg-slate-800/50' : 'bg-slate-50';
    let textClass = isNight ? 'text-slate-200' : 'text-slate-700';

