    const roleOccurrenceIndex = siblingsRoles.slice(0, slotIndex).filter(r => r === role).length;

    const potentialEmployees = employees.filter(e => 
        e.sector === fullSectorName && 
        e.machine === machine && 
        e.shift === shift && 
        e.role === role &&
        e.status !== 'Desligado'
