    else if (role.includes('Operador')) badgeClass = isNight ? 'bg-blue-900/40 text-blue-300' : 'bg-blue-100 text-blue-600';
    else if (role.includes('Auxiliar')) badgeClass = isNight ? 'bg-orange-900/40 text-orange-300' : 'bg-orange-100 text-orange-600';
    else badgeClass = isNight ? 'bg-slate-700 text-slate-300' : 'bg-slate-200 text-slate-600';

    if (employee.status === 'Férias') {
