                        / {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%
                    </span>
                 </div>

                 <div className={`w-full h-3 rounded-full overflow-hidden mb-5 ${selectedTimeframe === 'month' ? 'bg-black/20' : 'bg-slate-100'}`}>
                    <div className={`${selectedTimeframe === 'month' ? 'bg-white' : 'bg-blue-600'} h-full transition-all duration-1000 ease-out`} style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                   <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                      <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Objetivo</p>
                      <p className="text-xs font-black">{formatWeight(goalValue)}</p>
                   </div>
                   {!isGoalReached && (
                       <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                          <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-red-400'}`}>Falta</p>
                          <p className="text-xs font-black">{formatWeight(totals.remaining)}</p>
                       </div>
                   )}
                   {!isGoalReached && (
                       <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                          <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Média Nec.</p>
                          <p className="text-xs font-black">{formatWeight(totals.dailyRequired)}/dia</p>
                       </div>
                   )}
                   <div className={`p-2 rounded-xl border relative group/proj cursor-help ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                      <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-emerald-500'}`}>Projeção</p>
                      <p className="text-xs font-black">{formatWeight(totals.projection)}</p>
                   </div>
                 </div>
              </button>

              {isRangeFiltered ? (
                /* Card Unificado para Período Selecionado */
                <div className="md:col-span-2 p-8 rounded-[2rem] text-left bg-[#4f46e5] text-white shadow-xl flex flex-col justify-between animate-in zoom-in-95 duration-300 relative">

                  <div className="flex justify-between items-start">
                    <div className="space-y-1">
                      <p className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-100 opacity-80">Filtro de Período</p>
                      <h2 className="text-2xl font-black uppercase tracking-tight text-white flex items-center gap-3">
                        <Calendar size={26} className="text-indigo-200" />
                        PRODUÇÃO NO PERÍODO
                      </h2>
                    </div>

                    <div className="bg-indigo-400/20 backdrop-blur-md px-5 py-3 rounded-2xl flex items-center gap-3 border border-white/10">
                        <Clock size={18} className="text-indigo-100" /> 
                        <span className="text-[11px] font-black tracking-tight">
                          {dashStartDate ? new Date(dashStartDate).toLocaleDateString('pt-BR') : '...'} 
                          {' a '} 
                          {dashEndDate ? new Date(dashEndDate).toLocaleDateString('pt-BR') : '...'}
                        </span>
                    </div>
                  </div>

                  <div className="flex items-center justify-between gap-10 my-10">
                    <div className="flex items-baseline gap-2">
                      <h2 className="text-8xl font-black tracking-tighter leading-none">{formatWeight(totals.range).split(' ')[0]}</h2>
                      <span className="text-6xl font-black text-indigo-200/60 leading-none">{formatWeight(totals.range).split(' ')[1]}</span>
                    </div>

                    <div className="bg-white/10 backdrop-blur-sm p-6 rounded-[1.5rem] border border-white/10 max-w-[200px]">
                       <p className="text-[10px] font-black uppercase tracking-widest text-indigo-100 mb-2">TOTAL ACUMULADO</p>
                       <p className="text-[11px] font-bold leading-relaxed opacity-70">Baseado nos filtros ativos de operador e máquina.</p>
                    </div>
                  </div>

                  <div className="flex items-center gap-3 p-4 bg-indigo-900/30 rounded-2xl border border-white/5">
                    <AlertTriangle size={18} className="text-indigo-200 shrink-0" />
                    <p className="text-[10px] font-black uppercase tracking-[0.1em] text-indigo-100/60">
                      OS GRÁFICOS ABAIXO REFLETEM EXCLUSIVAMENTE ESTES DADOS
                    </p>
                  </div>
                </div>
              ) : (
                <>
                  {/* Cards de Ontem e Semana - Apenas se não houver filtro de range */}
                  <button onClick={() => setSelectedTimeframe('yesterday')} className={`p-6 rounded-3xl text-left transition-all ${selectedTimeframe === 'yesterday' ? 'bg-emerald-600 text-white shadow-xl' : 'bg-white border border-slate-100 text-slate-800'}`}>
                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'yesterday' ? 'text-emerald-100' : 'text-slate-400'}`}>Diário</p>
                            <h2 className={`text-lg font-black uppercase tracking-tight ${selectedTimeframe === 'yesterday' ? 'text-white' : 'text-slate-800'}`}>Produção Ontem</h2>
                        </div>
                        <div className={`p-2 rounded-xl ${selectedTimeframe === 'yesterday' ? 'bg-white/20' : 'bg-slate-100'}`}>
                            <TrendingUp size={20} className={selectedTimeframe === 'yesterday' ? 'text-white' : 'text-slate-400'} />
                        </div>
                    </div>
                    <h2 className="text-4xl font-black mt-2">{formatWeight(totals.yesterday)}</h2>
                    <p className="text-[11px] mt-2 opacity-80 font-bold">Acumulado diário</p>
                  </button>

                  <button onClick={() => setSelectedTimeframe('week')} className={`p-6 rounded-3xl text-left transition-all ${selectedTimeframe === 'week' ? 'bg-violet-600 text-white shadow-xl' : 'bg-white border border-slate-100 text-slate-800'}`}>
                    <div className="flex justify-between items-start mb-4">
                        <div>
                            <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'week' ? 'text-violet-100' : 'text-slate-400'}`}>Semanal</p>
                            <h2 className={`text-lg font-black uppercase tracking-tight ${selectedTimeframe === 'week' ? 'text-white' : 'text-slate-800'}`}>Produção 7 Dias</h2>
                        </div>
                        <div className={`p-2 rounded-xl ${selectedTimeframe === 'week' ? 'bg-white/20' : 'bg-slate-100'}`}>
                            <Clock size={20} className={selectedTimeframe === 'week' ? 'text-white' : 'text-slate-400'} />
                        </div>
                    </div>
                    <h2 className="text-4xl font-black mt-2">{formatWeight(totals.week)}</h2>
                    <p className="text-[11px] mt-2 opacity-80 font-bold">Últimos 7 dias</p>
                  </button>
                </>
              )}
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allCharts.map((chart, idx) => {
                let chartData: any[] = [];
                let dataKey = chart.key;
                const isOperatorChart = !chart.key.startsWith('comparison_');

                if (chart.key === 'comparison_prod_ecob') {
                  const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                  const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                  chartData = [{ name: 'Produção', value: totalProd }, { name: 'Eco B', value: totalEcoB }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_prod_borra') {
                  const totalProd = filteredDataForCharts.reduce((acc, c) => acc + (c.netWeight || 0), 0);
                  const totalBorra = filteredDataForCharts.reduce((acc, c) => acc + (c.borraTotal || 0), 0);
                  chartData = [{ name: 'Produção', value: totalProd }, { name: 'Borra', value: totalBorra }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_ecob_recycled') {
                  const totalEcoB = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoBP || 0) + (c.ecoBM || 0), 0);
                  const totalRecycled = filteredDataForCharts.reduce((acc, c) => acc + (c.ecoA || 0), 0);
                  chartData = [{ name: 'Eco B', value: totalEcoB }, { name: 'Reciclado', value: totalRecycled }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else if (chart.key === 'comparison_time') {
                  let totalAvailable = 0; let totalDowntime = 0;
                  filteredDataForCharts.forEach(item => { const shiftDuration = getShiftDuration(item.shift); totalAvailable += shiftDuration; totalDowntime += (item.manutencaoMin || 0) + (item.processoMin || 0) + (item.outrosMin || 0); });
                  const totalRunning = Math.max(0, totalAvailable - totalDowntime);
                  chartData = [{ name: 'Operação', value: totalRunning }, { name: 'Parada', value: totalDowntime }].filter(d => d.value > 0);
                  dataKey = 'value';
                } else {
                  chartData = stats.filter(s => (s[chart.key as keyof OperatorStat] as number) > 0).map(s => ({
                    ...s,
                    value: s[chart.key as keyof OperatorStat]
                  }));
                }

                // Ordenação decrescente: maior para menor
                chartData.sort((a, b) => {
                  const valA = a.value || 0;
                  const valB = b.value || 0;
                  return valB - valA;
                });

                if (chartData.length === 0) return null;
                const cardId = `chart-card-${idx}`;
                return (
                  <div key={idx} id={cardId} className="bg-white rounded-3xl p-6 shadow-sm border border-slate-100 h-[520px] flex flex-col group/card hover:shadow-xl transition-all">
                    <div className="flex justify-between items-start mb-2">
                      <h3 className="font-black text-xs uppercase tracking-widest text-slate-800">{chart.title}</h3>
                      <button onClick={() => handleDownloadChartPNG(cardId, chart.title)} className="p-1.5 text-slate-300 hover:text-blue-600 no-print"> <ImageIcon size={16} /> </button>
                    </div>
                    <p className="text-[9px] text-slate-400 font-bold uppercase tracking-wider mb-4 leading-tight">{chart.description}</p>
                    <div className="flex-1">
                       <ResponsiveContainer width="100%" height="100%">
                         <PieChart>
                           <Pie 
                             data={chartData} 
                             cx="50%" 
                             cy="50%" 
                             innerRadius={60} 
                             outerRadius={85} 
                             dataKey="value" 
                             nameKey="name" 
                             label={renderCustomizedLabel} 
                             paddingAngle={2}
                           >
                             {chartData.map((_, i) => <Cell key={i} fill={COLORS[i % COLORS.length]} />)}
                           </Pie>
                           <Tooltip formatter={(v: any) => chart.formatter(v)} />
                           <Legend 
                            iconType="circle" 
                            align="center" 
                            verticalAlign="bottom" 
                            formatter={(value, entry: any) => {
                              const val = entry.payload.value;
                              return <span className="text-slate-700">{value}: <span className="font-black">{chart.formatter(val)}</span></span>;
                            }}
                            wrapperStyle={{ fontSize: '10px', paddingTop: '20px' }} 
                          />
                         </PieChart>
                       </ResponsiveContainer>
                    </div>
                  </div>
                );
              })}
            </div>
