        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-slate-200/50 rounded-2xl w-fit">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-white text-blue-600 shadow-md' : 'text-slate-500 hover:text-slate-700'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Card Meta Mensal */}
              <button 
                onClick={() => setSelectedTimeframe('month')} 
                className={`p-6 rounded-3xl text-left transition-all relative overflow-hidden ${
                  selectedTimeframe === 'month' 
                    ? (isGoalReached ? 'bg-blue-600 animate-goal-reached' : 'bg-blue-600') 
                    : 'bg-white border border-slate-100'
                } ${selectedTimeframe === 'month' ? 'text-white shadow-xl' : 'text-slate-800'}`}
              >
                 {isGoalReached && <div className="absolute top-2 right-2 text-white/40"><Target size={40} /></div>}

                 <div className="flex justify-between items-start mb-3">
                    <div>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Desempenho</p>
                        <h2 className={`text-lg font-black uppercase tracking-tight ${selectedTimeframe === 'month' ? 'text-white' : 'text-slate-800'}`}>Meta Mensal</h2>
                    </div>
                    <div className={`p-2 rounded-xl ${selectedTimeframe === 'month' ? 'bg-white/20' : 'bg-slate-100'}`}>
                        {isGoalReached ? <Target size={20} className="text-white"/> : <Target size={20} className="text-slate-400"/>}
                    </div>
                 </div>

                 <div className="flex items-end gap-2 mb-4">
                    <span className="text-4xl font-black">{formatWeight(totals.month)}</span>
                    <span className={`text-xs font-bold mb-1.5 ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>
                        / {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%
                    </span>
                 </div>

                 <div className={`w-full h-3 rounded-full overflow-hidden mb-5 ${selectedTimeframe === 'month' ? 'bg-black/20' : 'bg-slate-100'}`}>
                    <div className={`${selectedTimeframe === 'month' ? 'bg-white' : 'bg-blue-600'} h-full transition-all duration-1000 ease-out`} style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                   <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                      <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Objetivo</p>
                      <p className="text-xs font-black">{formatWeight(goalValue)}</p>
                   </div>
                   {!isGoalReached && (
                       <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                          <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-red-400'}`}>Falta</p>
                          <p className="text-xs font-black">{formatWeight(totals.remaining)}</p>
                       </div>
                   )}
                   {!isGoalReached && (
                       <div className={`p-2 rounded-xl border ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                          <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Média Nec.</p>
                          <p className="text-xs font-black">{formatWeight(totals.dailyRequired)}/dia</p>
                       </div>
                   )}
                   <div className={`p-2 rounded-xl border relative group/proj cursor-help ${selectedTimeframe === 'month' ? 'bg-white/10 border-white/10' : 'bg-slate-50 border-slate-100'}`}>
                      <p className={`text-[9px] font-black uppercase ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-emerald-500'}`}>Projeção</p>
                      <p className="text-xs font-black">{formatWeight(totals.projection)}</p>
                   </div>
                 </div>
              </button>

              {isRangeFiltered ? (
                /* Card Unificado para Período Selecionado */
                <div className="md:col-span-2 p-8 rounded-[2rem] text-left bg-[#4f46e5] text-white shadow-xl flex flex-col justify-between animate-in zoom-in-95 duration-300 relative">

                  <div className="flex justify-between items-start">
                    <div className="space-y-1">
                      <p className="text-[10px] font-black uppercase tracking-[0.2em] text-indigo-100 opacity-80">Filtro de Período</p>
                      <h2 className="text-2xl font-black uppercase tracking-tight text-white flex items-center gap-3">
                        <Calendar size={26} className="text-indigo-200" />
                        <span>{selectedTimeframe === 'today' ? 'Hoje' : selectedTimeframe === 'yesterday' ? 'Ontem' : selectedTimeframe === 'week' ? 'Esta Semana' : 'Este Mês'}</span>
                      </h2>
                    </div>
                    <div className="flex gap-2">
                       <button onClick={() => { setDashStartDate(''); setDashEndDate(''); }} className="bg-white/20 hover:bg-white/30 text-white p-2 rounded-xl transition-all"><RotateCcw size={16}/></button>
                    </div>
                  </div>

                  <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mt-6">
                     <div className="bg-indigo-900/30 p-4 rounded-2xl backdrop-blur-sm border border-indigo-400/20">
                        <div className="text-indigo-200 mb-1"><Layers size={20}/></div>
                        <p className="text-[9px] font-black uppercase tracking-widest text-indigo-300">Produção Total</p>
                        <p className="text-2xl font-black">{formatWeight(totals.range)}</p>
                     </div>
                     <div className="bg-indigo-900/30 p-4 rounded-2xl backdrop-blur-sm border border-indigo-400/20">
                         <div className="text-emerald-300 mb-1"><TrendingUp size={20}/></div>
                        <p className="text-[9px] font-black uppercase tracking-widest text-indigo-300">Média/Dia</p>
                        <p className="text-2xl font-black">
                            {formatWeight(
                                totals.range / (Math.max(1, Math.ceil((new Date(dashEndDate).getTime() - new Date(dashStartDate).getTime()) / (1000 * 3600 * 24)) + 1))
                            )}
                        </p>
                     </div>
                  </div>
                </div>
              ) : (
                /* Cards de atalho para filtros rápidos (Hoje/Ontem/Semana) */
                <div className="md:col-span-2 grid grid-cols-1 sm:grid-cols-3 gap-6">
                    {['today', 'yesterday', 'week'].map(timeframe => {
                        const isSelected = selectedTimeframe === timeframe;
                        const value = timeframe === 'today' ? totals.today : timeframe === 'yesterday' ? totals.yesterday : totals.week;
                        const label = timeframe === 'today' ? 'Hoje' : timeframe === 'yesterday' ? 'Ontem' : 'Semana Atual';
                        const icon = timeframe === 'today' ? <Clock size={20} /> : timeframe === 'yesterday' ? <History size={20} /> : <Calendar size={20} />;

                        return (
                            <button 
                                key={timeframe}
                                onClick={() => setSelectedTimeframe(timeframe as any)}
                                className={`p-6 rounded-3xl text-left transition-all border group relative overflow-hidden ${
                                    isSelected 
                                    ? 'bg-slate-800 text-white shadow-xl border-transparent scale-[1.02]' 
                                    : 'bg-white text-slate-600 border-slate-100 hover:border-blue-200 hover:shadow-lg'
                                }`}
                            >
                                <div className={`absolute top-0 right-0 p-6 opacity-10 transition-transform group-hover:scale-110 ${isSelected ? 'text-white' : 'text-blue-600'}`}>
                                    {timeframe === 'today' ? <Target size={80} /> : timeframe === 'yesterday' ? <RotateCcw size={80} /> : <Layers size={80} />}
                                </div>

                                <div className="flex justify-between items-start mb-6 relative z-10">
                                    <div className={`p-3 rounded-2xl ${isSelected ? 'bg-white/10 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-blue-50 group-hover:text-blue-600'} transition-colors`}>
                                        {icon}
                                    </div>
                                    {isSelected && <div className="bg-green-500 w-2 h-2 rounded-full animate-pulse"></div>}
                                </div>

                                <div className="relative z-10">
                                    <p className={`text-[10px] font-black uppercase tracking-widest mb-1 ${isSelected ? 'text-slate-400' : 'text-slate-400'}`}>{label}</p>
                                    <p className={`text-2xl font-black ${isSelected ? 'text-white' : 'text-slate-800'}`}>{formatWeight(value)}</p>
                                </div>
                            </button>
                        );
                    })}
                </div>
              )}
            </div>

            {/* Gráficos em Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allCharts.map((chart, idx) => {
                 let data: any[] = [];
                 const isComparison = chart.key.startsWith('comparison_');

                 if (isComparison) {
                     if (chart.key === 'comparison_prod_ecob') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) }
                        ];
                     } else if (chart.key === 'comparison_prod_borra') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Borra', value: stats.reduce((acc, s) => acc + s.borra, 0) }
                        ];
                     } else if (chart.key === 'comparison_ecob_recycled') {
                         data = [
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) },
                            { name: 'Eco A', value: stats.reduce((acc, s) => acc + s.ecoA, 0) }
                        ];
                     } else if (chart.key === 'comparison_time') {
                         const totalTime = stats.reduce((acc, s) => acc + s.p_manut + s.p_proc + s.p_outros, 0);
                         const totalProd = stats.reduce((acc, s) => acc + s.prod, 0); // Mock ratio for demo
                         data = [
                            { name: 'Operando', value: 1000 }, 
                            { name: 'Parado', value: totalTime }
                         ];
                     }
                 } else {
                     data = stats.map(s => ({ 
                        name: s.name, 
                        value: (s as any)[chart.key] 
                     })).filter(i => i.value > 0);
                 }

                 if (data.length === 0) return null;

                 return (
                  <div id={`chart-${idx}`} key={idx} className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300 group">
                    <div className="flex justify-between items-start mb-6">
                      <div>
                        <h3 className="text-sm font-black uppercase text-slate-800 tracking-tight">{chart.title}</h3>
                        <p className="text-[10px] text-slate-400 font-medium">{chart.description}</p>
                      </div>
                      <button onClick={() => handleDownloadChartPNG(`chart-${idx}`, chart.title)} className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all opacity-0 group-hover:opacity-100">
                        <Download size={16} />
                      </button>
                    </div>
                    <div className="h-64 relative">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie
                            data={data}
                            cx="50%"
                            cy="50%"
                            innerRadius={60}
                            outerRadius={80}
                            paddingAngle={5}
                            dataKey="value"
                            stroke="none"
