                    {employee.status !== 'Ativo' && (
                        <span className="text-[8px] font-black px-1 py-0.5 rounded uppercase bg-white/50 text-slate-500">
                            {employee.status[0]}
                        </span>
                    )}
                    <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${badgeClass}`}>
                        {role.includes('Operador') ? 'OPE1' : role.includes('Auxiliar') ? 'AUX1' : 'LÍDER'}
                    </span>
                </div>
            </button>
        </div>
    );
  };

  const isRangeFiltered = dashStartDate || dashEndDate;

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
  }

  const isGoalReached = totals.month >= goalValue;

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              {/* Card Meta Mensal */}
              <button 
                onClick={() => setSelectedTimeframe('month')} 
                className={`p-6 rounded-3xl text-left transition-all relative overflow-hidden ${
                  selectedTimeframe === 'month' 
                    ? (isGoalReached ? 'bg-blue-600 animate-goal-reached' : 'bg-blue-600') 
                    : 'bg-white border border-slate-100'
                } ${selectedTimeframe === 'month' ? 'text-white shadow-xl' : 'text-slate-800'}`}
              >
                 {isGoalReached && <div className="absolute top-2 right-2 text-white/40"><Target size={40} /></div>}

                 <div className="flex justify-between items-start mb-3">
                    <div>
                        <p className={`text-[10px] font-black uppercase tracking-widest ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>Desempenho</p>
                        <h2 className={`text-lg font-black uppercase tracking-tight ${selectedTimeframe === 'month' ? 'text-white' : 'text-slate-800'}`}>Meta Mensal</h2>
                    </div>
                    <div className={`p-2 rounded-xl ${selectedTimeframe === 'month' ? 'bg-white/20' : 'bg-slate-100'}`}>
                        {isGoalReached ? <Target size={20} className="text-white"/> : <Target size={20} className="text-slate-400"/>}
