                 <div className="flex items-end gap-2 mb-4">
                    <span className="text-4xl font-black">{formatWeight(totals.month)}</span>
                    <span className={`text-xs font-bold mb-1.5 ${selectedTimeframe === 'month' ? 'text-blue-100' : 'text-slate-400'}`}>
                        / {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%
                    </span>
                 </div>

                 <div className={`w-full h-3 rounded-full overflow-hidden mb-5 ${selectedTimeframe === 'month' ? 'bg-black/20' : 'bg-slate-100'}`}>
                    <div className={`${selectedTimeframe === 'month' ? 'bg-white' : 'bg-blue-600'} h-full transition-all duration-1000 ease-out`} style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>

