                    {['today', 'yesterday', 'week'].map(timeframe => {
                        const isSelected = selectedTimeframe === timeframe;
                        const value = timeframe === 'today' ? totals.today : timeframe === 'yesterday' ? totals.yesterday : totals.week;
                        const label = timeframe === 'today' ? 'Hoje' : timeframe === 'yesterday' ? 'Ontem' : 'Semana Atual';
                        const icon = timeframe === 'today' ? <Clock size={20} /> : timeframe === 'yesterday' ? <History size={20} /> : <Calendar size={20} />;

                        return (
                            <button 
