                 let data: any[] = [];
                 const isComparison = chart.key.startsWith('comparison_');

                 if (isComparison) {
                     if (chart.key === 'comparison_prod_ecob') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) }
                        ];
                     } else if (chart.key === 'comparison_prod_borra') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Borra', value: stats.reduce((acc, s) => acc + s.borra, 0) }
                        ];
                     } else if (chart.key === 'comparison_ecob_recycled') {
                         data = [
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) },
                            { name: 'Eco A', value: stats.reduce((acc, s) => acc + s.ecoA, 0) }
                        ];
                     } else if (chart.key === 'comparison_time') {
                         const totalTime = stats.reduce((acc, s) => acc + s.p_manut + s.p_proc + s.p_outros, 0);
                         const totalProd = stats.reduce((acc, s) => acc + s.prod, 0); // Mock ratio for demo
                         data = [
                            { name: 'Operando', value: 1000 }, 
                            { name: 'Parado', value: totalTime }
                         ];
                     }
                 } else {
                     data = stats.map(s => ({ 
                        name: s.name, 
                        value: (s as any)[chart.key] 
                     })).filter(i => i.value > 0);
