                     <div className="mt-6">
                        <span className="text-4xl font-black text-slate-800">{formatWeight(totals.week)}</span>
                        <p className="text-xs font-bold text-slate-400 mt-1">Últimos 7 dias</p>
                     </div>
                  </div>
              </div>
            </div>

            {/* Gráficos em Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allCharts.map((chart, idx) => {
                 let data: any[] = [];
                 const isComparison = chart.key.startsWith('comparison_');

                 if (isComparison) {
                     if (chart.key === 'comparison_prod_ecob') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) }
                        ];
                     } else if (chart.key === 'comparison_prod_borra') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Borra', value: stats.reduce((acc, s) => acc + s.borra, 0) }
                        ];
                     } else if (chart.key === 'comparison_ecob_recycled') {
                         data = [
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) },
                            { name: 'Eco A', value: stats.reduce((acc, s) => acc + s.ecoA, 0) }
                        ];
                     } else if (chart.key === 'comparison_time') {
                         const totalTime = stats.reduce((acc, s) => acc + s.p_manut + s.p_proc + s.p_outros, 0);
                         const totalProd = stats.reduce((acc, s) => acc + s.prod, 0); // Mock ratio for demo
                         data = [
                            { name: 'Operando', value: 1000 }, 
                            { name: 'Parado', value: totalTime }
                         ];
                     }
                 } else {
                     data = stats.map(s => ({ 
                        name: s.name, 
                        value: (s as any)[chart.key] 
                     })).filter(i => i.value > 0);
                 }

                 if (data.length === 0) return null;

                 // Sort data descending for rank
                 data.sort((a, b) => b.value - a.value);

                 return (
                  <div id={`chart-${idx}`} key={idx} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300 group flex flex-col">
                    {/* Header */}
                    <div className="flex justify-between items-start mb-6">
                      <div>
                        <h3 className="text-sm font-black uppercase text-slate-800 tracking-tight flex items-center gap-2">
                           {idx === 0 && <span className="text-yellow-500">🏆</span>} {chart.title}
                        </h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wide mt-1">{chart.description}</p>
                      </div>
                      <button onClick={() => handleDownloadChartPNG(`chart-${idx}`, chart.title)} className="p-2 text-blue-500 bg-blue-50 rounded-xl hover:bg-blue-100 transition-all">
                        <ImageIcon size={18} />
