const formatWeight = (value: number) => {
  if (value === undefined || value === null) return '0 kg';
  return new Intl.NumberFormat('pt-BR', { minimumFractionDigits: 0, maximumFractionDigits: 0 }).format(value) + ' kg';
};

const formatMinutes = (value: number) => {
  if (value === undefined || value === null) return '0 min';
  return `${value} min`;
};

