                     } else if (chart.key === 'comparison_ecob_recycled') {
                         const totalErema = filteredDataForCharts
                            .filter(e => e.machine.toLowerCase().includes('erema'))
                            .reduce((acc, e) => acc + (e.netWeight || 0), 0);

                         const totalEcoB = stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0);

                         data = [
                            { name: 'Eco B', value: totalEcoB },
                            { name: 'Reciclado (Erema)', value: totalErema }
                        ];
                     } else if (chart.key === 'comparison_time') {
                         const totalTime = stats.reduce((acc, s) => acc + s.p_manut + s.p_proc + s.p_outros, 0);
