const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.03) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.2;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text 
      x={x} 
      y={y} 
      fill="#64748b" 
      textAnchor={x > cx ? 'start' : 'end'} 
      dominantBaseline="central" 
      className="text-[11px] font-black"
    >
      {`${(percent * 100).toFixed(1)}%`}
    </text>
  );
};

interface OperatorStat {
  name: string;
  prod: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borra: number;
  p_manut: number;
  p_proc: number;
  p_outros: number;
}

// Configuração fixa da hierarquia
const DEFAULT_HIERARCHY = [
  'Líder de Turno',
  'Operador 1',
  'Operador 2',
  'Operador 3',
  'Auxiliar 1',
  'Auxiliar 2'
];

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>(() => {
    return (localStorage.getItem('manupackaging_active_tab') as 'dashboard' | 'reports' | 'personnel') || 'dashboard';
  });
  const [selectedTimeframe, setSelectedTimeframe] = useState<'month' | 'today' | 'yesterday' | 'week'>(() => {
    return (localStorage.getItem('manupackaging_timeframe') as 'month' | 'today' | 'yesterday' | 'week') || 'month';
  });

  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);

  const [dashOperator, setDashOperator] = useState('');
  const [dashMachine, setDashMachine] = useState('');
  const [dashStartDate, setDashStartDate] = useState('');
  const [dashEndDate, setDashEndDate] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({
    isOpen: false,
    title: '',
    message: '',
    onConfirm: () => {},
  });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      let data = saved ? JSON.parse(saved) : INITIAL_DATA;
      if (Array.isArray(data)) {
        return data.map((item: any) => ({
          ...item,
          id: item.id || Math.random().toString(36).substr(2, 9)
        }));
      }
      return INITIAL_DATA;
    } catch (e) {
      return INITIAL_DATA;
    }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_operators');
      return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
    } catch (e) {
      return DEFAULT_OPERATORS;
    }
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_shifts');
      return saved ? JSON.parse(saved) : [
        { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '5', name: 'Comercial', startTime: '08:00', endTime: '18:00', type: 'Diurno' }
      ];
    } catch (e) {
      return [
        { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' }
      ];
    }
  });

  // --- PERSONNEL STATE MANAGEMENT ---
  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('manupackaging_employees');
    if (saved) return JSON.parse(saved);

    const initialEmployees: Employee[] = [];
    const getRoleByIndex = (index: number) => {
        return DEFAULT_HIERARCHY[index] || `Auxiliar ${index - 3}`;
    };

    PERSONNEL_DATA.extrusao.forEach(shift => {
        shift.machines.forEach(mach => {
            mach.team.forEach((name, idx) => {
                if (name && name !== 'Vaga') {
                    initialEmployees.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name,
                        role: getRoleByIndex(idx),
                        sector: 'Extrusão',
                        machine: mach.name,
                        shift: shift.shift,
                        status: 'Ativo',
                        updatedAt: new Date().toISOString()
                    });
                }
            });
        });
    });

    PERSONNEL_DATA.erema.forEach(mach => {
        mach.shifts.forEach(shift => {
            shift.team.forEach((name, idx) => {
                if(name && name !== 'Vaga') {
                     initialEmployees.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name,
                        role: getRoleByIndex(idx),
                        sector: 'Reciclagem',
                        machine: mach.name,
                        shift: shift.name,
                        status: 'Ativo',
                        updatedAt: new Date().toISOString()
                    });
                }
            });
        });
    });

    PERSONNEL_DATA.fitaAdesiva.forEach(mach => {
        mach.shifts.forEach(shift => {
             shift.team.forEach((name, idx) => {
                 if(name && name !== 'Vaga') {
                    initialEmployees.push({
                        id: Math.random().toString(36).substr(2, 9),
                        name,
                        role: getRoleByIndex(idx),
                        sector: 'Fita Adesiva',
                        machine: mach.name,
                        shift: shift.name,
                        status: 'Ativo',
                        updatedAt: new Date().toISOString()
                    });
                 }
             });
        });
    });

    return initialEmployees;
  });

  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>(() => {
    const saved = localStorage.getItem('manupackaging_personnel_logs');
    return saved ? JSON.parse(saved) : [];
  });

  const [jobRoles, setJobRoles] = useState<string[]>(() => {
    const saved = localStorage.getItem('manupackaging_roles');
    return saved ? JSON.parse(saved) : DEFAULT_HIERARCHY;
  });

  const [personnelStructure, setPersonnelStructure] = useState<PersonnelStructure>(() => {
    const saved = localStorage.getItem('manupackaging_structure');
    if (saved) return JSON.parse(saved);

    const getRoleByIndex = (index: number) => {
        return DEFAULT_HIERARCHY[index] || `Auxiliar ${index - 3}`;
    };

    return {
      extrusao: PERSONNEL_DATA.extrusao.map(s => ({
        shift: s.shift,
        machines: s.machines.map(m => ({
          name: m.name,
          roles: m.team.map((_, i) => getRoleByIndex(i))
        }))
      })),
      erema: PERSONNEL_DATA.erema.map(m => ({
        name: m.name,
        shifts: m.shifts.map(s => ({
          name: s.name,
          roles: s.team.map((_, i) => getRoleByIndex(i))
        }))
      })),
      fitaAdesiva: PERSONNEL_DATA.fitaAdesiva.map(m => ({
        name: m.name,
        shifts: m.shifts.map(s => ({
          name: s.name,
          roles: s.team.map((_, i) => getRoleByIndex(i))
        }))
      }))
    };
  });

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec'];

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
