  ];

  const getRoleBadge = (role: string) => {
    if (role.includes('Líder')) return 'LÍDER';
    if (role.includes('Operador 1')) return 'OPE1';
    if (role.includes('Operador 2')) return 'OPE2';
    if (role.includes('Operador 3')) return 'OPE3';
    if (role.includes('Auxiliar 1')) return 'AUX1';
    if (role.includes('Auxiliar 2')) return 'AUX2';
    if (role.includes('Auxiliar')) return 'AUXILIAR';
    return role.toUpperCase().substring(0, 4);
  };

  const renderPersonnelSlot = (
    sector: 'extrusao' | 'erema' | 'fitaAdesiva', 
    machine: string, 
    shift: string, 
    role: string, 
    isNight: boolean, 
    slotIndex: number,
