                className={`flex items-center justify-between px-3 py-1.5 rounded border border-dashed w-full transition-all hover:opacity-80 group ${isNight ? 'bg-red-900/10 border-red-800/50' : 'bg-red-50 border-red-200'}`}
            >
                <span className={`text-[10px] font-bold ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Adicionar)</span>
                <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${
                    isNight ? 'bg-red-900/30 text-red-400' : 'bg-red-100 text-red-600'
                }`}>{role === 'Vaga' ? 'AUXILIAR' : roleBadge}</span>
            </button>
        );
    }

    let badgeClass = 'bg-slate-200 text-slate-600';
    if (roleBadge === 'LÍDER') badgeClass = 'bg-purple-100 text-purple-700';
    else if (roleBadge.startsWith('OPE')) badgeClass = 'bg-blue-100 text-blue-700';
    else if (roleBadge.startsWith('AUX')) badgeClass = 'bg-orange-100 text-orange-700';

    if (employee.status === 'Férias') {
        containerClass = isNight ? 'bg-orange-900/10 border-orange-800/30' : 'bg-orange-50 border-orange-100';
        textClass = 'text-orange-600';
    } else if (employee.status === 'Atestado') {
        containerClass = isNight ? 'bg-purple-900/10 border-purple-800/30' : 'bg-purple-50 border-purple-100';
        textClass = 'text-purple-600';
    }

    return (
        <button 
            onClick={() => {
                setSelectedEmployee(employee);
                setNewEmployeeSlot(undefined);
                setIsEmployeeModalOpen(true);
