  const handleExportCSV = () => {
    const dataToExport = filteredReports;
    if (dataToExport.length === 0) {
      alert('Nenhum dado para exportar.');
      return;
    }
    // Headers matching the table columns and using ; as delimiter for Excel PT-BR compatibility
    const headers = ['Data', 'Turno', 'Máquina', 'Operador', 'Peso Bruto', 'Tara', 'Peso Líquido', 'Volumes', 'Tubetes', 'Eco A', 'Eco B (P)', 'Eco B (M)', 'Borra Total', 'Manutencao (min)', 'Processo (min)', 'Outros (min)'];

    // Helper to format numbers for Excel PT-BR (comma as decimal separator)
    const formatNum = (num: number | undefined) => String(num || 0).replace('.', ',');

    const rows = dataToExport.map(e => {
        const dateFormatted = e.date.split('-').reverse().join('/');

        return [
            dateFormatted,
            `"${e.shift}"`,
            `"${e.machine}"`,
            `"${e.operator}"`,
            formatNum(e.grossWeight),
            formatNum(e.tara),
            formatNum(e.netWeight),
            formatNum(e.volumes),
            formatNum(e.tubetes),
            formatNum(e.ecoA),
            formatNum(e.ecoBP),
            formatNum(e.ecoBM),
            formatNum(e.borraTotal),
            formatNum(e.manutencaoMin),
            formatNum(e.processoMin),
            formatNum(e.outrosMin)
        ].join(';');
    });

    // Calculate totals line
    const totalEcoBUnified = reportTotals.ecoBP + reportTotals.ecoBM;

    const totalRow = [
        'TOTAL',           // Data
        '',                // Turno
        '',                // Máquina
        '',                // Operador
        formatNum(reportTotals.gross),
        formatNum(reportTotals.tara),
        formatNum(reportTotals.net),
        formatNum(reportTotals.volumes),
        formatNum(reportTotals.tubetes),
        formatNum(reportTotals.ecoA),
        formatNum(totalEcoBUnified), // Eco B (P) gets the sum
        '',                          // Eco B (M) is empty to simulate "merge" space
        formatNum(reportTotals.borra),
        formatNum(reportTotals.manut),
        formatNum(reportTotals.proc),
        formatNum(reportTotals.outros)
    ].join(';');

    // Add BOM (\uFEFF) for UTF-8 encoding recognition in Excel
    const csvContent = '\uFEFF' + [headers.join(';'), ...rows, totalRow].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `producao_manupackaging_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

