    }), { gross: 0, tara: 0, net: 0, volumes: 0, tubetes: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredReports]);

  const stats = useMemo(() => {
    const initialStats: Record<string, OperatorStat> = {};
    operators.forEach(op => {
      initialStats[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
    });
    filteredDataForCharts.forEach(e => {
      if (!initialStats[e.operator]) {
        initialStats[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      }
      const isErema = e.machine.toLowerCase().includes('erema');

      if (!isErema) {
        initialStats[e.operator].prod += (e.netWeight || 0);
      }
      initialStats[e.operator].ecoA += (e.ecoA || 0);
      initialStats[e.operator].ecoBP += (e.ecoBP || 0);
      initialStats[e.operator].ecoBM += (e.ecoBM || 0);
      initialStats[e.operator].borra += (e.borraTotal || 0);
      initialStats[e.operator].p_manut += (e.manutencaoMin || 0);
      initialStats[e.operator].p_proc += (e.processoMin || 0);
      initialStats[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(initialStats);
  }, [filteredDataForCharts, operators]);

  const personnelStats = useMemo(() => {
    let totalStaff = 0;
    let totalOperators = 0;
    let totalAuxiliaries = 0;
    let totalVacancies = 0;

    employees.forEach(emp => {
        if (emp.status === 'Ativo') {
            totalStaff++;
            if (emp.role.includes('Operador') || emp.role === 'Líder de Turno') totalOperators++;
            else totalAuxiliaries++;
        }
    });

    let expectedSlots = 0;
    if (personnelStructure.leadership) personnelStructure.leadership.forEach(s => expectedSlots += s.roles.length);
    if (personnelStructure.extrusao) personnelStructure.extrusao.forEach(s => s.machines.forEach(m => expectedSlots += m.roles.length));
    if (personnelStructure.erema) personnelStructure.erema.forEach(m => m.shifts.forEach(s => expectedSlots += s.roles.length));
    if (personnelStructure.fitaAdesiva) personnelStructure.fitaAdesiva.forEach(m => m.shifts.forEach(s => expectedSlots += s.roles.length));

    const activeEmployeesCount = employees.filter(e => e.status !== 'Desligado').length;
    totalVacancies = Math.max(0, expectedSlots - activeEmployeesCount);

    return { totalStaff, totalOperators, totalAuxiliaries, totalVacancies };
  }, [employees, personnelStructure]);

  const eremaChartData = useMemo(() => {
    const data: Record<string, number> = {};
    filteredDataForCharts
      .filter(e => e.machine.toLowerCase().includes('erema'))
      .forEach(e => {
         const dateKey = e.date.split('-').reverse().slice(0, 2).join('/');
         data[dateKey] = (data[dateKey] || 0) + (e.netWeight || 0);
      });
    return Object.entries(data).map(([name, value]) => ({ name, value })).sort((a, b) => {
        // Simple sort by assuming date format dd/mm matches lexical sort if formatted right, 
        // but since it's just day/month, reliable enough for same year. 
        // For perfect sort, we'd stick to ISO keys then format.
        return 0; 
    });
  }, [filteredDataForCharts]);

  const handleDownloadChartPNG = async (cardId: string, title: string) => {
    const element = document.getElementById(cardId);
    if (!element) return;
    try {
      const canvas = await html2canvas(element, { backgroundColor: '#ffffff', scale: 2 });
      const link = document.createElement('a');
      link.download = `${title.replace(/\s+/g, '_').toLowerCase()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (err) {
      console.error('Failed to download chart:', err);
    }
  };

  const handleSaveDashboardPDF = async () => {
    if (!dashboardRef.current) return;
    setIsGeneratingPDF(true);
    try {
      const canvas = await html2canvas(dashboardRef.current, {
        scale: 2,
        backgroundColor: '#f8fafc',
        logging: false,
        useCORS: true
      });
      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const imgProps = pdf.getImageProperties(imgData);
      const imgHeight = (imgProps.height * pdfWidth) / imgProps.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, imgHeight);
      pdf.save(`dashboard_manupackaging_${new Date().toISOString().split('T')[0]}.pdf`);
    } catch (err) {
      console.error('Failed to save PDF:', err);
      alert('Erro ao gerar PDF.');
    } finally {
      setIsGeneratingPDF(false);
    }
  };

  const allCharts = [
    { title: 'Produção Líquida', key: 'prod', description: 'Total produzido por operador (KG)', color: COLORS, formatter: formatWeight },
    { title: 'Eficiência Eco A', key: 'ecoA', description: 'Material nobre recuperado (KG)', color: COLORS, formatter: formatWeight },
    { title: 'Resíduo Borra', key: 'borra', description: 'Perda total de material (KG)', color: COLORS, formatter: formatWeight },
    { title: 'Eco B (Produção)', key: 'ecoBP', description: 'Recuperado Eco B Produção (KG)', color: COLORS, formatter: formatWeight },
    { title: 'Eco B (Manutenção)', key: 'ecoBM', description: 'Recuperado Eco B Manutenção (KG)', color: COLORS, formatter: formatWeight },
    { title: 'Tempo Manutenção', key: 'p_manut', description: 'Paradas para ajuste mecânico (Min)', color: COLORS, formatter: formatMinutes },
    { title: 'Tempo Processo', key: 'p_proc', description: 'Paradas operacionais/ajustes (Min)', color: COLORS, formatter: formatMinutes },
    { title: 'Tempo Outros', key: 'p_outros', description: 'Paradas diversas (Min)', color: COLORS, formatter: formatMinutes },
    { title: 'Produção vs Eco B', key: 'comparison_prod_ecob', description: 'Comparativo Geral (KG)', color: ['#3b82f6', '#f59e0b'], formatter: formatWeight },
    { title: 'Produção vs Borra', key: 'comparison_prod_borra', description: 'Eficiência de Material (KG)', color: ['#3b82f6', '#ef4444'], formatter: formatWeight },
    { title: 'Eco B vs Reciclado', key: 'comparison_ecob_recycled', description: 'Comparativo de Recuperação (KG)', color: ['#f59e0b', '#10b981'], formatter: formatWeight },
    { title: 'Operação vs Parada', key: 'comparison_time', description: 'Eficiência de Tempo (Min)', color: ['#10b981', '#ef4444'], formatter: formatMinutes },
  ];

  const getRoleBadge = (role: string) => {
    if (role.includes('Líder')) return 'LÍDER';
    if (role.includes('Operador 1')) return 'OPE1';
    if (role.includes('Operador 2')) return 'OPE2';
    if (role.includes('Operador 3')) return 'OPE3';
    if (role.includes('Auxiliar 1')) return 'AUX1';
    if (role.includes('Auxiliar 2')) return 'AUX2';
    if (role.includes('Auxiliar')) return 'AUXILIAR';
    return role.toUpperCase().substring(0, 4);
  };

  const renderPersonnelSlot = (
    sector: 'leadership' | 'extrusao' | 'erema' | 'fitaAdesiva', 
    machine: string, 
    shift: string, 
    role: string, 
    isNight: boolean, 
    slotIndex: number,
    siblingsRoles: string[]
  ) => {
    const fullSectorName = sector === 'leadership' ? 'Liderança' : sector === 'extrusao' ? 'Extrusão' : sector === 'erema' ? 'Reciclagem' : 'Fita Adesiva';
    const roleBadge = getRoleBadge(role);

    const potentialEmployees = employees.filter(e => 
        e.sector === fullSectorName && 
        e.machine === machine && 
        e.shift === shift && 
        e.role === role &&
        e.status !== 'Desligado'
    );

    const roleOccurrenceIndex = siblingsRoles.slice(0, slotIndex).filter(r => r === role).length;
    const employee = potentialEmployees[roleOccurrenceIndex];

    let containerClass = isNight ? 'bg-[#2a3441] border-[#374151]' : 'bg-white border-slate-100';
    let textClass = isNight ? 'text-slate-200' : 'text-slate-700';

    if (role === 'Vaga' || !employee) {
        return (
            <button 
                onClick={() => {
                    setNewEmployeeSlot({ sector: fullSectorName, machine, shift, role: role === 'Vaga' ? (sector === 'leadership' ? 'Líder de Turno' : 'Auxiliar 1') : role });
                    setSelectedEmployee(null);
                    setIsEmployeeModalOpen(true);
                }}
                className={`flex items-center justify-between px-3 py-1.5 rounded border border-dashed w-full transition-all hover:opacity-80 group ${isNight ? 'bg-red-900/10 border-red-800/50' : 'bg-red-50 border-red-200'}`}
            >
                <span className={`text-[10px] font-bold ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Adicionar)</span>
                <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${
                    isNight ? 'bg-red-900/30 text-red-400' : 'bg-red-100 text-red-600'
                }`}>{role === 'Vaga' ? 'VAGO' : roleBadge}</span>
            </button>
        );
    }

    let badgeClass = 'bg-slate-200 text-slate-600';
    if (roleBadge === 'LÍDER') badgeClass = 'bg-purple-100 text-purple-700';
    else if (roleBadge.startsWith('OPE')) badgeClass = 'bg-blue-100 text-blue-700';
    else if (roleBadge.startsWith('AUX')) badgeClass = 'bg-orange-100 text-orange-700';

    if (employee.status === 'Férias') {
        containerClass = isNight ? 'bg-orange-900/10 border-orange-800/30' : 'bg-orange-50 border-orange-100';
        textClass = 'text-orange-600';
    } else if (employee.status === 'Atestado') {
        containerClass = isNight ? 'bg-purple-900/10 border-purple-800/30' : 'bg-purple-50 border-purple-100';
        textClass = 'text-purple-600';
    }

    return (
        <button 
            onClick={() => {
                setSelectedEmployee(employee);
                setNewEmployeeSlot(undefined);
                setIsEmployeeModalOpen(true);
            }}
            className={`flex items-center justify-between px-3 py-1.5 rounded w-full transition-all hover:brightness-95 ${containerClass}`}
        >
            <span className={`text-[10px] font-bold truncate ${textClass}`}>
                {employee.name}
            </span>
            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${badgeClass}`}>
                {roleBadge}
            </span>
        </button>
    );
  };

  const isRangeFiltered = dashStartDate || dashEndDate;

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
