        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
             {/* ... (Dashboard content same as before) */}
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Card Meta Mensal */}
              <div className="md:col-span-2 bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between">
                 {/* Header */}
                 <div className="flex justify-between items-start mb-2">
                    <div>
                        <p className="text-[10px] font-bold opacity-80 tracking-widest mb-1">DESEMPENHO</p>
                        <h2 className="text-2xl font-black uppercase tracking-tight">META MENSAL</h2>
                    </div>
                    <div className="bg-white/20 p-2.5 rounded-xl backdrop-blur-sm">
                        <Target size={24} className="text-white" />
                    </div>
                 </div>

                 {/* Main Value */}
                 <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-5xl font-black tracking-tight">{formatWeight(totals.month)}</span>
                    <span className="text-sm font-bold opacity-80">/ {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%</span>
                 </div>

                 {/* Progress Bar */}
                 <div className="w-full bg-black/20 h-2.5 rounded-full mb-6 overflow-hidden">
                    <div className="bg-white h-full rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>

                 {/* Grid Stats */}
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm">
                        <p className="text-[9px] font-bold uppercase opacity-70 mb-1">Objetivo</p>
                        <p className="text-sm font-bold">{formatWeight(goalValue)}</p>
                     </div>
                     {!isGoalReached && (
                       <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm">
                          <p className="text-[9px] font-bold uppercase opacity-70 mb-1">Falta</p>
                          <p className="text-sm font-bold">{formatWeight(totals.remaining)}</p>
                       </div>
                     )}
                     {!isGoalReached && (
                       <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm">
                          <p className="text-[9px] font-bold uppercase opacity-70 mb-1">Média Nec.</p>
                          <p className="text-sm font-bold">{formatWeight(totals.dailyRequired)}/dia</p>
                       </div>
                     )}
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm">
                        <p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p>
                        <p className="text-sm font-bold">{formatWeight(totals.projection)}</p>
                     </div>
                 </div>
              </div>

              {/* Cards Diário e Semanal */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:col-span-2">
                  {/* Card Diário */}
                  <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col justify-between">
                     <div className="flex justify-between items-start">
                        <div>
                           <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">DIÁRIO</p>
                           <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">PRODUÇÃO ONTEM</h3>
                        </div>
                        <div className="bg-slate-100 p-2.5 rounded-xl text-slate-400">
                           <TrendingUp size={24} />
                        </div>
                     </div>
                     <div className="mt-6">
                        <span className="text-4xl font-black text-slate-800">{formatWeight(totals.yesterday)}</span>
                        <p className="text-xs font-bold text-slate-400 mt-1">Acumulado diário</p>
                     </div>
                  </div>

                  {/* Card Erema Mensal */}
                  <div 
                    onClick={() => setIsEremaChartModalOpen(true)}
                    className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col justify-between cursor-pointer hover:scale-[1.02] transition-transform hover:shadow-md group"
                  >
                     <div className="flex justify-between items-start">
                        <div>
                           <p className="text-[10px] font-bold text-emerald-500 uppercase tracking-widest mb-1 group-hover:underline">RECICLAGEM</p>
                           <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight flex items-center gap-2">EREMA MENSAL <ChevronRight size={16} className="text-slate-300 group-hover:text-emerald-500 transition-colors"/></h3>
                        </div>
                        <div className="bg-emerald-50 p-2.5 rounded-xl text-emerald-500 group-hover:bg-emerald-100 transition-colors">
                           <RotateCcw size={24} />
                        </div>
                     </div>
                     <div className="mt-6">
                        <span className="text-4xl font-black text-slate-800">{formatWeight(totals.eremaMonth)}</span>
                        <p className="text-xs font-bold text-slate-400 mt-1">Recuperado este mês</p>
                     </div>
                  </div>
              </div>
            </div>

            {/* Gráficos em Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {allCharts.map((chart, idx) => {
                 let data: any[] = [];
                 const isComparison = chart.key.startsWith('comparison_');

                 if (isComparison) {
                     if (chart.key === 'comparison_prod_ecob') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Eco B', value: stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0) }
                        ];
                     } else if (chart.key === 'comparison_prod_borra') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Borra', value: stats.reduce((acc, s) => acc + s.borra, 0) }
                        ];
                     } else if (chart.key === 'comparison_ecob_recycled') {
                         const totalErema = filteredDataForCharts
                            .filter(e => e.machine.toLowerCase().includes('erema'))
                            .reduce((acc, e) => acc + (e.netWeight || 0), 0);

                         const totalEcoB = stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0);

                         data = [
                            { name: 'Eco B', value: totalEcoB },
                            { name: 'Reciclado (Erema)', value: totalErema }
                        ];
                     } else if (chart.key === 'comparison_time') {
                         const totalTime = stats.reduce((acc, s) => acc + s.p_manut + s.p_proc + s.p_outros, 0);
                         const totalProd = stats.reduce((acc, s) => acc + s.prod, 0); // Mock ratio for demo
                         data = [
                            { name: 'Operando', value: 1000 }, 
                            { name: 'Parado', value: totalTime }
                         ];
                     }
                 } else {
                     data = stats.map(s => ({ 
                        name: s.name, 
                        value: (s as any)[chart.key] 
                     })).filter(i => i.value > 0);
                 }

                 if (data.length === 0) return null;

                 // Sort data descending for rank
                 data.sort((a, b) => b.value - a.value);

                 return (
                  <div id={`chart-${idx}`} key={idx} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm hover:shadow-xl transition-all duration-300 group flex flex-col">
                    {/* Header */}
                    <div className="flex justify-between items-start mb-6">
                      <div>
                        <h3 className="text-sm font-black uppercase text-slate-800 tracking-tight flex items-center gap-2">
                           {idx === 0 && <span className="text-yellow-500">🏆</span>} {chart.title}
                        </h3>
                        <p className="text-[10px] text-slate-400 font-bold uppercase tracking-wide mt-1">{chart.description}</p>
                      </div>
                      <button onClick={() => handleDownloadChartPNG(`chart-${idx}`, chart.title)} className="p-2 text-blue-500 bg-blue-50 rounded-xl hover:bg-blue-100 transition-all">
                        <ImageIcon size={18} />
                      </button>
                    </div>

                    {/* Chart */}
                    <div className="h-72 relative w-full">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie
                            data={data}
                            cx="50%"
                            cy="50%"
                            innerRadius={70}
                            outerRadius={90}
                            paddingAngle={3}
                            dataKey="value"
                            stroke="none"
                            labelLine={{ stroke: '#cbd5e1', strokeWidth: 1.5 }}
                            label={renderCustomizedLabel}
                          >
                            {data.map((entry, index) => (
                              <Cell key={`cell-${index}`} fill={chart.color[index % chart.color.length]} />
                            ))}
                          </Pie>
                          <Tooltip 
                            contentStyle={{ borderRadius: '16px', border: 'none', boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 8px 10px -6px rgba(0, 0, 0, 0.1)', padding: '12px' }}
                            itemStyle={{ fontSize: '12px', fontWeight: 'bold', color: '#1e293b' }}
                            formatter={(value: number) => [chart.formatter(value), '']}
                          />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>

                    {/* Legend */}
                    <div className="mt-4 flex flex-wrap justify-center gap-x-6 gap-y-3">
                       {data.map((entry, i) => (
                          <div key={i} className="flex items-center gap-2 text-xs">
                             <div className="w-3 h-3 rounded-full flex-shrink-0" style={{ backgroundColor: chart.color[i % chart.color.length] }}></div>
                             <div className="flex items-baseline gap-1">
                                {chart.key === 'prod' && <span className="font-black text-slate-400">{i + 1}º</span>}
                                <span className="font-bold text-slate-600">{entry.name}:</span>
                                <span className="font-black text-slate-800">{chart.formatter(entry.value)}</span>
                             </div>
                          </div>
                       ))}
                    </div>
                  </div>
                 );
              })}
            </div>
          </div>
        )}

        {/* ... (rest of reports tab remains same) ... */}
        {activeTab === 'reports' && (
           <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-300">

              {/* Toolbar */}
              <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
