    const roleStr = String(role);
    const roleBadge = getRoleBadge(roleStr);

    const potentialEmployees = employees.filter(e => 
        e.sector === fullSectorName && 
        e.machine === machine && 
        e.shift === shift && 
        e.role === roleStr &&
        e.status !== 'Desligado'
