  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>(() => {
    const saved = localStorage.getItem('manupackaging_personnel_logs');
    return saved ? JSON.parse(saved) : [];
  });

  const [jobRoles, setJobRoles] = useState<string[]>(() => {
    const saved = localStorage.getItem('manupackaging_roles');
    let roles = saved ? JSON.parse(saved) : DEFAULT_HIERARCHY;
    // Ensure new admin roles exist
    const requiredRoles = ['Gerente', 'Supervisor', 'Líder de Produção'];
    requiredRoles.forEach(r => {
        if (!roles.includes(r)) roles = [r, ...roles];
    });
    return roles;
  });

  // Helper to generate default structure
  const getDefaultStructure = (): PersonnelStructure => {
      const getRoleByIndex = (index: number) => DEFAULT_HIERARCHY[index] || `Auxiliar ${index - 3}`;
      return {
          leadership: [
              { shift: 'Administrativo', roles: ['Gerente', 'Supervisor', 'Líder de Produção'] }
          ],
          extrusao: PERSONNEL_DATA.extrusao.map(s => ({
              shift: s.shift,
              machines: s.machines.map(m => ({
                  name: m.name,
                  roles: m.team.map((_, i) => getRoleByIndex(i))
              }))
          })),
          erema: PERSONNEL_DATA.erema.map(m => ({
              name: m.name,
              shifts: m.shifts.map(s => ({
                  name: s.name,
                  roles: s.team.map((_, i) => getRoleByIndex(i))
              }))
          })),
          fitaAdesiva: PERSONNEL_DATA.fitaAdesiva.map(m => ({
              name: m.name,
              shifts: m.shifts.map(s => ({
                  name: s.name,
                  roles: s.team.map((_, i) => getRoleByIndex(i))
              }))
          }))
      };
  };

  const sanitizeStructure = (parsed: any): PersonnelStructure => {
      const defaults = getDefaultStructure();
      if (!parsed || typeof parsed !== 'object') return defaults;

      // Leadership Migration: Force only Administrativo
      let sourceLeadership = Array.isArray(parsed.leadership) ? parsed.leadership : [];
      let adminBlock = sourceLeadership.find((s: any) => s.shift === 'Administrativo');

      if (!adminBlock) {
          adminBlock = { shift: 'Administrativo', roles: ['Gerente', 'Supervisor', 'Líder de Produção'] };
      } else {
          adminBlock = { ...adminBlock, roles: Array.isArray(adminBlock.roles) ? adminBlock.roles : [] };
      }

      const leadership = [adminBlock];

      // Sanitization Helpers
      const sanitizeExtrusao = (arr: any) => Array.isArray(arr) ? arr.map((s: any) => ({
          ...s, 
          machines: Array.isArray(s.machines) ? s.machines.map((m: any) => ({...m, roles: Array.isArray(m.roles) ? m.roles : []})) : []
      })) : defaults.extrusao;

      const sanitizeStandard = (arr: any, def: any) => Array.isArray(arr) ? arr.map((m: any) => ({
           ...m,
           shifts: Array.isArray(m.shifts) ? m.shifts.map((s: any) => ({...s, roles: Array.isArray(s.roles) ? s.roles : []})) : []
      })) : def;

      return {
          leadership,
          extrusao: sanitizeExtrusao(parsed.extrusao),
          erema: sanitizeStandard(parsed.erema, defaults.erema),
          fitaAdesiva: sanitizeStandard(parsed.fitaAdesiva, defaults.fitaAdesiva),
      };
  };

  const [personnelStructure, setPersonnelStructure] = useState<PersonnelStructure>(() => {
    const saved = localStorage.getItem('manupackaging_structure');
    if (saved) {
        try {
            return sanitizeStructure(JSON.parse(saved));
        } catch (e) {
            console.error("Error parsing structure from local storage", e);
        }
    }
    return getDefaultStructure();
  });

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec', 'Supervisão'];

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_shifts', JSON.stringify(shifts)); }, [shifts]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_active_tab', activeTab); }, [activeTab]);
  useEffect(() => { localStorage.setItem('manupackaging_timeframe', selectedTimeframe); }, [selectedTimeframe]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);

  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_personnel_logs', JSON.stringify(personnelLogs)); }, [personnelLogs]);
  useEffect(() => { localStorage.setItem('manupackaging_roles', JSON.stringify(jobRoles)); }, [jobRoles]);
  useEffect(() => { localStorage.setItem('manupackaging_structure', JSON.stringify(personnelStructure)); }, [personnelStructure]);

  const [isModalOpen, setIsModalOpen] = useState(false);
