  const personnelStats = useMemo(() => {
    let totalStaff = 0;
    let activeOperators = 0;
    let totalAuxiliaries = 0;
    let activeAuxiliaries = 0;
    let employeesOnVacation = 0;
    let totalVacancies = 0;

    employees.forEach(emp => {
        if (emp.status !== 'Desligado') {
            totalStaff++; // Count everyone on payroll

            const isOperator = emp.role.includes('Operador') || emp.role === 'Líder de Turno';

            if (!isOperator) {
                totalAuxiliaries++;
                if (emp.status === 'Ativo') activeAuxiliaries++;
            } else {
                if (emp.status === 'Ativo') activeOperators++;
            }

            if (emp.status === 'Férias') {
                employeesOnVacation++;
            }
        }
    });

    let expectedSlots = 0;
    if (personnelStructure.leadership) personnelStructure.leadership.forEach(s => expectedSlots += s.roles?.length || 0);
    if (personnelStructure.extrusao) personnelStructure.extrusao.forEach(s => s.machines?.forEach(m => expectedSlots += m.roles?.length || 0));
    if (personnelStructure.erema) personnelStructure.erema.forEach(m => m.shifts?.forEach(s => expectedSlots += s.roles?.length || 0));
    if (personnelStructure.fitaAdesiva) personnelStructure.fitaAdesiva.forEach(m => m.shifts?.forEach(s => expectedSlots += s.roles?.length || 0));

    const activeEmployeesCount = employees.filter(e => e.status !== 'Desligado').length;
    totalVacancies = Math.max(0, expectedSlots - activeEmployeesCount);

    return { totalStaff, activeOperators, totalAuxiliaries, activeAuxiliaries, employeesOnVacation, totalVacancies };
  }, [employees, personnelStructure]);

