                     } else if (chart.key === 'comparison_prod_borra') {
                        data = [
                            { name: 'Prod. Liq', value: stats.reduce((acc, s) => acc + s.prod, 0) },
                            { name: 'Borra', value: stats.reduce((acc, s) => acc + s.borra, 0) }
