                         const totalEcoB = stats.reduce((acc, s) => acc + s.ecoBP + s.ecoBM, 0);

                         data = [
                            { name: 'Eco B', value: totalEcoB },
                            { name: 'Reciclado (Erema)', value: totalErema }
                        ];
                     } else if (chart.key === 'comparison_time') {
