    const fullSectorName = sector === 'leadership' ? 'Liderança' : sector === 'extrusao' ? 'Extrusão' : sector === 'erema' ? 'Reciclagem' : 'Fita Adesiva';
    const roleStr = String(role);
    const roleBadge = getRoleBadge(roleStr);

    const potentialEmployees = employees.filter(e => 
        e.sector === fullSectorName && 
        e.machine === machine && 
        e.shift === shift && 
        e.role === roleStr &&
        e.status !== 'Desligado'
    );

    const roleOccurrenceIndex = siblingsRoles.slice(0, slotIndex).filter(r => r === role).length;
    const employee = potentialEmployees[roleOccurrenceIndex];

    let containerClass = isNight ? 'bg-[#2a3441] border-[#374151]' : 'bg-white border-slate-100';
    let textClass = isNight ? 'text-slate-200' : 'text-slate-700';

    if (roleStr === 'Vaga' || !employee) {
