    try {
      const canvas = await html2canvas(element, { backgroundColor: '#ffffff', scale: 2 });
      const link = document.createElement('a');
      link.download = `${title.replace(/\s+/g, '_').toLowerCase()}.png`;
      link.href = canvas.toDataURL('image/png');
      link.click();
    } catch (err) {
      console.error('Failed to download chart:', err);
    }
  };

  const getRoleBadge = (role: string) => {
    if (role.includes('Gerente')) return 'GER';
    if (role.includes('Supervisor')) return 'SUP';
    if (role.includes('Líder de Produção')) return 'LÍD.P';
    if (role.includes('Líder')) return 'LÍDER';
    if (role.includes('Operador 1')) return 'OPE1';
    if (role.includes('Operador 2')) return 'OPE2';
    if (role.includes('Operador 3')) return 'OPE3';
    if (role.includes('Auxiliar 1')) return 'AUX1';
    if (role.includes('Auxiliar 2')) return 'AUX2';
    if (role.includes('Auxiliar')) return 'AUXILIAR';
    return role.toUpperCase().substring(0, 4);
  };

  const renderPersonnelSlot = (
    sector: 'leadership' | 'extrusao' | 'erema' | 'fitaAdesiva', 
    machine: string, 
    shift: string, 
    role: string, 
    isNight: boolean, 
    slotIndex: number,
    siblingsRoles: string[]
  ) => {
    const fullSectorName = sector === 'leadership' ? 'Liderança' : sector === 'extrusao' ? 'Extrusão' : sector === 'erema' ? 'Reciclagem' : 'Fita Adesiva';
    const roleStr = String(role);
    const roleBadge = getRoleBadge(roleStr);

    const potentialEmployees = employees.filter(e => 
        e.sector === fullSectorName && 
        e.machine === machine && 
        e.shift === shift && 
        e.role === roleStr &&
        e.status !== 'Desligado'
    );

    const roleOccurrenceIndex = siblingsRoles.slice(0, slotIndex).filter(r => r === role).length;
    const employee = potentialEmployees[roleOccurrenceIndex];

    let containerClass = isNight ? 'bg-[#2a3441] border-[#374151]' : 'bg-white border-slate-100';
    let textClass = isNight ? 'text-slate-200' : 'text-slate-700';

    if (roleStr === 'Vaga' || !employee) {
        return (
            <button 
                onClick={() => {
                    const defaultRole = sector === 'leadership' 
                        ? (shift === 'Administrativo' ? 'Gerente' : 'Líder de Turno') 
                        : 'Auxiliar 1';

                    setNewEmployeeSlot({ 
                        sector: fullSectorName, 
                        machine, 
                        shift, 
                        role: roleStr === 'Vaga' ? defaultRole : roleStr 
                    });
                    setSelectedEmployee(null);
                    setIsEmployeeModalOpen(true);
                }}
                className={`flex items-center justify-between px-3 py-1.5 rounded border border-dashed w-full transition-all hover:opacity-80 group ${isNight ? 'bg-red-900/10 border-red-800/50' : 'bg-red-50 border-red-200'}`}
            >
                <span className={`text-[10px] font-bold ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Adicionar)</span>
                <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${
                    isNight ? 'bg-red-900/30 text-red-400' : 'bg-red-100 text-red-600'
                }`}>{roleStr === 'Vaga' ? 'VAGO' : roleBadge}</span>
            </button>
        );
    }

    let badgeClass = 'bg-slate-200 text-slate-600';
    if (['GER', 'SUP', 'LÍD.P'].includes(roleBadge)) badgeClass = 'bg-indigo-100 text-indigo-700';
    else if (roleBadge === 'LÍDER') badgeClass = 'bg-purple-100 text-purple-700';
    else if (roleBadge.startsWith('OPE')) badgeClass = 'bg-blue-100 text-blue-700';
    else if (roleBadge.startsWith('AUX')) badgeClass = 'bg-orange-100 text-orange-700';

    if (employee.status === 'Férias') {
        containerClass = isNight ? 'bg-orange-900/10 border-orange-800/30' : 'bg-orange-50 border-orange-100';
        textClass = 'text-orange-600';
    } else if (employee.status === 'Atestado') {
        containerClass = isNight ? 'bg-purple-900/10 border-purple-800/30' : 'bg-purple-50 border-purple-100';
        textClass = 'text-purple-600';
    }

    return (
        <button 
            onClick={() => {
                setSelectedEmployee(employee);
                setNewEmployeeSlot(undefined);
                setIsEmployeeModalOpen(true);
            }}
            className={`flex items-center justify-between px-3 py-1.5 rounded w-full transition-all hover:brightness-95 ${containerClass}`}
        >
            <span className={`text-[10px] font-bold truncate ${textClass}`}>
                {employee.name}
            </span>
            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${badgeClass}`}>
                {roleBadge}
            </span>
        </button>
    );
  };

  if (!isAuthenticated) {
    return (
      <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
        <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
          <div className="text-center space-y-2">
            <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4">
              <ShieldCheck size={32} />
            </div>
            <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
            <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
          </div>
          <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
        </div>
      </div>
    );
