                           <h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">PRODUÇÃO ONTEM</h3>
                        </div>
                        <div className="bg-slate-100 p-2.5 rounded-xl text-slate-400">
                           <TrendingUp size={24} />
