                     </div>
                     <div className="mt-6">
                        <span className="text-4xl font-black text-slate-800">{formatWeight(totals.yesterday)}</span>
                        <p className="text-xs font-bold text-slate-400 mt-1">Acumulado diário</p>
                     </div>
                  </div>

                  <div 
                    onClick={() => setIsEremaChartModalOpen(true)}
                    className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col justify-between cursor-pointer hover:scale-[1.02] transition-transform hover:shadow-md group"
