                        <p className="text-xs font-bold text-slate-400 mt-1">Recuperado este mês</p>
                     </div>
                  </div>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'personnel' && (
           <div className="space-y-6 animate-in fade-in duration-300">
              <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm min-w-[220px] flex-1">
                      <div className="flex justify-between items-start mb-2">
                          <h3 className="text-[10px] font-black text-blue-500 uppercase tracking-widest">Colaboradores</h3>
                          <div className="bg-blue-50 p-2.5 rounded-2xl text-blue-500"><Users size={20} /></div>
                      </div>
                      <span className="text-4xl font-black text-slate-800">{personnelStats.totalStaff}</span>
                      <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">No Quadro</p>
                  </div>
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm min-w-[220px] flex-1">
                      <div className="flex justify-between items-start mb-2">
                          <h3 className="text-[10px] font-black text-emerald-500 uppercase tracking-widest">Operadores</h3>
                          <div className="bg-emerald-50 p-2.5 rounded-2xl text-emerald-500"><HardHat size={20} /></div>
                      </div>
                      <span className="text-4xl font-black text-slate-800">{personnelStats.activeOperators}</span>
                      <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">Ativos</p>
                  </div>
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm min-w-[220px] flex-1">
                      <div className="flex justify-between items-start mb-2">
                          <h3 className="text-[10px] font-black text-cyan-500 uppercase tracking-widest">Auxiliares Ativos</h3>
                          <div className="bg-cyan-50 p-2.5 rounded-2xl text-cyan-500"><UserCheck size={20} /></div>
                      </div>
                      <span className="text-4xl font-black text-slate-800">{personnelStats.activeAuxiliaries}</span>
                      <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">Em Operação</p>
                  </div>
                  <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm min-w-[220px] flex-1">
                      <div className="flex justify-between items-start mb-2">
                          <h3 className="text-[10px] font-black text-amber-500 uppercase tracking-widest">Férias</h3>
                          <div className="bg-amber-50 p-2.5 rounded-2xl text-amber-500"><Plane size={20} /></div>
                      </div>
                      <span className="text-4xl font-black text-slate-800">{personnelStats.employeesOnVacation}</span>
                      <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase">Ausentes</p>
                  </div>
              </div>

              <div className="flex justify-end items-center gap-2">
                  <button onClick={() => setIsHistoryModalOpen(true)} className="px-4 py-2.5 bg-white border border-slate-200 text-slate-600 rounded-xl text-[10px] font-black uppercase hover:bg-slate-50 transition-all flex items-center gap-2 shadow-sm">
                      <History size={14}/> Histórico de Movimentação
                  </button>
              </div>

              <div className="space-y-8">
                  {/* Liderança Section */}
                  <div className="rounded-t-[2rem] overflow-hidden shadow-sm border border-slate-200">
                      <div className="bg-[#4f46e5] p-6 flex items-center gap-4">
                          <div className="p-3 bg-white/10 text-white rounded-2xl border border-white/10"><Crown size={22}/></div>
                          <div>
                              <h3 className="text-lg font-black uppercase tracking-tight text-white">Liderança & Coordenação</h3>
                          </div>
                      </div>
                      <div className="bg-white p-6 grid grid-cols-1 gap-4">
                          {personnelStructure.leadership?.map((shift, sIdx) => {
                              const isNight = shift.shift.toLowerCase().includes('noturno');
                              return (
                                <div key={sIdx} className={`p-6 rounded-[1.5rem] border ${isNight ? 'bg-[#2a3441] border-[#374151]' : 'bg-slate-50 border-slate-100'}`}>
                                    <div className="flex justify-between items-center mb-4">
                                        <h5 className={`text-[11px] font-black uppercase tracking-widest ${isNight ? 'text-slate-400' : 'text-slate-500'}`}>{shift.shift}</h5>
                                        <button onClick={() => handleAddSlot('leadership', 'Supervisão', shift.shift)} className={`p-1.5 rounded-lg hover:bg-black/10 transition-colors ${isNight ? 'text-indigo-400' : 'text-indigo-500'}`}>
                                            <Plus size={16}/>
                                        </button>
                                    </div>
                                    <div className="space-y-2">
                                        {shift.roles?.map((role, rIdx) => (
                                            <React.Fragment key={rIdx}>
                                                {renderPersonnelSlot('leadership', 'Supervisão', shift.shift, role, isNight, rIdx, shift.roles)}
