      <OperatorModal isOpen={isOperatorModalOpen} onClose={() => setIsOperatorModalOpen(false)} operators={operators} onUpdate={setOperators} />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => { setIsEmployeeModalOpen(false); setSelectedEmployee(null); setNewEmployeeSlot(undefined); }} onSave={handleEmployeeAction} availableShifts={[{id:'l1', name: 'Diurno', type: 'Diurno', startTime: '', endTime: ''}, {id:'l2', name: 'Noturno', type: 'Noturno', startTime: '', endTime: ''}, ...shifts]} availableMachines={activeMachines} availableRoles={jobRoles} initialData={selectedEmployee} slotInfo={newEmployeeSlot} />
      <HistoryModal isOpen={isHistoryModalOpen} onClose={() => setIsHistoryModalOpen(false)} logs={personnelLogs} />
      <RoleModal isOpen={isRoleModalOpen} onClose={() => setIsRoleModalOpen(false)} roles={jobRoles} onUpdate={setJobRoles} />

      {confirmDialog.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-3xl w-full max-w-sm shadow-2xl p-6 text-center space-y-4 animate-in zoom-in-95 duration-200">
             <div className="w-16 h-16 bg-red-100 text-red-600 rounded-full flex items-center justify-center mx-auto"><AlertTriangle size={32} /></div>
             <div>
                <h3 className="text-lg font-black text-slate-800 uppercase">{confirmDialog.title}</h3>
                <p className="text-sm text-slate-500 font-medium mt-2">{confirmDialog.message}</p>
             </div>
             <div className="grid grid-cols-2 gap-3 pt-2">
                <button onClick={() => setConfirmDialog(prev => ({ ...prev, isOpen: false }))} className="py-3 bg-white border border-slate-200 rounded-xl text-slate-500 text-xs font-black uppercase hover:bg-slate-50">Cancelar</button>
                <button onClick={confirmDialog.onConfirm} className="py-3 bg-red-600 text-white rounded-xl text-xs font-black uppercase hover:bg-red-700 shadow-lg shadow-red-200">Confirmar</button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

