                           <RotateCcw size={24} />
                        </div>
                     </div>
                     <div className="mt-6">
                        <span className="text-4xl font-black text-slate-800">{formatWeight(totals.eremaMonth)}</span>
                        <p className="text-xs font-bold text-slate-400 mt-1">Recuperado este mês</p>
                     </div>
                  </div>
              </div>
            </div>
          </div>
