  const handleExportBackup = () => {
    const backup = {
      productionData,
      goalValue,
      shifts,
      operators,
      employees,
      personnelLogs,
      jobRoles,
      personnelStructure,
      version: '1.4.0',
      exportedAt: new Date().toISOString()
    };
    const blob = new Blob([JSON.stringify(backup, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    const now = new Date();
    const dateStr = now.toLocaleDateString('pt-BR').replace(/\//g, '-');
    const timeStr = now.toLocaleTimeString('pt-BR').replace(/:/g, 'h');
    link.download = `Dados de Produção e Pessoal - ${dateStr} ${timeStr}.json`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const handleExportCSV = () => {
    const dataToExport = filteredReports;
    if (dataToExport.length === 0) return alert('Nenhum dado para exportar.');
    const headers = ['Data', 'Turno', 'Máquina', 'Operador', 'Peso Bruto', 'Tara', 'Peso Líquido', 'Volumes', 'Tubetes', 'Eco A', 'Eco B (P)', 'Eco B (M)', 'Borra Total', 'Manutencao (min)', 'Processo (min)', 'Outros (min)'];
    const formatNum = (num: number | undefined) => String(num || 0).replace('.', ',');
    const rows = dataToExport.map(e => {
        const dateFormatted = e.date.split('-').reverse().join('/');
        return [
            dateFormatted, `"${e.shift}"`, `"${e.machine}"`, `"${e.operator}"`,
            formatNum(e.grossWeight), formatNum(e.tara), formatNum(e.netWeight),
            formatNum(e.volumes), formatNum(e.tubetes), formatNum(e.ecoA),
            formatNum(e.ecoBP), formatNum(e.ecoBM), formatNum(e.borraTotal),
            formatNum(e.manutencaoMin), formatNum(e.processoMin), formatNum(e.outrosMin)
        ].join(';');
    });
    const totalRow = [
        'TOTAL', '', '', '',
        formatNum(reportTotals.gross), formatNum(reportTotals.tara), formatNum(reportTotals.net),
        formatNum(reportTotals.volumes), formatNum(reportTotals.tubetes), formatNum(reportTotals.ecoA),
        formatNum(reportTotals.ecoBP + reportTotals.ecoBM), '', formatNum(reportTotals.borra),
        formatNum(reportTotals.manut), formatNum(reportTotals.proc), formatNum(reportTotals.outros)
    ].join(';');
    const csvContent = '\uFEFF' + [headers.join(';'), ...rows, totalRow].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `producao_manupackaging_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const rawData = JSON.parse(event.target?.result as string);
        const data = Array.isArray(rawData) ? { productionData: rawData } : rawData;

        if (data.productionData && Array.isArray(data.productionData)) {
            const normalizedData = data.productionData.map((e: any) => ({
                ...e,
                date: e.date && e.date.includes('/') ? e.date.split('/').reverse().join('-') : e.date
            }));
            setProductionData(normalizedData);
            const dates = normalizedData.map((e: any) => e.date).filter(Boolean);
            if (dates.length > 0) {
                const latestDate = dates.sort().reverse()[0];
                setDashboardMonth(latestDate.slice(0, 7));
            }
        }
        if (data.goalValue) {
            const g = Number(data.goalValue);
            if (!isNaN(g)) setGoalValue(g);
        }
        if (data.shifts) setShifts(data.shifts);
        if (data.operators) setOperators(data.operators);
        if (data.employees) setEmployees(data.employees);
        if (data.personnelLogs) setPersonnelLogs(data.personnelLogs);
        if (data.jobRoles) setJobRoles(data.jobRoles);
        if (data.personnelStructure) setPersonnelStructure(sanitizeStructure(data.personnelStructure));

        alert('Backup restaurado com sucesso! Dashboard sincronizado com a data mais recente.');
      } catch (err) {
        alert('Erro ao carregar backup. Verifique o arquivo.');
      }
    };
    reader.readAsText(file);
  };

  const handleResetSystem = () => {
    setConfirmDialog({
      isOpen: true,
      title: 'Resetar Sistema',
      message: 'ATENÇÃO: Isso apagará todos os dados salvos. Esta ação não pode ser desfeita!',
      onConfirm: () => { localStorage.clear(); window.location.reload(); }
    });
  };

  const syncStructureWithEmployeeChange = (oldEmployee: Employee | null, newEmployeeData: Partial<Employee>, action: string) => {
    setPersonnelStructure(prevStructure => {
        const newStructure = JSON.parse(JSON.stringify(prevStructure));
        const sortRoles = (roles: string[]) => {
            const priorityMap: Record<string, number> = {};
            jobRoles.forEach((r, i) => priorityMap[r] = i);
            roles.sort((a, b) => (priorityMap[a] ?? 999) - (priorityMap[b] ?? 999));
        };
        const findRolesArray = (struct: PersonnelStructure, sector: string, machine: string, shift: string) => {
             if (sector === 'Liderança') {
                const sIdx = struct.leadership.findIndex((s: any) => s.shift === shift);
                if (sIdx >= 0) return struct.leadership[sIdx].roles;
             } else if (sector === 'Extrusão') {
                const sIdx = struct.extrusao.findIndex((s: any) => s.shift === shift);
                if (sIdx >= 0) {
                    const mIdx = struct.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                    if (mIdx >= 0) return struct.extrusao[sIdx].machines[mIdx].roles;
                }
             } else {
                const secKey = sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva';
                const sectorArr = struct[secKey as keyof Pick<PersonnelStructure, 'erema' | 'fitaAdesiva'>] as any[];
                const mIdx = sectorArr.findIndex((m: any) => m.name === machine);
                if (mIdx >= 0) {
                    const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === shift);
                    if (sIdx >= 0) return sectorArr[mIdx].shifts[sIdx].roles;
                }
             }
             return null;
        };

        if (newEmployeeData.status !== 'Desligado' && newEmployeeData.sector && newEmployeeData.machine && newEmployeeData.shift && newEmployeeData.role) {
            const rolesArr = findRolesArray(newStructure, newEmployeeData.sector, newEmployeeData.machine, newEmployeeData.shift);
            if (rolesArr) {
                const futureOccupants = employees.filter(e => 
                    e.sector === newEmployeeData.sector && e.machine === newEmployeeData.machine && 
                    e.shift === newEmployeeData.shift && e.role === newEmployeeData.role && 
                    e.status !== 'Desligado' && e.id !== newEmployeeData.id
                ).length + 1;
                const currentCapacity = rolesArr.filter((r: string) => r === newEmployeeData.role).length;
                if (futureOccupants > currentCapacity) {
                    rolesArr.push(newEmployeeData.role);
                    sortRoles(rolesArr);
                }
            }
        }

        if (oldEmployee && (action === 'Transferência' || action === 'Alteração')) {
             if (oldEmployee.sector !== newEmployeeData.sector || oldEmployee.machine !== newEmployeeData.machine || 
                 oldEmployee.shift !== newEmployeeData.shift || oldEmployee.role !== newEmployeeData.role) {
                 const rolesArr = findRolesArray(newStructure, oldEmployee.sector, oldEmployee.machine, oldEmployee.shift);
                 if (rolesArr) {
                     const remainingOccupants = employees.filter(e => 
                        e.sector === oldEmployee.sector && e.machine === oldEmployee.machine && 
                        e.shift === oldEmployee.shift && e.role === oldEmployee.role && 
                        e.status !== 'Desligado' && e.id !== oldEmployee.id
                     ).length;
                     const currentCapacity = rolesArr.filter((r: string) => r === oldEmployee.role).length;
                     if (currentCapacity > remainingOccupants) {
                         const idx = rolesArr.indexOf(oldEmployee.role);
                         if (idx > -1) { rolesArr.splice(idx, 1); sortRoles(rolesArr); }
                     }
                 }
             }
        }
        return newStructure;
    });
  };

  const handleAddSlot = (sector: 'leadership' | 'extrusao' | 'erema' | 'fitaAdesiva', machine: string, shift: string) => {
    setPersonnelStructure(prev => {
        const newStruct = JSON.parse(JSON.stringify(prev));
        if (sector === 'leadership') {
            const sIdx = newStruct.leadership.findIndex((s: any) => s.shift === shift);
            if (sIdx >= 0) newStruct.leadership[sIdx].roles.push('Vaga');
        } else if (sector === 'extrusao') {
            const sIdx = newStruct.extrusao.findIndex((s: any) => s.shift === shift);
            if (sIdx >= 0) {
                const mIdx = newStruct.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                if (mIdx >= 0) newStruct.extrusao[sIdx].machines[mIdx].roles.push('Vaga');
            }
        } else {
             const secKey = sector === 'erema' ? 'erema' : 'fitaAdesiva';
             const sectorArr = newStruct[secKey];
             const mIdx = sectorArr.findIndex((m: any) => m.name === machine);
             if (mIdx >= 0) {
                 const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === shift);
                 if (sIdx >= 0) sectorArr[mIdx].shifts[sIdx].roles.push('Vaga');
             }
        }
        return newStruct;
    });
  };

  const handleEmployeeAction = (data: Partial<Employee>, action: string, details?: string) => {
    const timestamp = new Date().toISOString();
    const oldEmployee = data.id ? employees.find(e => e.id === data.id) || null : null;
    const newLog: PersonnelLog = { id: Math.random().toString(36).substr(2, 9), date: timestamp, employeeName: data.name || 'Desconhecido', action: action as any, details: details || '', user: 'Admin' };
    setPersonnelLogs(prev => [newLog, ...prev]);

    if (action === 'Exclusão' && oldEmployee) {
        setEmployees(prev => prev.filter(e => e.id !== oldEmployee.id));
        setPersonnelStructure(prevStructure => {
            const newStruct = JSON.parse(JSON.stringify(prevStructure));
            const { sector, machine, shift, role } = oldEmployee;
            const removeRoleInstance = (roles: string[]) => { const idx = roles.indexOf(role); if (idx > -1) roles.splice(idx, 1); };
            if (sector === 'Liderança') {
                const sIdx = newStruct.leadership.findIndex((s: any) => s.shift === shift);
                if (sIdx >= 0) removeRoleInstance(newStruct.leadership[sIdx].roles);
            } else if (sector === 'Extrusão') {
                const sIdx = newStruct.extrusao.findIndex((s: any) => s.shift === shift);
                if (sIdx >= 0) {
                    const mIdx = newStruct.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                    if (mIdx >= 0) removeRoleInstance(newStruct.extrusao[sIdx].machines[mIdx].roles);
                }
            } else {
                const secKey = sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva';
                const sectorArr = newStruct[secKey as keyof Pick<PersonnelStructure, 'erema' | 'fitaAdesiva'>] as any[];
                const mIdx = sectorArr.findIndex((m: any) => m.name === machine);
                if (mIdx >= 0) {
                    const sIdx = sectorArr[mIdx].shifts.findIndex((s: any) => s.name === shift);
                    if (sIdx >= 0) removeRoleInstance(sectorArr[mIdx].shifts[sIdx].roles);
                }
            }
            return newStruct;
        });
        return;
    }
    if (['Contratação', 'Alteração', 'Transferência', 'Desligamento'].includes(action)) syncStructureWithEmployeeChange(oldEmployee, data, action);
    if (action === 'Contratação' && newEmployeeSlot && newEmployeeSlot.role === 'Vaga') {
         setPersonnelStructure(prev => {
            const ns = JSON.parse(JSON.stringify(prev));
            const { sector, machine, shift } = newEmployeeSlot;
            const removeVaga = (roles: string[]) => { const idx = roles.indexOf('Vaga'); if (idx > -1) roles.splice(idx, 1); };
            if (sector === 'Liderança') {
                 const sIdx = ns.leadership.findIndex((s: any) => s.shift === shift);
                 if (sIdx >= 0) removeVaga(ns.leadership[sIdx].roles);
            } else if (sector === 'Extrusão') {
                 const sIdx = ns.extrusao.findIndex((s: any) => s.shift === shift);
                 if (sIdx >= 0) {
                     const mIdx = ns.extrusao[sIdx].machines.findIndex((m: any) => m.name === machine);
                     if (mIdx >= 0) removeVaga(ns.extrusao[sIdx].machines[mIdx].roles);
                 }
            } else {
                 const sk = sector === 'Reciclagem' ? 'erema' : 'fitaAdesiva';
                 const sa = ns[sk];
                 const mi = sa.findIndex((m: any) => m.name === machine);
                 if (mi >= 0) {
                     const si = sa[mi].shifts.findIndex((s: any) => s.name === shift);
                     if (si >= 0) removeVaga(sa[mi].shifts[si].roles);
                 }
            }
            return ns;
         });
    }
    if (data.id) { setEmployees(prev => prev.map(e => e.id === data.id ? { ...e, ...data, updatedAt: timestamp } : e)); }
    else { setEmployees(prev => [...prev, { ...data, id: Math.random().toString(36).substr(2, 9), updatedAt: timestamp } as Employee]); }
  };

  const formatWeight = (val: number) => {
    if (isNaN(val)) return '0 KG';
    if (val >= 1000) return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const totals = useMemo(() => {
    const now = new Date();
    const todayStr = now.toLocaleDateString('sv-SE');
    const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');
    const results = { month: 0, eremaMonth: 0, today: 0, yesterday: 0, projection: 0, remaining: 0, dailyRequired: 0 };
    const currentYear = parseInt(dashboardMonth.split('-')[0]);
    const currentMonth = parseInt(dashboardMonth.split('-')[1]) - 1;
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const currentDay = (now.getFullYear() === currentYear && now.getMonth() === currentMonth) ? now.getDate() : daysInMonth;

    productionData.forEach(e => {
      const isErema = e.machine.toLowerCase().includes('erema');
      if (e.date.startsWith(dashboardMonth)) {
        if (isErema) results.eremaMonth += (e.netWeight || 0);
        else results.month += (e.netWeight || 0);
      }
      if (e.date === todayStr) results.today += (e.netWeight || 0);
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
    });
    results.projection = currentDay > 0 ? (results.month / currentDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);
    const dr = Math.max(0, daysInMonth - currentDay);
    results.dailyRequired = dr > 0 ? results.remaining / dr : results.remaining;
    return results;
  }, [productionData, dashboardMonth, goalValue]);

  const filteredDataForCharts = useMemo(() => {
    return productionData.filter(e => e.date.startsWith(dashboardMonth));
  }, [productionData, dashboardMonth]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const ms = searchTerm ? Object.values(e).some(v => String(v).toLowerCase().includes(searchTerm.toLowerCase())) : true;
      const mst = filterStartDate ? e.date >= filterStartDate : true;
      const me = filterEndDate ? e.date <= filterEndDate : true;
      return ms && mst && me;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportTotals = useMemo(() => {
    return filteredReports.reduce((acc, item) => ({
      gross: acc.gross + (item.grossWeight || 0), tara: acc.tara + (item.tara || 0), net: acc.net + (item.netWeight || 0),
      volumes: acc.volumes + (item.volumes || 0), tubetes: acc.tubetes + (item.tubetes || 0), ecoA: acc.ecoA + (item.ecoA || 0),
      ecoBP: acc.ecoBP + (item.ecoBP || 0), ecoBM: acc.ecoBM + (item.ecoBM || 0), borra: acc.borra + (item.borraTotal || 0),
      manut: acc.manut + (item.manutencaoMin || 0), proc: acc.proc + (item.processoMin || 0), outros: acc.outros + (item.outrosMin || 0),
    }), { gross: 0, tara: 0, net: 0, volumes: 0, tubetes: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, manut: 0, proc: 0, outros: 0 });
  }, [filteredReports]);

  const stats = useMemo(() => {
    const is: Record<string, OperatorStat> = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 });
    filteredDataForCharts.forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0); is[e.operator].ecoBP += (e.ecoBP || 0); is[e.operator].ecoBM += (e.ecoBM || 0);
      is[e.operator].borra += (e.borraTotal || 0); is[e.operator].p_manut += (e.manutencaoMin || 0); is[e.operator].p_proc += (e.processoMin || 0); is[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(is);
  }, [filteredDataForCharts, operators]);

  const personnelStats = useMemo(() => {
    let ts = 0, ao = 0, ta = 0, aa = 0, ev = 0;
    employees.forEach(emp => {
        if (emp.status !== 'Desligado') {
            ts++;
            const isOp = emp.role.toLowerCase().includes('operador') || emp.role.toLowerCase().includes('líder');
            if (!isOp) { ta++; if (emp.status === 'Ativo') aa++; }
            else { if (emp.status === 'Ativo') ao++; }
            if (emp.status === 'Férias') ev++;
        }
    });
    return { totalStaff: ts, activeOperators: ao, totalAuxiliaries: ta, activeAuxiliaries: aa, employeesOnVacation: ev };
  }, [employees]);

  const renderPersonnelSlot = (sector: any, machine: string, shift: string, role: string, isNight: boolean, slotIndex: number, siblingsRoles: string[]) => {
    const fs = sector === 'leadership' ? 'Liderança' : sector === 'extrusao' ? 'Extrusão' : sector === 'erema' ? 'Reciclagem' : 'Fita Adesiva';
    const rb = getRoleBadge(role);
    const pe = employees.filter(e => e.sector === fs && e.machine === machine && e.shift === shift && e.role === role && e.status !== 'Desligado');
    const ri = siblingsRoles.slice(0, slotIndex).filter(r => r === role).length;
    const employee = pe[ri];
    if (role === 'Vaga' || !employee) {
        return (
            <button onClick={() => { setNewEmployeeSlot({ sector: fs, machine, shift, role: role === 'Vaga' ? 'Auxiliar 1' : role }); setSelectedEmployee(null); setIsEmployeeModalOpen(true); }} className={`flex items-center justify-between px-3 py-1.5 rounded border border-dashed w-full hover:opacity-80 ${isNight ? 'bg-red-900/10 border-red-800/50' : 'bg-red-50 border-red-200'}`}>
                <span className={`text-[10px] font-bold ${isNight ? 'text-red-400' : 'text-red-500'}`}>(Adicionar)</span>
                <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${isNight ? 'bg-red-900/30 text-red-400' : 'bg-red-100 text-red-600'}`}>{role === 'Vaga' ? 'VAGO' : rb}</span>
            </button>
        );
    }
    const bc = rb.startsWith('OPE') ? 'bg-blue-100 text-blue-700' : rb.startsWith('AUX') ? 'bg-orange-100 text-orange-700' : 'bg-slate-200 text-slate-600';
    return (
        <button onClick={() => { setSelectedEmployee(employee); setNewEmployeeSlot(undefined); setIsEmployeeModalOpen(true); }} className={`flex items-center justify-between px-3 py-1.5 rounded w-full hover:brightness-95 ${employee.status === 'Férias' ? 'bg-orange-50 border border-orange-100 text-orange-600' : isNight ? 'bg-[#2a3441] border-[#374151] text-slate-200' : 'bg-white border border-slate-100 text-slate-700'}`}>
            <span className="text-[10px] font-bold truncate">{employee.name}</span>
            <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${bc}`}>{rb}</span>
        </button>
    );
  };

  const getRoleBadge = (r: string) => {
    if (r.includes('Gerente')) return 'GER'; if (r.includes('Supervisor')) return 'SUP'; if (r.includes('Líder')) return 'LÍD'; if (r.includes('Operador 1')) return 'OPE1'; if (r.includes('Operador 2')) return 'OPE2'; if (r.includes('Operador 3')) return 'OPE3'; if (r.includes('Auxiliar 1')) return 'AUX1'; if (r.includes('Auxiliar 2')) return 'AUX2';
    return r.toUpperCase().substring(0, 4);
  };

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
        <div className="text-center space-y-2">
          <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
          <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Painel de Acesso</p>
        </div>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl transition-all shadow-xl shadow-blue-200 uppercase text-xs">Entrar no Sistema</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 hover:bg-blue-700 text-white p-2.5 rounded-xl shadow-lg shadow-blue-100 transition-all flex items-center justify-center"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all relative"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm overflow-x-auto">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span>
          </button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span>
          </button>
          <button onClick={() => setActiveTab('personnel')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}>
            <Users size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Gestão de Pessoal</span>
          </button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              <div className={`md:col-span-2 bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between ${totals.month >= goalValue ? 'animate-goal-reached' : ''}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div>
                        <p className="text-[10px] font-bold opacity-80 tracking-widest mb-1">DESEMPENHO</p>
                        <h2 className="text-2xl font-black uppercase tracking-tight">META MENSAL</h2>
                    </div>
                    <div className="bg-white/20 p-2.5 rounded-xl backdrop-blur-sm"><Target size={24} className="text-white" /></div>
                 </div>
                 <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-5xl font-black tracking-tight">{formatWeight(totals.month)}</span>
                    <span className="text-sm font-bold opacity-80">/ {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%</span>
                 </div>
                 <div className="w-full bg-black/20 h-2.5 rounded-full mb-6 overflow-hidden">
                    <div className="bg-white h-full rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Objetivo</p><p className="text-sm font-bold">{formatWeight(goalValue)}</p></div>
                     {totals.month < goalValue && <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Falta</p><p className="text-sm font-bold">{formatWeight(totals.remaining)}</p></div>}
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Média Nec.</p><p className="text-sm font-bold">{formatWeight(totals.dailyRequired)}/dia</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p><p className="text-sm font-bold">{formatWeight(totals.projection)}</p></div>
                 </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 md:col-span-2">
                  <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100 flex flex-col justify-between">
                     <div className="flex justify-between items-start">
                        <div><p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mb-1">DIÁRIO</p><h3 className="text-lg font-black text-slate-800 uppercase tracking-tight">PRODUÇÃO ONTEM</h3></div>
                        <div className="bg-slate-100 p-2.5 rounded-xl text-slate-400"><TrendingUp size={24} /></div>
                     </div>
                     <div className="mt-6"><span className="text-4xl font-black text-slate-800">{formatWeight(totals.yesterday)}</span><p className="text-xs font-bold text-slate-400 mt-1">Acumulado diário</p></div>
                  </div>
