  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      return saved ? JSON.parse(saved) : INITIAL_DATA;
    } catch (e) { return INITIAL_DATA; }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_operators');
      return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
    } catch (e) { return DEFAULT_OPERATORS; }
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_shifts');
      return saved ? JSON.parse(saved) : [
        { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '5', name: 'Comercial', startTime: '08:00', endTime: '18:00', type: 'Diurno' }
      ];
    } catch (e) { return []; }
  });

  const [employees, setEmployees] = useState<Employee[]>([]);
  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>([]);
  const [jobRoles, setJobRoles] = useState<string[]>(DEFAULT_HIERARCHY);
  const [personnelStructure, setPersonnelStructure] = useState<any>(null);

  // Sync to LocalStorage
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isEremaChartModalOpen, setIsEremaChartModalOpen] = useState(false);

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec', 'Supervisão'];

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const raw = JSON.parse(event.target?.result as string);
        const data = Array.isArray(raw) ? { productionData: raw } : raw;

        if (data.productionData && Array.isArray(data.productionData)) {
            const normalized = data.productionData.map((item: any) => ({
                ...item,
                date: item.date && item.date.includes('/') ? item.date.split('/').reverse().join('-') : item.date
            }));
            setProductionData(normalized);

            // Auto-sync month to the newest entry
            const dates = normalized.map((i: any) => i.date).filter(Boolean).sort();
            if (dates.length > 0) {
                const latestMonth = dates[dates.length - 1].slice(0, 7);
                setDashboardMonth(latestMonth);
            }
        }

        if (data.goalValue) setGoalValue(Number(data.goalValue));
        if (data.operators) setOperators(data.operators);
        if (data.shifts) setShifts(data.shifts);

        alert('Backup restaurado! O dashboard foi sincronizado com os dados carregados.');
        setIsMenuOpen(false);
      } catch (err) {
        alert('Erro ao ler o arquivo de backup.');
      }
    };
    reader.readAsText(file);
  };

  const formatWeight = (val: number) => {
    if (isNaN(val)) return '0 KG';
    if (val >= 1000) return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  // Filtered values for dashboard
  const totals = useMemo(() => {
    const now = new Date();
    const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');

    const results = { month: 0, eremaMonth: 0, yesterday: 0, projection: 0, remaining: 0, dailyRequired: 0 };

    const currentYear = parseInt(dashboardMonth.split('-')[0]);
    const currentMonth = parseInt(dashboardMonth.split('-')[1]) - 1;
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

    // Se for o mês atual, usa o dia de hoje, senão usa o fim do mês para o cálculo de projeção
    const isCurrentMonth = now.getFullYear() === currentYear && now.getMonth() === currentMonth;
    const referenceDay = isCurrentMonth ? now.getDate() : daysInMonth;

    productionData.forEach(e => {
      const isErema = e.machine.toLowerCase().includes('erema');
      if (e.date.startsWith(dashboardMonth)) {
        if (isErema) results.eremaMonth += (e.netWeight || 0);
        else results.month += (e.netWeight || 0);
      }
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
    });

    results.projection = referenceDay > 0 ? (results.month / referenceDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);
    const dr = Math.max(0, daysInMonth - referenceDay);
    results.dailyRequired = dr > 0 ? results.remaining / dr : results.remaining;

    return results;
  }, [productionData, dashboardMonth, goalValue]);

  const filteredDataForCharts = useMemo(() => {
    return productionData.filter(e => e.date.startsWith(dashboardMonth));
  }, [productionData, dashboardMonth]);

  const stats = useMemo(() => {
    const is: Record<string, OperatorStat> = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 });

    filteredDataForCharts.forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0);
      is[e.operator].ecoBP += (e.ecoBP || 0);
      is[e.operator].ecoBM += (e.ecoBM || 0);
      is[e.operator].borra += (e.borraTotal || 0);
      is[e.operator].p_manut += (e.manutencaoMin || 0);
      is[e.operator].p_proc += (e.processoMin || 0);
      is[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(is);
  }, [filteredDataForCharts, operators]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const ms = searchTerm ? Object.values(e).some(v => String(v).toLowerCase().includes(searchTerm.toLowerCase())) : true;
      const mst = filterStartDate ? e.date >= filterStartDate : true;
      const me = filterEndDate ? e.date <= filterEndDate : true;
      return ms && mst && me;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportTotals = useMemo(() => {
    return filteredReports.reduce((acc, item) => ({
      net: acc.net + (item.netWeight || 0),
      ecoA: acc.ecoA + (item.ecoA || 0),
      borra: acc.borra + (item.borraTotal || 0),
      paradas: acc.paradas + (item.manutencaoMin + item.processoMin + item.outrosMin),
    }), { net: 0, ecoA: 0, borra: 0, paradas: 0 });
  }, [filteredReports]);

  const allCharts = [
    { title: 'Produção Líquida', key: 'prod', description: 'Total produzido (KG)', formatter: formatWeight },
    { title: 'Eficiência Eco A', key: 'ecoA', description: 'Nobre recuperado (KG)', formatter: formatWeight },
    { title: 'Resíduo Borra', key: 'borra', description: 'Perda total (KG)', formatter: formatWeight },
    { title: 'Eco B (Total)', key: 'eco_total', description: 'P + M recuperado (KG)', formatter: formatWeight },
    { title: 'Tempo Parada', key: 'stop_total', description: 'Minutos totais parados', formatter: formatMinutes },
  ];

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
        <div className="text-center space-y-2">
          <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
          <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Acesso Restrito</p>
        </div>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl transition-all">Entrar</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-2.5 rounded-xl shadow-lg hover:bg-blue-700 transition-all"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm overflow-x-auto">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}><BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span></button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}><FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span></button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            {/* Header Monthly Goal */}
            <div className={`bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between ${totals.month >= goalValue ? 'animate-goal-reached' : ''}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div><p className="text-[10px] font-bold opacity-80 tracking-widest mb-1">DESEMPENHO</p><h2 className="text-2xl font-black uppercase tracking-tight">META MENSAL ({dashboardMonth.split('-').reverse().join('/')})</h2></div>
                    <div className="bg-white/20 p-2.5 rounded-xl backdrop-blur-sm"><Target size={24} className="text-white" /></div>
                 </div>
                 <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-5xl font-black tracking-tight">{formatWeight(totals.month)}</span>
                    <span className="text-sm font-bold opacity-80">/ {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%</span>
                 </div>
                 <div className="w-full bg-black/20 h-2.5 rounded-full mb-6 overflow-hidden">
                    <div className="bg-white h-full rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Objetivo</p><p className="text-sm font-bold">{formatWeight(goalValue)}</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Média Nec.</p><p className="text-sm font-bold">{formatWeight(totals.dailyRequired)}/dia</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p><p className="text-sm font-bold">{formatWeight(totals.projection)}</p></div>
                     <div onClick={() => setIsEremaChartModalOpen(true)} className="bg-emerald-500/20 rounded-xl p-3 backdrop-blur-sm cursor-pointer hover:bg-emerald-500/30 transition-all"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Erema</p><p className="text-sm font-bold">{formatWeight(totals.eremaMonth)}</p></div>
                 </div>
            </div>

            {/* Detailed Charts Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {allCharts.map((chart, idx) => {
                    const data = stats.map(s => {
                        let value = 0;
                        if (chart.key === 'prod') value = s.prod;
                        else if (chart.key === 'ecoA') value = s.ecoA;
                        else if (chart.key === 'borra') value = s.borra;
                        else if (chart.key === 'eco_total') value = s.ecoBP + s.ecoBM;
                        else if (chart.key === 'stop_total') value = s.p_manut + s.p_proc + s.p_outros;
                        return { name: s.name, value };
                    }).filter(item => item.value > 0).sort((a, b) => b.value - a.value);

                    if (data.length === 0) return null;

                    return (
                        <div key={idx} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
                            <div className="mb-4">
                                <h3 className="text-sm font-black uppercase text-slate-800 tracking-tight">{chart.title}</h3>
                                <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">{chart.description}</p>
                            </div>
                            <div className="h-64 w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={data}
                                            cx="50%" cy="50%"
                                            innerRadius={60} outerRadius={80}
                                            paddingAngle={4} dataKey="value" stroke="none"
                                            label={renderCustomizedLabel}
                                        >
                                            {data.map((_, i) => <Cell key={`cell-${i}`} fill={COLORS[i % COLORS.length]} />)}
                                        </Pie>
                                        <Tooltip formatter={(v: number) => chart.formatter(v)} />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                            <div className="mt-4 space-y-1">
                                {data.slice(0, 3).map((item, i) => (
                                    <div key={i} className="flex justify-between items-center text-[10px] font-bold">
                                        <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{backgroundColor: COLORS[i % COLORS.length]}}></div><span className="text-slate-500 uppercase">{item.name}</span></div>
                                        <span className="text-slate-800">{chart.formatter(item.value)}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
           <div className="space-y-6 animate-in fade-in duration-300">
              <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
                 <div className="flex flex-1 items-center gap-2 w-full">
                    <Search className="text-slate-400" size={20} />
                    <input type="text" placeholder="Buscar registros..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl py-3 px-4 text-sm font-bold outline-none" />
                 </div>
                 <button onClick={() => fileInputRef.current?.click()} className="bg-slate-800 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-slate-900 transition-all"><Upload size={16} /> Restaurar Backup</button>
              </div>
              <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/80 border-b border-slate-100">
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Data / Turno</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Máquina</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Operador</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Peso Líq</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Eco A</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Borra</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Parada</th>
                                <th className="px-6 py-4 w-10"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {filteredReports.map(item => (
                                <tr key={item.id} className="hover:bg-blue-50/30 transition-colors">
                                    <td className="px-6 py-4"><span className="text-[11px] font-black text-slate-700 block">{item.date.split('-').reverse().join('/')}</span><span className="text-[9px] font-bold text-slate-400">{item.shift}</span></td>
                                    <td className="px-6 py-4"><span className="inline-flex px-2 py-0.5 rounded-lg text-[9px] font-black uppercase bg-slate-100 text-slate-600">{item.machine}</span></td>
                                    <td className="px-6 py-4 text-[10px] font-bold text-slate-600">{item.operator}</td>
                                    <td className="px-6 py-4 text-right text-[11px] font-black text-slate-800">{formatWeight(item.netWeight)}</td>
                                    <td className="px-6 py-4 text-right text-[10px] font-bold text-emerald-600">{item.ecoA} kg</td>
                                    <td className="px-6 py-4 text-right text-[10px] font-bold text-red-400">{item.borraTotal} kg</td>
                                    <td className="px-6 py-4 text-right text-[10px] font-bold text-orange-400">{item.manutencaoMin + item.processoMin + item.outrosMin} min</td>
                                    <td className="px-6 py-4"><button onClick={() => { setEditingEntry(item); setIsModalOpen(true); }} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 size={12}/></button></td>
                                </tr>
                            ))}
                        </tbody>
                        <tfoot className="bg-slate-50 font-black text-slate-700 border-t border-slate-200">
                           <tr>
                              <td colSpan={3} className="px-6 py-4 text-[10px] uppercase text-right tracking-widest text-slate-400">Totais:</td>
                              <td className="px-6 py-4 text-[10px] text-right text-blue-600">{formatWeight(reportTotals.net)}</td>
                              <td className="px-6 py-4 text-[10px] text-right text-emerald-600">{reportTotals.ecoA} kg</td>
                              <td className="px-6 py-4 text-[10px] text-right text-red-500">{reportTotals.borra} kg</td>
                              <td className="px-6 py-4 text-[10px] text-right text-orange-500">{reportTotals.paradas} min</td>
                              <td></td>
                           </tr>
                        </tfoot>
                    </table>
                 </div>
              </div>
           </div>
        )}
      </main>

      <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />

      <LaunchModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} availableShifts={shifts} initialData={editingEntry} />

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end" onClick={() => setIsMenuOpen(false)}>
            <div className="w-80 bg-white h-full shadow-2xl p-6 animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-8"><h2 className="text-xl font-black uppercase text-slate-800">Opções</h2><button onClick={() => setIsMenuOpen(false)}><X size={24} /></button></div>
                <div className="space-y-6">
                    <div><label className="text-[10px] font-black uppercase text-slate-400 mb-2 block">Meta Mensal</label><input type="number" value={goalValue} onChange={e => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold" /></div>
                    <div className="pt-6 border-t space-y-3">
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-3 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><Upload size={14}/> Carregar Backup</button>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="w-full py-3 bg-red-50 text-red-600 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><RotateCcw size={14}/> Resetar Sistema</button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, Settings, BarChart3, FileText, Search, 
  Printer, ShieldCheck, Download, Upload, Trash2, Cpu, 
  Save, X, Edit2, LogOut, TrendingUp, AlertTriangle, FileSpreadsheet, ImageIcon, Target, ChevronRight, RotateCcw, Clock, FileDown, Users, HardHat, Factory, Layers, UserPlus, UserCog, Briefcase, History, MoreHorizontal, Filter, TrendingDown, Layout, UserMinus, Calendar, User, Crown, UserCheck, Plane
} from 'lucide-react';
import { 
  Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';
import { ProductionEntry, Shift, Employee, PersonnelLog, PersonnelStructure } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS, PERSONNEL_DATA } from './constants';
import LaunchModal from './components/LaunchModal';
import ShiftModal from './components/ShiftModal';
import OperatorModal from './components/OperatorModal';
import EmployeeModal from './components/EmployeeModal';
import HistoryModal from './components/HistoryModal';
import RoleModal from './components/RoleModal';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];

const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.03) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.2;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text 
      x={x} 
      y={y} 
      fill="#64748b" 
      textAnchor={x > cx ? 'start' : 'end'} 
      dominantBaseline="central" 
      className="text-[11px] font-black"
    >
      {`${(percent * 100).toFixed(1)}%`}
    </text>
  );
};

interface OperatorStat {
  name: string;
  prod: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borra: number;
  p_manut: number;
  p_proc: number;
  p_outros: number;
}

const DEFAULT_HIERARCHY = [
  'Gerente', 'Supervisor', 'Líder de Produção', 'Líder de Turno', 
  'Operador 1', 'Operador 2', 'Operador 3', 'Auxiliar 1', 'Auxiliar 2'
];

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>(() => {
    return (localStorage.getItem('manupackaging_active_tab') as 'dashboard' | 'reports' | 'personnel') || 'dashboard';
  });
  const [selectedTimeframe, setSelectedTimeframe] = useState<'month' | 'today' | 'yesterday' | 'week'>(() => {
    return (localStorage.getItem('manupackaging_timeframe') as 'month' | 'today' | 'yesterday' | 'week') || 'month';
  });

  const [isGeneratingPDF, setIsGeneratingPDF] = useState(false);
  const dashboardRef = useRef<HTMLDivElement>(null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [searchTerm, setSearchTerm] = useState('');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const [confirmDialog, setConfirmDialog] = useState<{
    isOpen: boolean;
    title: string;
    message: string;
    onConfirm: () => void;
  }>({ isOpen: false, title: '', message: '', onConfirm: () => {} });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      return saved ? JSON.parse(saved) : INITIAL_DATA;
    } catch (e) { return INITIAL_DATA; }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [operators, setOperators] = useState<string[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_operators');
      return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
    } catch (e) { return DEFAULT_OPERATORS; }
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_shifts');
      return saved ? JSON.parse(saved) : [
        { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
        { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
        { id: '5', name: 'Comercial', startTime: '08:00', endTime: '18:00', type: 'Diurno' }
      ];
    } catch (e) { return []; }
  });

  const [employees, setEmployees] = useState<Employee[]>([]);
  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>([]);
  const [jobRoles, setJobRoles] = useState<string[]>(DEFAULT_HIERARCHY);
  const [personnelStructure, setPersonnelStructure] = useState<any>(null);

  // Sync to LocalStorage
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [isEremaChartModalOpen, setIsEremaChartModalOpen] = useState(false);

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec', 'Supervisão'];

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const raw = JSON.parse(event.target?.result as string);
        const data = Array.isArray(raw) ? { productionData: raw } : raw;

        if (data.productionData && Array.isArray(data.productionData)) {
            const normalized = data.productionData.map((item: any) => ({
                ...item,
                date: item.date && item.date.includes('/') ? item.date.split('/').reverse().join('-') : item.date
            }));
            setProductionData(normalized);

            // Auto-sync month to the newest entry
            const dates = normalized.map((i: any) => i.date).filter(Boolean).sort();
            if (dates.length > 0) {
                const latestMonth = dates[dates.length - 1].slice(0, 7);
                setDashboardMonth(latestMonth);
            }
        }

        if (data.goalValue) setGoalValue(Number(data.goalValue));
        if (data.operators) setOperators(data.operators);
        if (data.shifts) setShifts(data.shifts);

        alert('Backup restaurado! O dashboard foi sincronizado com os dados carregados.');
        setIsMenuOpen(false);
      } catch (err) {
        alert('Erro ao ler o arquivo de backup.');
      }
    };
    reader.readAsText(file);
  };

  const formatWeight = (val: number) => {
    if (isNaN(val)) return '0 KG';
    if (val >= 1000) return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  // Filtered values for dashboard
  const totals = useMemo(() => {
    const now = new Date();
    const yesterday = new Date(now); yesterday.setDate(now.getDate() - 1);
    const yesterdayStr = yesterday.toLocaleDateString('sv-SE');

    const results = { month: 0, eremaMonth: 0, yesterday: 0, projection: 0, remaining: 0, dailyRequired: 0 };

    const currentYear = parseInt(dashboardMonth.split('-')[0]);
    const currentMonth = parseInt(dashboardMonth.split('-')[1]) - 1;
    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();

    // Se for o mês atual, usa o dia de hoje, senão usa o fim do mês para o cálculo de projeção
    const isCurrentMonth = now.getFullYear() === currentYear && now.getMonth() === currentMonth;
    const referenceDay = isCurrentMonth ? now.getDate() : daysInMonth;

    productionData.forEach(e => {
      const isErema = e.machine.toLowerCase().includes('erema');
      if (e.date.startsWith(dashboardMonth)) {
        if (isErema) results.eremaMonth += (e.netWeight || 0);
        else results.month += (e.netWeight || 0);
      }
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
    });

    results.projection = referenceDay > 0 ? (results.month / referenceDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);
    const dr = Math.max(0, daysInMonth - referenceDay);
    results.dailyRequired = dr > 0 ? results.remaining / dr : results.remaining;

    return results;
  }, [productionData, dashboardMonth, goalValue]);

  const filteredDataForCharts = useMemo(() => {
    return productionData.filter(e => e.date.startsWith(dashboardMonth));
  }, [productionData, dashboardMonth]);

  const stats = useMemo(() => {
    const is: Record<string, OperatorStat> = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 });

    filteredDataForCharts.forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0);
      is[e.operator].ecoBP += (e.ecoBP || 0);
      is[e.operator].ecoBM += (e.ecoBM || 0);
      is[e.operator].borra += (e.borraTotal || 0);
      is[e.operator].p_manut += (e.manutencaoMin || 0);
      is[e.operator].p_proc += (e.processoMin || 0);
      is[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(is);
  }, [filteredDataForCharts, operators]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const ms = searchTerm ? Object.values(e).some(v => String(v).toLowerCase().includes(searchTerm.toLowerCase())) : true;
      const mst = filterStartDate ? e.date >= filterStartDate : true;
      const me = filterEndDate ? e.date <= filterEndDate : true;
      return ms && mst && me;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportTotals = useMemo(() => {
    return filteredReports.reduce((acc, item) => ({
      net: acc.net + (item.netWeight || 0),
      ecoA: acc.ecoA + (item.ecoA || 0),
      borra: acc.borra + (item.borraTotal || 0),
      paradas: acc.paradas + (item.manutencaoMin + item.processoMin + item.outrosMin),
    }), { net: 0, ecoA: 0, borra: 0, paradas: 0 });
  }, [filteredReports]);

  // Fix: Implemented handleSaveEntry to handle creation and updates of production records
  const handleSaveEntry = (entry: Omit<ProductionEntry, 'id'> & { id?: string }) => {
    if (entry.id) {
      // Update existing record
      setProductionData(prev => prev.map(e => e.id === entry.id ? { ...e, ...entry } as ProductionEntry : e));
    } else {
      // Create new record with unique ID
      const newEntry: ProductionEntry = {
        ...entry,
        id: Math.random().toString(36).substring(2, 9),
      } as ProductionEntry;
      setProductionData(prev => [newEntry, ...prev]);
    }
  };

  const allCharts = [
    { title: 'Produção Líquida', key: 'prod', description: 'Total produzido (KG)', formatter: formatWeight },
    { title: 'Eficiência Eco A', key: 'ecoA', description: 'Nobre recuperado (KG)', formatter: formatWeight },
    { title: 'Resíduo Borra', key: 'borra', description: 'Perda total (KG)', formatter: formatWeight },
    { title: 'Eco B (Total)', key: 'eco_total', description: 'P + M recuperado (KG)', formatter: formatWeight },
    { title: 'Tempo Parada', key: 'stop_total', description: 'Minutos totais parados', formatter: formatMinutes },
  ];

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-8">
        <div className="text-center space-y-2">
          <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
          <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
          <p className="text-slate-400 text-[10px] font-bold uppercase tracking-widest">Acesso Restrito</p>
        </div>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl transition-all">Entrar</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-2.5 rounded-xl shadow-lg hover:bg-blue-700 transition-all"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm overflow-x-auto">
          <button onClick={() => setActiveTab('dashboard')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}><BarChart3 size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Indicadores</span></button>
          <button onClick={() => setActiveTab('reports')} className={`flex items-center gap-2 px-6 py-2.5 rounded-xl transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400 hover:text-slate-600'}`}><FileText size={18} /><span className="text-[11px] font-black uppercase tracking-tighter">Relatórios</span></button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-8">
        {activeTab === 'dashboard' && (
          <div ref={dashboardRef} className="space-y-6 animate-in fade-in duration-300">
            {/* Header Monthly Goal */}
            <div className={`bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between ${totals.month >= goalValue ? 'animate-goal-reached' : ''}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div><p className="text-[10px] font-bold opacity-80 tracking-widest mb-1">DESEMPENHO</p><h2 className="text-2xl font-black uppercase tracking-tight">META MENSAL ({dashboardMonth.split('-').reverse().join('/')})</h2></div>
                    <div className="bg-white/20 p-2.5 rounded-xl backdrop-blur-sm"><Target size={24} className="text-white" /></div>
                 </div>
                 <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-5xl font-black tracking-tight">{formatWeight(totals.month)}</span>
                    <span className="text-sm font-bold opacity-80">/ {Math.min(((totals.month/goalValue)*100), 100).toFixed(1)}%</span>
                 </div>
                 <div className="w-full bg-black/20 h-2.5 rounded-full mb-6 overflow-hidden">
                    <div className="bg-white h-full rounded-full transition-all duration-1000 ease-out" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Objetivo</p><p className="text-sm font-bold">{formatWeight(goalValue)}</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Média Nec.</p><p className="text-sm font-bold">{formatWeight(totals.dailyRequired)}/dia</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p><p className="text-sm font-bold">{formatWeight(totals.projection)}</p></div>
                     <div onClick={() => setIsEremaChartModalOpen(true)} className="bg-emerald-500/20 rounded-xl p-3 backdrop-blur-sm cursor-pointer hover:bg-emerald-500/30 transition-all"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Erema</p><p className="text-sm font-bold">{formatWeight(totals.eremaMonth)}</p></div>
                 </div>
            </div>

            {/* Detailed Charts Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {allCharts.map((chart, idx) => {
                    const data = stats.map(s => {
                        let value = 0;
                        if (chart.key === 'prod') value = s.prod;
                        else if (chart.key === 'ecoA') value = s.ecoA;
                        else if (chart.key === 'borra') value = s.borra;
                        else if (chart.key === 'eco_total') value = s.ecoBP + s.ecoBM;
                        else if (chart.key === 'stop_total') value = s.p_manut + s.p_proc + s.p_outros;
                        return { name: s.name, value };
                    }).filter(item => item.value > 0).sort((a, b) => b.value - a.value);

                    if (data.length === 0) return null;

                    return (
                        <div key={idx} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col">
                            <div className="mb-4">
                                <h3 className="text-sm font-black uppercase text-slate-800 tracking-tight">{chart.title}</h3>
                                <p className="text-[10px] text-slate-400 font-bold uppercase mt-1">{chart.description}</p>
                            </div>
                            <div className="h-64 w-full">
                                <ResponsiveContainer width="100%" height="100%">
                                    <PieChart>
                                        <Pie
                                            data={data}
                                            cx="50%" cy="50%"
                                            innerRadius={60} outerRadius={80}
                                            paddingAngle={4} dataKey="value" stroke="none"
                                            label={renderCustomizedLabel}
                                        >
                                            {data.map((_, i) => <Cell key={`cell-${i}`} fill={COLORS[i % COLORS.length]} />)}
                                        </Pie>
                                        <Tooltip formatter={(v: number) => chart.formatter(v)} />
                                    </PieChart>
                                </ResponsiveContainer>
                            </div>
                            <div className="mt-4 space-y-1">
                                {data.slice(0, 3).map((item, i) => (
                                    <div key={i} className="flex justify-between items-center text-[10px] font-bold">
                                        <div className="flex items-center gap-2"><div className="w-2 h-2 rounded-full" style={{backgroundColor: COLORS[i % COLORS.length]}}></div><span className="text-slate-500 uppercase">{item.name}</span></div>
                                        <span className="text-slate-800">{chart.formatter(item.value)}</span>
                                    </div>
                                ))}
                            </div>
                        </div>
                    );
                })}
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
           <div className="space-y-6 animate-in fade-in duration-300">
              <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row justify-between items-center gap-4">
                 <div className="flex flex-1 items-center gap-2 w-full">
                    <Search className="text-slate-400" size={20} />
                    <input type="text" placeholder="Buscar registros..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl py-3 px-4 text-sm font-bold outline-none" />
                 </div>
                 <button onClick={() => fileInputRef.current?.click()} className="bg-slate-800 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2 hover:bg-slate-900 transition-all"><Upload size={16} /> Restaurar Backup</button>
              </div>
              <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
                 <div className="overflow-x-auto">
                    <table className="w-full text-left border-collapse">
                        <thead>
                            <tr className="bg-slate-50/80 border-b border-slate-100">
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Data / Turno</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Máquina</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest">Operador</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Peso Líq</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Eco A</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Borra</th>
                                <th className="px-6 py-4 text-[9px] font-black text-slate-400 uppercase tracking-widest text-right">Parada</th>
                                <th className="px-6 py-4 w-10"></th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {filteredReports.map(item => (
                                <tr key={item.id} className="hover:bg-blue-50/30 transition-colors">
                                    <td className="px-6 py-4"><span className="text-[11px] font-black text-slate-700 block">{item.date.split('-').reverse().join('/')}</span><span className="text-[9px] font-bold text-slate-400">{item.shift}</span></td>
                                    <td className="px-6 py-4"><span className="inline-flex px-2 py-0.5 rounded-lg text-[9px] font-black uppercase bg-slate-100 text-slate-600">{item.machine}</span></td>
                                    <td className="px-6 py-4 text-[10px] font-bold text-slate-600">{item.operator}</td>
                                    <td className="px-6 py-4 text-right text-[11px] font-black text-slate-800">{formatWeight(item.netWeight)}</td>
                                    <td className="px-6 py-4 text-right text-[10px] font-bold text-emerald-600">{item.ecoA} kg</td>
                                    <td className="px-6 py-4 text-right text-[10px] font-bold text-red-400">{item.borraTotal} kg</td>
                                    <td className="px-6 py-4 text-right text-[10px] font-bold text-orange-400">{item.manutencaoMin + item.processoMin + item.outrosMin} min</td>
                                    <td className="px-6 py-4"><button onClick={() => { setEditingEntry(item); setIsModalOpen(true); }} className="p-1.5 text-blue-600 hover:bg-blue-50 rounded-lg transition-colors"><Edit2 size={12}/></button></td>
                                </tr>
                            ))}
                        </tbody>
                        <tfoot className="bg-slate-50 font-black text-slate-700 border-t border-slate-200">
                           <tr>
                              <td colSpan={3} className="px-6 py-4 text-[10px] uppercase text-right tracking-widest text-slate-400">Totais:</td>
                              <td className="px-6 py-4 text-[10px] text-right text-blue-600">{formatWeight(reportTotals.net)}</td>
                              <td className="px-6 py-4 text-[10px] text-right text-emerald-600">{reportTotals.ecoA} kg</td>
                              <td className="px-6 py-4 text-[10px] text-right text-red-500">{reportTotals.borra} kg</td>
                              <td className="px-6 py-4 text-[10px] text-right text-orange-500">{reportTotals.paradas} min</td>
                              <td></td>
                           </tr>
                        </tfoot>
                    </table>
                 </div>
              </div>
           </div>
        )}
      </main>

      <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />

      <LaunchModal isOpen={isModalOpen} onClose={() => { setIsModalOpen(false); setEditingEntry(null); }} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} availableShifts={shifts} initialData={editingEntry} />

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end" onClick={() => setIsMenuOpen(false)}>
            <div className="w-80 bg-white h-full shadow-2xl p-6 animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-8"><h2 className="text-xl font-black uppercase text-slate-800">Opções</h2><button onClick={() => setIsMenuOpen(false)}><X size={24} /></button></div>
                <div className="space-y-6">
                    <div><label className="text-[10px] font-black uppercase text-slate-400 mb-2 block">Meta Mensal</label><input type="number" value={goalValue} onChange={e => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold" /></div>
                    <div className="pt-6 border-t space-y-3">
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-3 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><Upload size={14}/> Carregar Backup</button>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="w-full py-3 bg-red-50 text-red-600 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><RotateCcw size={14}/> Resetar Sistema</button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, Settings, BarChart3, FileText, Search, 
  Printer, ShieldCheck, Download, Upload, Trash2, Cpu, 
  Save, X, Edit2, LogOut, TrendingUp, AlertTriangle, FileSpreadsheet, ImageIcon, Target, ChevronRight, RotateCcw, Clock, FileDown, Users, HardHat, Factory, Layers, UserPlus, UserCog, Briefcase, History, MoreHorizontal, Filter, TrendingDown, Layout, UserMinus, Calendar, User, Crown, UserCheck, Plane
} from 'lucide-react';
import { 
  Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
import { ProductionEntry, Shift, Employee, PersonnelLog, PersonnelStructure } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS, PERSONNEL_DATA } from './constants';
import LaunchModal from './components/LaunchModal';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];

const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.03) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.2;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text x={x} y={y} fill="#64748b" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" className="text-[11px] font-black">
      {`${(percent * 100).toFixed(1)}%`}
    </text>
  );
};

interface OperatorStat {
  name: string;
  prod: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borra: number;
  p_manut: number;
  p_proc: number;
  p_outros: number;
}

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports'>('dashboard');
  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      return saved ? JSON.parse(saved) : INITIAL_DATA;
    } catch (e) { return INITIAL_DATA; }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [operators, setOperators] = useState<string[]>(DEFAULT_OPERATORS);
  const [shifts, setShifts] = useState<Shift[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec', 'Supervisão'];

  const formatWeight = (val: number) => {
    if (isNaN(val)) return '0 KG';
    if (val >= 1000) return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const raw = JSON.parse(event.target?.result as string);
        const data = Array.isArray(raw) ? { productionData: raw } : raw;

        if (data.productionData && Array.isArray(data.productionData)) {
            const normalized = data.productionData.map((item: any) => ({
                ...item,
                date: item.date && item.date.includes('/') ? item.date.split('/').reverse().join('-') : item.date
            }));

            setProductionData(normalized);

            // Localizar mês mais recente para sincronizar os gráficos
            const sortedDates = normalized.map((i: any) => i.date).filter(Boolean).sort();
            if (sortedDates.length > 0) {
                const latestMonth = sortedDates[sortedDates.length - 1].slice(0, 7);
                setDashboardMonth(latestMonth);
            }
            alert('Backup restaurado! Gráficos sincronizados com as novas datas.');
        }
        if (data.goalValue) setGoalValue(Number(data.goalValue));
        setIsMenuOpen(false);
      } catch (err) { alert('Erro ao processar backup.'); }
    };
    reader.readAsText(file);
  };

  const totals = useMemo(() => {
    const now = new Date();
    const yesterdayStr = new Date(Date.now() - 86400000).toLocaleDateString('sv-SE');
    const results = { month: 0, eremaMonth: 0, yesterday: 0, projection: 0, remaining: 0, dailyRequired: 0 };

    const [year, month] = dashboardMonth.split('-').map(Number);
    const daysInMonth = new Date(year, month, 0).getDate();
    const isCurrentMonth = now.getFullYear() === year && (now.getMonth() + 1) === month;
    const refDay = isCurrentMonth ? now.getDate() : daysInMonth;

    productionData.forEach(e => {
      const isErema = e.machine.toLowerCase().includes('erema');
      if (e.date.startsWith(dashboardMonth)) {
        if (isErema) results.eremaMonth += (e.netWeight || 0);
        else results.month += (e.netWeight || 0);
      }
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
    });

    results.projection = refDay > 0 ? (results.month / refDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);
    const daysLeft = Math.max(0, daysInMonth - refDay);
    results.dailyRequired = daysLeft > 0 ? results.remaining / daysLeft : results.remaining;

    return results;
  }, [productionData, dashboardMonth, goalValue]);

  const stats = useMemo(() => {
    const is: Record<string, OperatorStat> = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 });

    productionData.filter(e => e.date.startsWith(dashboardMonth)).forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0);
      is[e.operator].ecoBP += (e.ecoBP || 0);
      is[e.operator].ecoBM += (e.ecoBM || 0);
      is[e.operator].borra += (e.borraTotal || 0);
      is[e.operator].p_manut += (e.manutencaoMin || 0);
      is[e.operator].p_proc += (e.processoMin || 0);
      is[e.operator].p_outros += (e.outrosMin || 0);
    });
    return Object.values(is);
  }, [productionData, dashboardMonth, operators]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const ms = searchTerm ? Object.values(e).some(v => String(v).toLowerCase().includes(searchTerm.toLowerCase())) : true;
      const mst = filterStartDate ? e.date >= filterStartDate : true;
      const me = filterEndDate ? e.date <= filterEndDate : true;
      return ms && mst && me;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportTotals = useMemo(() => {
    return filteredReports.reduce((acc, item) => ({
      net: acc.net + (item.netWeight || 0),
      ecoA: acc.ecoA + (item.ecoA || 0),
      borra: acc.borra + (item.borraTotal || 0),
      paradas: acc.paradas + (item.manutencaoMin + item.processoMin + item.outrosMin),
    }), { net: 0, ecoA: 0, borra: 0, paradas: 0 });
  }, [filteredReports]);

  const handleSaveEntry = (entry: any) => {
    if (entry.id) {
      setProductionData(prev => prev.map(e => e.id === entry.id ? { ...e, ...entry } : e));
    } else {
      setProductionData(prev => [{ ...entry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
    }
  };

  const chartConfigs = [
    { title: 'Produção Líquida', key: 'prod', formatter: formatWeight },
    { title: 'Eficiência Eco A', key: 'ecoA', formatter: formatWeight },
    { title: 'Resíduo Borra', key: 'borra', formatter: formatWeight },
    { title: 'Tempo Parada', key: 'stops', formatter: formatMinutes },
  ];

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-6 text-center">
        <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
        <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl transition-all">Entrar no Sistema</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-2.5 rounded-xl shadow-lg hover:bg-blue-700 transition-all"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm">
          <button onClick={() => setActiveTab('dashboard')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Indicadores</button>
          <button onClick={() => setActiveTab('reports')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Relatórios</button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className={`bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between ${totals.month >= goalValue ? 'animate-goal-reached' : ''}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div><p className="text-[10px] font-bold opacity-80 uppercase mb-1">Meta Mensal ({dashboardMonth})</p><h2 className="text-2xl font-black uppercase">Desempenho de Produção</h2></div>
                    <Target size={24} className="opacity-40" />
                 </div>
                 <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-5xl font-black">{formatWeight(totals.month)}</span>
                    <span className="text-sm font-bold opacity-80">/ {((totals.month/goalValue)*100).toFixed(1)}%</span>
                 </div>
                 <div className="w-full bg-black/20 h-2.5 rounded-full mb-6 overflow-hidden">
                    <div className="bg-white h-full rounded-full transition-all duration-1000" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Objetivo</p><p className="text-sm font-bold">{formatWeight(goalValue)}</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Média Nec.</p><p className="text-sm font-bold">{formatWeight(totals.dailyRequired)}/dia</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p><p className="text-sm font-bold">{formatWeight(totals.projection)}</p></div>
                     <div className="bg-emerald-500/20 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Recuperado Erema</p><p className="text-sm font-bold">{formatWeight(totals.eremaMonth)}</p></div>
                 </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {chartConfigs.map((config, idx) => {
                const data = stats.map(s => {
                  let value = 0;
                  if (config.key === 'prod') value = s.prod;
                  else if (config.key === 'ecoA') value = s.ecoA;
                  else if (config.key === 'borra') value = s.borra;
                  else if (config.key === 'stops') value = s.p_manut + s.p_proc + s.p_outros;
                  return { name: s.name, value };
                }).filter(i => i.value > 0);

                if (data.length === 0) return null;

                return (
                  <div key={idx} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                    <h3 className="text-xs font-black uppercase text-slate-800 mb-4">{config.title}</h3>
                    <div className="h-64">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={data} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={4} dataKey="value" label={renderCustomizedLabel}>
                            {data.map((_, i) => <Cell key={`cell-${i}`} fill={COLORS[i % COLORS.length]} />)}
                          </Pie>
                          <Tooltip formatter={(v: number) => config.formatter(v)} />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-6">
            <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex items-center gap-4">
              <Search className="text-slate-400" size={20} />
              <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl py-3 px-4 text-sm font-bold outline-none" />
              <button onClick={() => fileInputRef.current?.click()} className="bg-slate-800 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center gap-2"><Upload size={16} /> Backup</button>
            </div>
            <div className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden">
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="bg-slate-50 border-b border-slate-100 text-[9px] font-black uppercase tracking-widest text-slate-400">
                      <th className="px-6 py-4">Data/Turno</th>
                      <th className="px-6 py-4">Máquina</th>
                      <th className="px-6 py-4">Operador</th>
                      <th className="px-6 py-4 text-right">Peso Líq</th>
                      <th className="px-6 py-4 text-right">Eco A</th>
                      <th className="px-6 py-4 text-right">Borra</th>
                      <th className="px-6 py-4 text-right">Paradas</th>
                      <th className="px-6 py-4"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filteredReports.map(item => (
                      <tr key={item.id} className="hover:bg-blue-50/30 transition-colors text-[11px] font-bold">
                        <td className="px-6 py-4"><span>{item.date.split('-').reverse().join('/')}</span><br/><span className="text-[9px] text-slate-400">{item.shift}</span></td>
                        <td className="px-6 py-4 uppercase"><span className="bg-slate-100 px-2 py-0.5 rounded text-slate-600">{item.machine}</span></td>
                        <td className="px-6 py-4">{item.operator}</td>
                        <td className="px-6 py-4 text-right font-black">{formatWeight(item.netWeight)}</td>
                        <td className="px-6 py-4 text-right text-emerald-600">{item.ecoA} kg</td>
                        <td className="px-6 py-4 text-right text-red-500">{item.borraTotal} kg</td>
                        <td className="px-6 py-4 text-right text-orange-400">{item.manutencaoMin + item.processoMin + item.outrosMin} m</td>
                        <td className="px-6 py-4"><button onClick={() => { setEditingEntry(item); setIsModalOpen(true); }} className="p-1.5 text-blue-600"><Edit2 size={12}/></button></td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot className="bg-slate-50 font-black text-slate-800 text-[10px]">
                    <tr>
                      <td colSpan={3} className="px-6 py-4 text-right">TOTAL:</td>
                      <td className="px-6 py-4 text-right text-blue-600">{formatWeight(reportTotals.net)}</td>
                      <td className="px-6 py-4 text-right text-emerald-600">{reportTotals.ecoA} kg</td>
                      <td className="px-6 py-4 text-right text-red-500">{reportTotals.borra} kg</td>
                      <td className="px-6 py-4 text-right text-orange-500">{reportTotals.paradas} min</td>
                      <td></td>
                    </tr>
                  </tfoot>
                </table>
              </div>
            </div>
          </div>
        )}
      </main>

      <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />

      <LaunchModal 
        isOpen={isModalOpen} 
        onClose={() => setIsModalOpen(false)} 
        onSave={handleSaveEntry} 
        operators={operators} 
        activeMachines={activeMachines} 
        availableShifts={shifts.length > 0 ? shifts : [{id:'1', name:'Diurno', type:'Diurno', startTime:'07:00', endTime:'19:00'}]} 
        initialData={editingEntry} 
      />

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/40" onClick={() => setIsMenuOpen(false)}>
            <div className="w-80 bg-white h-full shadow-2xl p-6" onClick={e => e.stopPropagation()}>
                <h2 className="text-xl font-black uppercase text-slate-800 mb-8 flex items-center justify-between">Opções <X onClick={() => setIsMenuOpen(false)} className="cursor-pointer" /></h2>
                <div className="space-y-6">
                    <div><label className="text-[10px] font-black uppercase text-slate-400 mb-2 block">Meta Mensal (KG)</label><input type="number" value={goalValue} onChange={e => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold" /></div>
                    <div><label className="text-[10px] font-black uppercase text-slate-400 mb-2 block">Mês do Painel</label><input type="month" value={dashboardMonth} onChange={e => setDashboardMonth(e.target.value)} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold" /></div>
                    <div className="pt-6 border-t space-y-3">
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-blue-50 text-blue-600 rounded-2xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><Upload size={14}/> Carregar Backup</button>
                        <button onClick={() => { localStorage.clear(); window.location.reload(); }} className="w-full py-4 bg-red-50 text-red-600 rounded-2xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><RotateCcw size={14}/> Resetar Tudo</button>
                        <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full py-4 bg-slate-800 text-white rounded-2xl font-black text-[10px] uppercase flex items-center justify-center gap-2"><LogOut size={14}/> Sair</button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, Settings, BarChart3, FileText, Search, 
  Printer, ShieldCheck, Download, Upload, Trash2, Cpu, 
  Save, X, Edit2, LogOut, TrendingUp, AlertTriangle, FileSpreadsheet, ImageIcon, Target, ChevronRight, RotateCcw, Clock, FileDown, Users, HardHat, Factory, Layers, UserPlus, UserCog, Briefcase, History, MoreHorizontal, Filter, TrendingDown, Layout, UserMinus, Calendar, User, Crown, UserCheck, Plane
} from 'lucide-react';
import { 
  Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
import { ProductionEntry, Shift, Employee, PersonnelLog, PersonnelStructure } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS, PERSONNEL_DATA } from './constants';
import LaunchModal from './components/LaunchModal';
import ShiftModal from './components/ShiftModal';
import OperatorModal from './components/OperatorModal';
import EmployeeModal from './components/EmployeeModal';
import HistoryModal from './components/HistoryModal';
import RoleModal from './components/RoleModal';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];

const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.03) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.2;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text x={x} y={y} fill="#64748b" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" className="text-[11px] font-black">
      {`${(percent * 100).toFixed(1)}%`}
    </text>
  );
};

interface OperatorStat {
  name: string;
  prod: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borra: number;
  p_manut: number;
  p_proc: number;
  p_outros: number;
}

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>(() => {
    return (localStorage.getItem('manupackaging_active_tab') as 'dashboard' | 'reports' | 'personnel') || 'dashboard';
  });

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      return saved ? JSON.parse(saved) : INITIAL_DATA;
    } catch (e) { return INITIAL_DATA; }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const saved = localStorage.getItem('manupackaging_operators');
    return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    const saved = localStorage.getItem('manupackaging_shifts');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
      { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' }
    ];
  });

  // Personnel States (Restauração da lógica de pessoal)
  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('manupackaging_employees');
    return saved ? JSON.parse(saved) : [];
  });
  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>(() => {
    const saved = localStorage.getItem('manupackaging_personnel_logs');
    return saved ? JSON.parse(saved) : [];
  });
  const [jobRoles, setJobRoles] = useState<string[]>(['Gerente', 'Supervisor', 'Líder de Produção', 'Líder de Turno', 'Operador 1', 'Operador 2', 'Operador 3', 'Auxiliar 1', 'Auxiliar 2']);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);
  const [isOperatorModalOpen, setIsOperatorModalOpen] = useState(false);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);

  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterStartDate, setFilterStartDate] = useState('');
  const [filterEndDate, setFilterEndDate] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);
  useEffect(() => { localStorage.setItem('manupackaging_active_tab', activeTab); }, [activeTab]);
  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_personnel_logs', JSON.stringify(personnelLogs)); }, [personnelLogs]);

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec', 'Supervisão'];

  const formatWeight = (val: number) => {
    if (isNaN(val)) return '0 KG';
    if (val >= 1000) return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const raw = JSON.parse(event.target?.result as string);
        const data = Array.isArray(raw) ? { productionData: raw } : raw;
        if (data.productionData) {
            const normalized = data.productionData.map((item: any) => ({
                ...item,
                date: item.date && item.date.includes('/') ? item.date.split('/').reverse().join('-') : item.date
            }));
            setProductionData(normalized);
            const sortedDates = normalized.map((i: any) => i.date).filter(Boolean).sort();
            if (sortedDates.length > 0) {
                setDashboardMonth(sortedDates[sortedDates.length - 1].slice(0, 7));
            }
        }
        if (data.employees) setEmployees(data.employees);
        if (data.goalValue) setGoalValue(Number(data.goalValue));
        alert('Backup restaurado com sucesso!');
        setIsMenuOpen(false);
      } catch (err) { alert('Erro ao processar backup.'); }
    };
    reader.readAsText(file);
  };

  const handleExportCSV = () => {
    const headers = ['Data', 'Turno', 'Máquina', 'Operador', 'Peso Líquido', 'Eco A', 'Borra', 'Paradas (min)'];
    const rows = filteredReports.map(e => [
      e.date.split('-').reverse().join('/'), e.shift, e.machine, e.operator, e.netWeight, e.ecoA, e.borraTotal, (e.manutencaoMin + e.processoMin + e.outrosMin)
    ].join(';'));
    const csvContent = "\uFEFF" + [headers.join(';'), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `relatorio_producao_${dashboardMonth}.csv`;
    link.click();
  };

  const handleBulkDelete = () => {
    if (window.confirm(`Excluir ${selectedIds.length} registros permanentemente?`)) {
      setProductionData(prev => prev.filter(e => !selectedIds.includes(e.id)));
      setSelectedIds([]);
    }
  };

  const totals = useMemo(() => {
    const now = new Date();
    const yesterdayStr = new Date(Date.now() - 86400000).toLocaleDateString('sv-SE');
    const results = { month: 0, eremaMonth: 0, yesterday: 0, projection: 0, remaining: 0, dailyRequired: 0 };
    const [year, month] = dashboardMonth.split('-').map(Number);
    const daysInMonth = new Date(year, month, 0).getDate();
    const isCurrentMonth = now.getFullYear() === year && (now.getMonth() + 1) === month;
    const refDay = isCurrentMonth ? now.getDate() : daysInMonth;

    productionData.forEach(e => {
      if (e.date.startsWith(dashboardMonth)) {
        if (e.machine.toLowerCase().includes('erema')) results.eremaMonth += (e.netWeight || 0);
        else results.month += (e.netWeight || 0);
      }
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
    });

    results.projection = refDay > 0 ? (results.month / refDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);
    const daysLeft = Math.max(0, daysInMonth - refDay);
    results.dailyRequired = daysLeft > 0 ? results.remaining / daysLeft : results.remaining;
    return results;
  }, [productionData, dashboardMonth, goalValue]);

  const stats = useMemo(() => {
    const is: Record<string, OperatorStat> = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 });
    productionData.filter(e => e.date.startsWith(dashboardMonth)).forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0);
      is[e.operator].borra += (e.borraTotal || 0);
      is[e.operator].p_manut += (e.manutencaoMin || 0);
      is[e.operator].p_proc += (e.processoMin || 0);
      is[e.operator].p_outros += (e.outrosMin || 0);
      is[e.operator].ecoBP += (e.ecoBP || 0);
      is[e.operator].ecoBM += (e.ecoBM || 0);
    });
    return Object.values(is);
  }, [productionData, dashboardMonth, operators]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const ms = searchTerm ? Object.values(e).some(v => String(v).toLowerCase().includes(searchTerm.toLowerCase())) : true;
      const mst = filterStartDate ? e.date >= filterStartDate : true;
      const me = filterEndDate ? e.date <= filterEndDate : true;
      return ms && mst && me;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm, filterStartDate, filterEndDate]);

  const reportTotals = useMemo(() => {
    return filteredReports.reduce((acc, item) => ({
      net: acc.net + (item.netWeight || 0),
      ecoA: acc.ecoA + (item.ecoA || 0),
      borra: acc.borra + (item.borraTotal || 0),
      paradas: acc.paradas + (item.manutencaoMin + item.processoMin + item.outrosMin),
    }), { net: 0, ecoA: 0, borra: 0, paradas: 0 });
  }, [filteredReports]);

  const handleSaveEntry = (entry: any) => {
    if (entry.id) setProductionData(prev => prev.map(e => e.id === entry.id ? { ...e, ...entry } : e));
    else setProductionData(prev => [{ ...entry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  };

  const handleEmployeeAction = (data: Partial<Employee>, action: string, details?: string) => {
    const timestamp = new Date().toISOString();
    if (action === 'Exclusão') {
      setEmployees(prev => prev.filter(e => e.id !== data.id));
    } else if (data.id) {
      setEmployees(prev => prev.map(e => e.id === data.id ? { ...e, ...data, updatedAt: timestamp } : e));
    } else {
      setEmployees(prev => [...prev, { ...data, id: Math.random().toString(36).substr(2, 9), updatedAt: timestamp } as Employee]);
    }
    setPersonnelLogs(prev => [{ id: Math.random().toString(36).substr(2, 9), date: timestamp, employeeName: data.name || 'Desconhecido', action: action as any, details: details || '', user: 'Admin' }, ...prev]);
  };

  const chartConfigs = [
    { title: 'Produção Líquida', key: 'prod', formatter: formatWeight },
    { title: 'Eficiência Eco A', key: 'ecoA', formatter: formatWeight },
    { title: 'Resíduo Borra', key: 'borra', formatter: formatWeight },
    { title: 'Tempo Parada', key: 'stops', formatter: formatMinutes },
    { title: 'Recuperado Eco B', key: 'ecoB', formatter: formatWeight },
  ];

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-6 text-center">
        <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
        <h1 className="text-2xl font-black text-slate-800">Manupackaging</h1>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl transition-all">Entrar no Sistema</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-2.5 rounded-xl shadow-lg hover:bg-blue-700 transition-all"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm overflow-x-auto">
          <button onClick={() => setActiveTab('dashboard')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Indicadores</button>
          <button onClick={() => setActiveTab('reports')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Relatórios</button>
          <button onClick={() => setActiveTab('personnel')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Gestão de Pessoal</button>
        </div>
      </div>

      <main className="max-w-6xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="space-y-6">
            <div className={`bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between ${totals.month >= goalValue ? 'animate-goal-reached' : ''}`}>
                 <div className="flex justify-between items-start mb-2">
                    <div><p className="text-[10px] font-bold opacity-80 uppercase mb-1">Meta Mensal ({dashboardMonth})</p><h2 className="text-2xl font-black uppercase tracking-tight">Desempenho de Produção</h2></div>
                    <Target size={24} className="opacity-40" />
                 </div>
                 <div className="flex items-baseline gap-2 mb-4">
                    <span className="text-5xl font-black">{formatWeight(totals.month)}</span>
                    <span className="text-sm font-bold opacity-80">/ {((totals.month/goalValue)*100).toFixed(1)}%</span>
                 </div>
                 <div className="w-full bg-black/20 h-2.5 rounded-full mb-6 overflow-hidden">
                    <div className="bg-white h-full rounded-full transition-all duration-1000" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                 </div>
                 <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Objetivo</p><p className="text-sm font-bold">{formatWeight(goalValue)}</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Média Nec.</p><p className="text-sm font-bold">{formatWeight(totals.dailyRequired)}/dia</p></div>
                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p><p className="text-sm font-bold">{formatWeight(totals.projection)}</p></div>
                     <div className="bg-emerald-500/20 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Erema</p><p className="text-sm font-bold">{formatWeight(totals.eremaMonth)}</p></div>
                 </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {chartConfigs.map((config, idx) => {
                const data = stats.map(s => {
                  let value = 0;
                  if (config.key === 'prod') value = s.prod;
                  else if (config.key === 'ecoA') value = s.ecoA;
                  else if (config.key === 'borra') value = s.borra;
                  else if (config.key === 'stops') value = s.p_manut + s.p_proc + s.p_outros;
                  else if (config.key === 'ecoB') value = s.ecoBP + s.ecoBM;
                  return { name: s.name, value };
                }).filter(i => i.value > 0).sort((a, b) => b.value - a.value);
                if (data.length === 0) return null;
                return (
                  <div key={idx} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-full">
                    <h3 className="text-xs font-black uppercase text-slate-800 mb-4">{config.title}</h3>
                    <div className="h-64">
                      <ResponsiveContainer width="100%" height="100%">
                        <PieChart>
                          <Pie data={data} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={4} dataKey="value" label={renderCustomizedLabel}>
                            {data.map((_, i) => <Cell key={`cell-${i}`} fill={COLORS[i % COLORS.length]} />)}
                          </Pie>
                          <Tooltip formatter={(v: number) => config.formatter(v)} />
                          <Legend wrapperStyle={{fontSize: '9px', fontWeight: 'bold', textTransform: 'uppercase'}} />
                        </PieChart>
                      </ResponsiveContainer>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {activeTab === 'reports' && (
          <div className="space-y-6">
            <div className="bg-white p-4 rounded-3xl border border-slate-100 shadow-sm flex flex-col md:flex-row items-center gap-4">
              <div className="flex-1 flex items-center gap-2 bg-slate-50 rounded-2xl px-4 py-3 w-full">
                <Search className="text-slate-400" size={18} />
                <input type="text" placeholder="Buscar..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} className="bg-transparent border-none w-full text-sm font-bold outline-none" />
              </div>
              <div className="flex items-center gap-2 w-full md:w-auto">
                <button onClick={handleExportCSV} className="flex-1 md:flex-none bg-slate-800 text-white px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center justify-center gap-2"><FileDown size={16} /> CSV</button>
                {selectedIds.length > 0 && <button onClick={handleBulkDelete} className="flex-1 md:flex-none bg-red-50 text-red-600 px-6 py-3 rounded-2xl text-xs font-black uppercase flex items-center justify-center gap-2"><Trash2 size={16} /> ({selectedIds.length})</button>}
              </div>
            </div>
            <div className="bg-white rounded-[2rem] border border-slate-100 overflow-hidden shadow-sm">
              <div className="overflow-x-auto">
                <table className="w-full text-left">
                  <thead className="bg-slate-50 border-b border-slate-100 text-[9px] font-black uppercase tracking-widest text-slate-400">
                    <tr>
                      <th className="px-6 py-4 w-10"><input type="checkbox" onChange={e => setSelectedIds(e.target.checked ? filteredReports.map(x => x.id) : [])} /></th>
                      <th className="px-6 py-4">Data/Turno</th>
                      <th className="px-6 py-4">Máquina</th>
                      <th className="px-6 py-4">Operador</th>
                      <th className="px-6 py-4 text-right">Peso Líq</th>
                      <th className="px-6 py-4 text-right">Eco A</th>
                      <th className="px-6 py-4 text-right">Borra</th>
                      <th className="px-6 py-4 text-right">Paradas</th>
                      <th className="px-6 py-4"></th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-slate-50">
                    {filteredReports.map(item => (
                      <tr key={item.id} className={`hover:bg-blue-50/30 transition-colors text-[11px] font-bold ${selectedIds.includes(item.id) ? 'bg-blue-50/50' : ''}`}>
                        <td className="px-6 py-4"><input type="checkbox" checked={selectedIds.includes(item.id)} onChange={() => setSelectedIds(prev => prev.includes(item.id) ? prev.filter(x => x !== item.id) : [...prev, item.id])} /></td>
                        <td className="px-6 py-4"><span>{item.date.split('-').reverse().join('/')}</span><br/><span className="text-[9px] text-slate-400 font-medium">{item.shift}</span></td>
                        <td className="px-6 py-4"><span className="bg-slate-100 px-2 py-0.5 rounded text-slate-600 uppercase text-[9px] font-black">{item.machine}</span></td>
                        <td className="px-6 py-4">{item.operator}</td>
                        <td className="px-6 py-4 text-right font-black">{formatWeight(item.netWeight)}</td>
                        <td className="px-6 py-4 text-right text-emerald-600">{item.ecoA} kg</td>
                        <td className="px-6 py-4 text-right text-red-500">{item.borraTotal} kg</td>
                        <td className="px-6 py-4 text-right text-orange-400">{item.manutencaoMin + item.processoMin + item.outrosMin} m</td>
                        <td className="px-6 py-4"><button onClick={() => { setEditingEntry(item); setIsModalOpen(true); }} className="p-1.5 text-blue-600 hover:bg-blue-100 rounded-lg"><Edit2 size={12}/></button></td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}

        {activeTab === 'personnel' && (
          <div className="space-y-8">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
              <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Equipe Total</p>
                <p className="text-3xl font-black text-slate-800">{employees.filter(e => e.status !== 'Desligado').length}</p>
              </div>
              <div className="bg-white p-6 rounded-[2rem] shadow-sm border border-slate-100">
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">Em Férias</p>
                <p className="text-3xl font-black text-orange-600">{employees.filter(e => e.status === 'Férias').length}</p>
              </div>
              <button onClick={() => setIsHistoryModalOpen(true)} className="md:col-span-2 bg-slate-800 text-white rounded-[2rem] p-6 flex items-center justify-between hover:bg-slate-900 transition-all group">
                <div><p className="text-[10px] font-black opacity-60 uppercase tracking-widest mb-1">Registros de RH</p><p className="text-xl font-black uppercase">Ver Histórico</p></div>
                <History className="group-hover:rotate-12 transition-transform" />
              </button>
            </div>

            <div className="space-y-6">
              <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
                <div className="bg-indigo-600 p-6 flex items-center justify-between text-white">
                  <div><h3 className="text-lg font-black uppercase tracking-tight">Liderança & Apoio</h3><p className="text-[10px] opacity-70 font-bold uppercase">Gestão e Coordenação Geral</p></div>
                  <button onClick={() => { setSelectedEmployee(null); setIsEmployeeModalOpen(true); }} className="bg-white/20 p-2.5 rounded-xl hover:bg-white/30 transition-all"><Plus size={20} /></button>
                </div>
                <div className="p-6 grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                  {employees.filter(e => e.sector === 'Supervisão' || e.sector === 'Liderança').map(emp => (
                    <button key={emp.id} onClick={() => { setSelectedEmployee(emp); setIsEmployeeModalOpen(true); }} className="flex items-center justify-between bg-slate-50 p-4 rounded-2xl border border-slate-100 hover:border-indigo-200 transition-all text-left">
                      <div><p className="text-xs font-black text-slate-800">{emp.name}</p><p className="text-[9px] font-bold text-slate-400 uppercase">{emp.role}</p></div>
                      <span className={`px-2 py-0.5 rounded text-[8px] font-black uppercase ${emp.status === 'Ativo' ? 'bg-emerald-100 text-emerald-600' : 'bg-orange-100 text-orange-600'}`}>{emp.status}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="bg-white rounded-[2rem] shadow-sm border border-slate-100 overflow-hidden">
                <div className="bg-slate-800 p-6 flex items-center justify-between text-white">
                  <div><h3 className="text-lg font-black uppercase tracking-tight">Produção - Extrusão</h3><p className="text-[10px] opacity-70 font-bold uppercase">Cast 1 & Cast 2</p></div>
                  <button onClick={() => setIsEmployeeModalOpen(true)} className="bg-white/20 p-2.5 rounded-xl hover:bg-white/30 transition-all"><Plus size={20} /></button>
                </div>
                <div className="p-6">
                  {/* Visualização simplificada da lista de produção */}
                  <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                    {['Diurno 1', 'Noturno 1', 'Diurno 2', 'Noturno 2'].map(shiftName => (
                      <div key={shiftName} className="space-y-3">
                        <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-2">{shiftName}</h4>
                        {employees.filter(e => e.shift === shiftName && (e.machine === 'Cast 1' || e.machine === 'Cast 2')).map(emp => (
                          <div key={emp.id} onClick={() => { setSelectedEmployee(emp); setIsEmployeeModalOpen(true); }} className="bg-slate-50 p-3 rounded-xl border border-slate-100 flex items-center justify-between cursor-pointer hover:bg-white hover:shadow-sm transition-all">
                            <div><p className="text-[10px] font-black text-slate-700">{emp.name}</p><p className="text-[8px] font-bold text-slate-400 uppercase">{emp.machine} - {emp.role}</p></div>
                            <ChevronRight size={14} className="text-slate-300" />
                          </div>
                        ))}
                      </div>
                    ))}
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </main>

      <input type="file" ref={fileInputRef} onChange={handleImport} accept=".json" className="hidden" />

      {/* Modais Restaurados */}
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={handleSaveEntry} operators={operators} activeMachines={activeMachines} availableShifts={shifts} initialData={editingEntry} />
      <ShiftModal isOpen={isShiftModalOpen} onClose={() => setIsShiftModalOpen(false)} onSave={s => setShifts(prev => [...prev, { ...s, id: Math.random().toString(36).substr(2, 9) }])} />
      <OperatorModal isOpen={isOperatorModalOpen} onClose={() => setIsOperatorModalOpen(false)} operators={operators} onUpdate={setOperators} />
      <RoleModal isOpen={isRoleModalOpen} onClose={() => setIsRoleModalOpen(false)} roles={jobRoles} onUpdate={setJobRoles} />
      <HistoryModal isOpen={isHistoryModalOpen} onClose={() => setIsHistoryModalOpen(false)} logs={personnelLogs} />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => { setIsEmployeeModalOpen(false); setSelectedEmployee(null); }} onSave={handleEmployeeAction} availableShifts={shifts} availableMachines={activeMachines} availableRoles={jobRoles} initialData={selectedEmployee} />

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/40" onClick={() => setIsMenuOpen(false)}>
            <div className="w-80 bg-white h-full shadow-2xl p-6 animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-8"><h2 className="text-xl font-black uppercase text-slate-800">Opções</h2><button onClick={() => setIsMenuOpen(false)}><X size={24} /></button></div>
                <div className="space-y-6">
                    <div><label className="text-[10px] font-black text-slate-400 mb-2 block uppercase tracking-widest">Meta Mensal (KG)</label><input type="number" value={goalValue} onChange={e => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold" /></div>
                    <div><label className="text-[10px] font-black text-slate-400 mb-2 block uppercase tracking-widest">Mês do Painel</label><input type="month" value={dashboardMonth} onChange={e => setDashboardMonth(e.target.value)} className="w-full bg-slate-50 border rounded-xl px-4 py-3 font-bold" /></div>

                    <div className="pt-6 border-t space-y-2">
                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest mb-2">Gestão de Listas</p>
                      <button onClick={() => setIsOperatorModalOpen(true)} className="w-full py-3 bg-slate-50 text-slate-700 rounded-xl font-bold text-xs uppercase flex items-center justify-between px-4 hover:bg-slate-100"><span className="flex items-center gap-2"><Users size={14}/> Operadores</span> <ChevronRight size={14}/></button>
                      <button onClick={() => setIsShiftModalOpen(true)} className="w-full py-3 bg-slate-50 text-slate-700 rounded-xl font-bold text-xs uppercase flex items-center justify-between px-4 hover:bg-slate-100"><span className="flex items-center gap-2"><Clock size={14}/> Turnos</span> <ChevronRight size={14}/></button>
                      <button onClick={() => setIsRoleModalOpen(true)} className="w-full py-3 bg-slate-50 text-slate-700 rounded-xl font-bold text-xs uppercase flex items-center justify-between px-4 hover:bg-slate-100"><span className="flex items-center gap-2"><Briefcase size={14}/> Funções</span> <ChevronRight size={14}/></button>
                    </div>

                    <div className="pt-6 border-t space-y-3">
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-blue-50 text-blue-600 rounded-2xl font-black text-[10px] uppercase flex items-center justify-center gap-2 transition-all hover:bg-blue-100"><Upload size={14}/> Carregar Backup</button>
                        <button onClick={() => { if(confirm('Resetar sistema?')) {localStorage.clear(); window.location.reload();}}} className="w-full py-4 bg-red-50 text-red-600 rounded-2xl font-black text-[10px] uppercase flex items-center justify-center gap-2 transition-all hover:bg-red-100"><RotateCcw size={14}/> Limpar Tudo</button>
                        <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full py-4 bg-slate-800 text-white rounded-2xl font-black text-[10px] uppercase flex items-center justify-center gap-2 transition-all hover:bg-slate-900"><LogOut size={14}/> Sair</button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, Settings, BarChart3, FileText, Search, 
  ShieldCheck, Download, Upload, Trash2, Cpu, 
  Save, X, Edit2, LogOut, Target, ChevronRight, RotateCcw, Clock, FileDown, Users, HardHat, Factory, Briefcase, History, Plane
} from 'lucide-react';
import { 
  Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend
} from 'recharts';
import { ProductionEntry, Shift, Employee, PersonnelLog } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';
import ShiftModal from './components/ShiftModal';
import OperatorModal from './components/OperatorModal';
import EmployeeModal from './components/EmployeeModal';
import HistoryModal from './components/HistoryModal';
import RoleModal from './components/RoleModal';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];

const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.03) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.2;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);

  return (
    <text x={x} y={y} fill="#64748b" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" className="text-[11px] font-black">
      {`${(percent * 100).toFixed(1)}%`}
    </text>
  );
};

interface OperatorStat {
  name: string;
  prod: number;
  ecoA: number;
  ecoBP: number;
  ecoBM: number;
  borra: number;
  p_manut: number;
  p_proc: number;
  p_outros: number;
}

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>(() => {
    return (localStorage.getItem('manupackaging_active_tab') as 'dashboard' | 'reports' | 'personnel') || 'dashboard';
  });

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    try {
      const saved = localStorage.getItem('manupackaging_data');
      return saved ? JSON.parse(saved) : INITIAL_DATA;
    } catch (e) { return INITIAL_DATA; }
  });

  const [goalValue, setGoalValue] = useState<number>(() => {
    const saved = localStorage.getItem('manupackaging_goal');
    return saved ? parseFloat(saved) : DEFAULT_GOAL;
  });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const savedMonth = localStorage.getItem('manupackaging_dashboard_month');
    return savedMonth || new Date().toISOString().slice(0, 7);
  });

  const [operators, setOperators] = useState<string[]>(() => {
    const saved = localStorage.getItem('manupackaging_operators');
    return saved ? JSON.parse(saved) : DEFAULT_OPERATORS;
  });

  const [shifts, setShifts] = useState<Shift[]>(() => {
    const saved = localStorage.getItem('manupackaging_shifts');
    return saved ? JSON.parse(saved) : [
      { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
      { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
      { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
      { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' }
    ];
  });

  const [employees, setEmployees] = useState<Employee[]>(() => {
    const saved = localStorage.getItem('manupackaging_employees');
    return saved ? JSON.parse(saved) : [];
  });

  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>(() => {
    const saved = localStorage.getItem('manupackaging_personnel_logs');
    return saved ? JSON.parse(saved) : [];
  });

  const [jobRoles, setJobRoles] = useState<string[]>(['Gerente', 'Supervisor', 'Líder', 'Operador 1', 'Operador 2', 'Operador 3', 'Auxiliar']);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);
  const [isOperatorModalOpen, setIsOperatorModalOpen] = useState(false);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);

  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedIds, setSelectedIds] = useState<string[]>([]);

  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);
  useEffect(() => { localStorage.setItem('manupackaging_active_tab', activeTab); }, [activeTab]);
  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_personnel_logs', JSON.stringify(personnelLogs)); }, [personnelLogs]);
  useEffect(() => { localStorage.setItem('manupackaging_shifts', JSON.stringify(shifts)); }, [shifts]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);

  const activeMachines = ['Cast 1', 'Cast 2', 'Erema 1', 'Ghezzi', 'Lintech', 'Wutec', 'Supervisão'];

  const formatWeight = (val: number) => {
    if (isNaN(val)) return '0 KG';
    if (val >= 1000) return (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
    return val.toLocaleString('pt-BR') + ' KG';
  };

  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const handleImport = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const raw = JSON.parse(event.target?.result as string);
        const data = Array.isArray(raw) ? { productionData: raw } : raw;
        if (data.productionData) {
            const normalized = data.productionData.map((item: any) => ({
                ...item,
                date: item.date && item.date.includes('/') ? item.date.split('/').reverse().join('-') : item.date
            }));
            setProductionData(normalized);
            const sortedDates = normalized.map((i: any) => i.date).filter(Boolean).sort();
            if (sortedDates.length > 0) {
                setDashboardMonth(sortedDates[sortedDates.length - 1].slice(0, 7));
            }
        }
        if (data.employees) setEmployees(data.employees);
        if (data.goalValue) setGoalValue(Number(data.goalValue));
        if (data.operators) setOperators(data.operators);
        if (data.shifts) setShifts(data.shifts);
        alert('Backup restaurado com sucesso! O painel foi sincronizado.');
        setIsMenuOpen(false);
      } catch (err) { alert('Erro ao processar backup.'); }
    };
    reader.readAsText(file);
  };

  const handleExportCSV = () => {
    const headers = ['Data', 'Turno', 'Máquina', 'Operador', 'Peso Líquido', 'Eco A', 'Borra', 'Paradas (min)'];
    const rows = filteredReports.map(e => [
      e.date.split('-').reverse().join('/'), e.shift, e.machine, e.operator, e.netWeight, e.ecoA, e.borraTotal, (e.manutencaoMin + e.processoMin + e.outrosMin)
    ].join(';'));
    const csvContent = "\uFEFF" + [headers.join(';'), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = `relatorio_producao_${dashboardMonth}.csv`;
    link.click();
  };

  const handleBulkDelete = () => {
    if (window.confirm(`Excluir permanentemente ${selectedIds.length} registros selecionados?`)) {
      setProductionData(prev => prev.filter(e => !selectedIds.includes(e.id)));
      setSelectedIds([]);
    }
  };

  const totals = useMemo(() => {
    const now = new Date();
    const yesterdayStr = new Date(Date.now() - 86400000).toLocaleDateString('sv-SE');
    const results = { month: 0, eremaMonth: 0, yesterday: 0, projection: 0, remaining: 0, dailyRequired: 0 };
    const [year, month] = dashboardMonth.split('-').map(Number);
    const daysInMonth = new Date(year, month, 0).getDate();
    const isCurrentMonth = now.getFullYear() === year && (now.getMonth() + 1) === month;
    const refDay = isCurrentMonth ? now.getDate() : daysInMonth;

    productionData.forEach(e => {
      if (e.date.startsWith(dashboardMonth)) {
        if (e.machine.toLowerCase().includes('erema')) results.eremaMonth += (e.netWeight || 0);
        else results.month += (e.netWeight || 0);
      }
      if (e.date === yesterdayStr) results.yesterday += (e.netWeight || 0);
    });

    results.projection = refDay > 0 ? (results.month / refDay) * daysInMonth : 0;
    results.remaining = Math.max(0, goalValue - results.month);
    const daysLeft = Math.max(0, daysInMonth - refDay);
    results.dailyRequired = daysLeft > 0 ? results.remaining / daysLeft : results.remaining;
    return results;
  }, [productionData, dashboardMonth, goalValue]);

  const stats = useMemo(() => {
    const is: Record<string, OperatorStat> = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 });
    productionData.filter(e => e.date.startsWith(dashboardMonth)).forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, borra: 0, p_manut: 0, p_proc: 0, p_outros: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0);
      is[e.operator].borra += (e.borraTotal || 0);
      is[e.operator].p_manut += (e.manutencaoMin || 0);
      is[e.operator].p_proc += (e.processoMin || 0);
      is[e.operator].p_outros += (e.outrosMin || 0);
      is[e.operator].ecoBP += (e.ecoBP || 0);
      is[e.operator].ecoBM += (e.ecoBM || 0);
    });
    return Object.values(is);
  }, [productionData, dashboardMonth, operators]);

  const filteredReports = useMemo(() => {
    return productionData.filter(e => {
      const ms = searchTerm ? Object.values(e).some(v => String(v).toLowerCase().includes(searchTerm.toLowerCase())) : true;
      const mm = e.date.startsWith(dashboardMonth);
      return ms && mm;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [productionData, searchTerm, dashboardMonth]);

  const reportTotals = useMemo(() => {
    return filteredReports.reduce((acc, item) => ({
      net: acc.net + (item.netWeight || 0),
      ecoA: acc.ecoA + (item.ecoA || 0),
      borra: acc.borra + (item.borraTotal || 0),
      paradas: acc.paradas + (item.manutencaoMin + item.processoMin + item.outrosMin),
    }), { net: 0, ecoA: 0, borra: 0, paradas: 0 });
  }, [filteredReports]);

  const handleSaveEntry = (entry: any) => {
    if (entry.id) setProductionData(prev => prev.map(e => e.id === entry.id ? { ...e, ...entry } : e));
    else setProductionData(prev => [{ ...entry, id: Math.random().toString(36).substr(2, 9) }, ...prev]);
  };

  const handleEmployeeAction = (data: Partial<Employee>, action: string, details?: string) => {
    const timestamp = new Date().toISOString();
    if (action === 'Exclusão') {
      setEmployees(prev => prev.filter(e => e.id !== data.id));
    } else if (data.id) {
      setEmployees(prev => prev.map(e => e.id === data.id ? { ...e, ...data, updatedAt: timestamp } : e));
    } else {
      setEmployees(prev => [...prev, { ...data, id: Math.random().toString(36).substr(2, 9), updatedAt: timestamp } as Employee]);
    }
    setPersonnelLogs(prev => [{ id: Math.random().toString(36).substr(2, 9), date: timestamp, employeeName: data.name || 'Desconhecido', action: action as any, details: details || '', user: 'Admin' }, ...prev]);
  };

  const chartConfigs = [
    { title: 'Produção Líquida', key: 'prod', formatter: formatWeight },
    { title: 'Eficiência Eco A', key: 'ecoA', formatter: formatWeight },
    { title: 'Resíduo Borra', key: 'borra', formatter: formatWeight },
    { title: 'Recuperado Eco B', key: 'ecoB', formatter: formatWeight },
    { title: 'Tempo Parada', key: 'stops', formatter: formatMinutes },
  ];

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md shadow-2xl space-y-6 text-center">
        <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto shadow-lg mb-4"><ShieldCheck size={32} /></div>
        <h1 className="text-2xl font-black text-slate-800 tracking-tight uppercase">Manupackaging</h1>
        <p className="text-slate-400 text-xs font-bold uppercase tracking-widest">Painel Administrativo</p>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 hover:bg-blue-700 text-white font-black py-4 rounded-2xl shadow-xl transition-all">Acessar Sistema</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-24">
      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-lg font-black text-slate-800 tracking-tighter uppercase">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-2.5 rounded-xl shadow-lg hover:bg-blue-700 transition-all"><Plus size={24} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl transition-all"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-6xl mx-auto px-4 mt-6 no-print">
        <div className="flex items-center p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm overflow-x-auto no-scrollbar">
          <button onClick={() => setActiveTab('dashboard')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}><BarChart3 size={16} className="inline mr-2" /> Indicadores</button>
          <button onClick={() => setActiveTab('reports')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}><FileText size={16} className="inline mr-2" /> Relatórios</button>
          <button onClick={() => setActiveTab('personnel')} className={`px-6 py-2.5 rounded-xl text-[11px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}><Users size={16} className="inline mr-2" /> Gestão de Pessoal</button>
