                     <div className="bg-white/10 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Projeção</p><p className="text-sm font-bold">{formatWeight(totals.projection)}</p></div>
                     <div className="bg-emerald-500/20 rounded-xl p-3 backdrop-blur-sm"><p className="text-[9px] font-bold uppercase opacity-70 mb-1">Total Erema</p><p className="text-sm font-bold">{formatWeight(totals.eremaMonth)}</p></div>
                 </div>
            </div>

            {/* Gráficos em Grid */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {/* Comparações Globais (Novos Gráficos de Eficiência) */}
