                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1 flex items-center gap-1.5"><Factory size={12}/> Erema Mensal</p>
                            <p className="text-2xl md:text-3xl font-black text-emerald-600">{formatWeight(totals.eremaMonth)}</p>
                        </div>
                        <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center group-hover:bg-emerald-600 group-hover:text-white transition-all"><RotateCcw size={24} /></div>
                    </div>
                </div>
            </div>

            {/* Gráficos em Grid Analítico - Comparação por Operador PRIMEIRO */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">

              {/* Gráficos de Operadores (Pie Charts) - ORDEM SOLICITADA COM LEGENDAS RESTAURADAS */}
              {operatorChartConfigs.map((config, idx) => {
                const data = stats.map(s => {
                  let value = 0;
                  if (config.key === 'prod') value = s.prod;
                  else if (config.key === 'ecoA') value = s.ecoA;
                  else if (config.key === 'ecoB') value = s.ecoBP + s.ecoBM;
                  else if (config.key === 'borra') value = s.borra;
                  else if (config.key === 'manut') value = s.p_manut;
                  else if (config.key === 'proc') value = s.p_proc;
                  else if (config.key === 'stops') value = s.p_manut + s.p_proc + s.p_outros;
                  return { name: s.name, value };
                }).filter(i => i.value > 0).sort((a, b) => b.value - a.value);

                if (data.length === 0) return null;

                return (
                  <div key={idx} className="bg-white p-6 rounded-2xl md:rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[480px] hover:border-blue-200 transition-all">
                    <h3 className="text-xs font-black uppercase text-slate-800 mb-4 text-center">{config.title}</h3>
                    <ResponsiveContainer width="100%" height="100%">
                      <PieChart>
                        <Pie data={data} cx="50%" cy="45%" innerRadius={60} outerRadius={80} paddingAngle={4} dataKey="value" label={renderCustomizedLabel}>
                          {data.map((_, i) => <Cell key={`cell-${i}`} fill={COLORS[i % COLORS.length]} stroke="none" />)}
                        </Pie>
                        <Tooltip formatter={(v: number) => config.type === 'weight' ? formatWeight(v) : formatMinutes(v)} />
                        <Legend 
                            iconType="circle" 
                            layout="vertical"
                            align="center"
                            verticalAlign="bottom"
                            formatter={(value, entry: any) => {
                                const val = entry.payload.value;
                                const formattedVal = config.type === 'weight' ? formatWeightTonOnly(val) : formatMinutes(val);
                                return <span className="text-[10px] font-black text-slate-800 uppercase ml-2">{value} — {formattedVal}</span>;
                            }}
                            wrapperStyle={{paddingTop: '20px'}} 
                        />
                      </PieChart>
                    </ResponsiveContainer>
                  </div>
                );
              })}

              {/* Gráficos Globais e de Maquinário APÓS os Operadores */}

              {/* Operação vs Parada (Tempo) */}
              <div className="bg-white p-6 rounded-2xl md:rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[480px] hover:border-blue-200 transition-all">
                <h3 className="text-xs font-black uppercase text-slate-800 mb-4 text-center">Operação vs Parada (Tempo Global)</h3>
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={[
                        { name: 'Operação', value: Math.max(0, totals.totalActiveMinutes - totals.totalStops) },
                        { name: 'Parado', value: totals.totalStops }
                      ]} cx="50%" cy="45%" innerRadius={70} outerRadius={90} paddingAngle={5} dataKey="value" label={renderCustomizedLabel}>
                      <Cell fill="#10b981" stroke="none" />
                      <Cell fill="#ef4444" stroke="none" />
                    </Pie>
                    <Tooltip formatter={(v: number) => formatMinutes(v)} />
                    <Legend 
                        iconType="circle" 
                        layout="vertical"
                        align="center"
                        verticalAlign="bottom"
                        formatter={(value, entry: any) => {
                            const val = entry.payload.value;
                            return <span className="text-[10px] font-black text-slate-800 uppercase ml-2">{value} — {formatMinutes(val)}</span>;
                        }}
                        wrapperStyle={{paddingTop: '20px'}} 
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>

              {/* Produção vs Eco B (Comparativo) */}
              <div className="bg-white p-6 rounded-2xl md:rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[480px] hover:border-blue-200 transition-all">
                <h3 className="text-xs font-black uppercase text-slate-800 mb-4 text-center">Produção vs Eco B (Kg Global)</h3>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={[{ name: 'Comparativo', prod: totals.month, ecob: totals.totalEcoB }]}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" hide />
                    <YAxis tickFormatter={(v) => `${(v/1000).toFixed(0)}T`} tick={{fontSize: 9, fontWeight: 'bold'}} />
                    <Tooltip formatter={(v: number) => formatWeight(v)} />
                    <Legend 
                        formatter={(value) => <span className="text-[10px] font-black text-slate-800 uppercase">{value === 'prod' ? 'Líquido' : 'Eco B'}</span>}
                    />
                    <Bar name="Líquido" dataKey="prod" fill="#3b82f6" radius={[6, 6, 0, 0]} />
                    <Bar name="Eco B" dataKey="ecob" fill="#f59e0b" radius={[6, 6, 0, 0]} />
                  </BarChart>
                </ResponsiveContainer>
              </div>

              {/* Produção vs Borra (Comparativo) */}
              <div className="bg-white p-6 rounded-2xl md:rounded-[2rem] border border-slate-100 shadow-sm flex flex-col h-[480px] hover:border-blue-200 transition-all">
                <h3 className="text-xs font-black uppercase text-slate-800 mb-4 text-center">Produção vs Borra (Kg Global)</h3>
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={[{ name: 'Comparativo', prod: totals.month, borra: totals.totalBorra }]}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                    <XAxis dataKey="name" hide />
                    <YAxis tickFormatter={(v) => `${(v/1000).toFixed(0)}T`} tick={{fontSize: 9, fontWeight: 'bold'}} />
                    <Tooltip formatter={(v: number) => formatWeight(v)} />
                    <Legend 
                        formatter={(value) => <span className="text-[10px] font-black text-slate-800 uppercase">{value === 'prod' ? 'Líquido' : 'Borra'}</span>}
                    />
                    <Bar name="Líquido" dataKey="prod" fill="#3b82f6" radius={[6, 6, 0, 0]} />
