  const formatWeight = (val: number) => val >= 1000 ? (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T' : val.toLocaleString('pt-BR') + ' KG';
  const formatWeightTon = (val: number) => (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const totals = useMemo(() => {
