                            <div className="grid grid-cols-2 gap-3">
                                {['Diurno 1', 'Diurno 2'].map(sh => (
                                    <div key={sh} className="space-y-2">
                                        <p className="text-[8px] font-black text-slate-400 uppercase">{sh}</p>
                                        {renderSlot('Fita', 'Lintech', sh, 'Operador 1', 'OPE1', 'bg-blue-100 text-blue-600')}
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                    <div className="bg-white border border-orange-100 rounded-2xl p-4">
                        <h3 className="text-[10px] font-black text-orange-800 uppercase mb-3 flex items-center gap-2"><div className="w-2 h-2 rounded-full bg-orange-500"/> Wutec</h3>
                        <div className="grid grid-cols-2 gap-4">
                            {renderSlot('Fita', 'Wutec', 'Comercial', 'Auxiliar 1', 'AUX1', 'bg-orange-100 text-orange-600')}
                            {renderSlot('Fita', 'Wutec', 'Comercial', 'Auxiliar 2', 'AUX2', 'bg-orange-100 text-orange-600')}
