                <div className="flex justify-between items-center mb-8"><h2 className="text-lg font-black uppercase text-slate-800">Definições</h2><button onClick={() => setIsMenuOpen(false)}><X size={24} /></button></div>
                <div className="space-y-6">
                    <div><label className="text-[10px] font-black text-slate-400 mb-2 block uppercase tracking-widest">Meta Produção (KG)</label><input type="number" value={goalValue} onChange={e => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm" /></div>
                    <div><label className="text-[10px] font-black text-slate-400 mb-2 block uppercase tracking-widest">Mês Referência</label><input type="month" value={dashboardMonth} onChange={e => setDashboardMonth(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 font-bold text-sm" /></div>
                    <div className="pt-6 border-t space-y-3">
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-3.5 bg-blue-50 text-blue-600 rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2 hover:bg-blue-100 transition-all border border-blue-100"><Upload size={14}/> Backup</button>
                        <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full py-3.5 bg-slate-800 text-white rounded-xl font-black text-[10px] uppercase flex items-center justify-center gap-2 hover:bg-slate-900 transition-all"><LogOut size={14}/> Sair</button>
                    </div>
                </div>
            </div>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={(e) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                const data = JSON.parse(ev.target?.result as string);
                if (data.productionData) setProductionData(data.productionData);
                if (data.employees) setEmployees(data.employees);
            };
            reader.readAsText(file);
        }
      }} accept=".json" className="hidden" />
      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={(e) => setProductionData(p => [{...e, id: Math.random().toString(36).substr(2, 9)} as any, ...p])} operators={operators} activeMachines={activeMachines} availableShifts={[]} initialData={editingEntry} />
      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => { setIsEmployeeModalOpen(false); setSelectedEmployee(null); setSelectedSlot(null); }} onSave={(data, action, details) => {
          const now = new Date().toISOString();
          if (action === 'Contratação') setEmployees(prev => [...prev, {...data, id: Math.random().toString(36).substr(2, 9), updatedAt: now} as Employee]);
          else setEmployees(prev => prev.map(e => e.id === data.id ? {...e, ...data, updatedAt: now} : e));
          setPersonnelLogs(prev => [{id: Math.random().toString(36).substr(2, 9), date: now, employeeName: data.name || '', action: action as any, details, user: 'Admin'}, ...prev]);
      }} availableShifts={[]} availableMachines={activeMachines} availableRoles={['Operador 1', 'Operador 2', 'Auxiliar 1', 'Auxiliar 2', 'Líder', 'Supervisor']} initialData={selectedEmployee} slotInfo={selectedSlot} />
      <HistoryModal isOpen={isHistoryModalOpen} onClose={() => setIsHistoryModalOpen(false)} logs={personnelLogs} />
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, Settings, BarChart3, FileText, Search, 
  ShieldCheck, Download, Upload, Trash2, Cpu, 
  Save, X, Edit2, LogOut, Target, ChevronRight, RotateCcw, Clock, FileDown, Users, HardHat, Factory, Briefcase, History, TrendingUp, Calendar, MapPin
} from 'lucide-react';
import { 
  Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
import { ProductionEntry, Shift, Employee, PersonnelLog } from './types';
import { INITIAL_DATA, GOAL_VALUE as DEFAULT_GOAL, DEFAULT_OPERATORS } from './constants';
import LaunchModal from './components/LaunchModal';
import EmployeeModal from './components/EmployeeModal';
import HistoryModal from './components/HistoryModal';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b'];

const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.05) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.15;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);
  return (
    <text x={x} y={y} fill="#1e293b" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" className="text-[10px] font-black">
      {`${(percent * 100).toFixed(0)}%`}
    </text>
  );
};

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>(() => 
    (localStorage.getItem('manupackaging_active_tab') as any) || 'dashboard'
  );

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const saved = localStorage.getItem('manupackaging_data');
    if (saved) {
        const parsed = JSON.parse(saved);
        return parsed.length > 0 ? parsed : INITIAL_DATA;
    }
    return INITIAL_DATA;
  });

  const [goalValue, setGoalValue] = useState<number>(() => Number(localStorage.getItem('manupackaging_goal')) || DEFAULT_GOAL);
  const [dashboardMonth, setDashboardMonth] = useState(() => localStorage.getItem('manupackaging_dashboard_month') || new Date().toISOString().slice(0, 7));
  const [operators, setOperators] = useState<string[]>(() => JSON.parse(localStorage.getItem('manupackaging_operators') || JSON.stringify(DEFAULT_OPERATORS)));
  const [employees, setEmployees] = useState<Employee[]>(() => JSON.parse(localStorage.getItem('manupackaging_employees') || '[]'));
  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>(() => JSON.parse(localStorage.getItem('manupackaging_personnel_logs') || '[]'));

  // FIX: Define activeMachines and availableShifts to satisfy modal requirements and fix missing variable errors
  const activeMachines = useMemo(() => ["Cast 1", "Cast 2", "Erema 1", "Ghezzi", "Lintech", "Wutec"], []);
  const availableShifts: Shift[] = useMemo(() => [
    { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
    { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
    { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
    { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
    { id: '5', name: 'Comercial', startTime: '08:00', endTime: '18:00', type: 'Diurno' },
  ], []);

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);

  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [selectedSlot, setSelectedSlot] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');

  const fileInputRef = useRef<HTMLInputElement>(null);

  // Persistência
  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_goal', goalValue.toString()); }, [goalValue]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);
  useEffect(() => { localStorage.setItem('manupackaging_active_tab', activeTab); }, [activeTab]);
  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_personnel_logs', JSON.stringify(personnelLogs)); }, [personnelLogs]);

  // CORREÇÃO CRÍTICA: Se o mês estiver vazio, busca o último mês com dados
  useEffect(() => {
    const entriesInMonth = productionData.filter(e => e.date.startsWith(dashboardMonth));
    if (entriesInMonth.length === 0 && productionData.length > 0) {
        const lastEntry = productionData[0]; // Dados vêm invertidos (mais recentes primeiro)
        if (lastEntry && lastEntry.date) {
            setDashboardMonth(lastEntry.date.slice(0, 7));
        }
    }
  }, [productionData, dashboardMonth]);

  const formatWeight = (val: number) => val >= 1000 ? (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T' : val.toLocaleString('pt-BR') + ' KG';
  const formatWeightTon = (val: number) => (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3, maximumFractionDigits: 3 }) + ' T';
  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  const totals = useMemo(() => {
    const res = { month: 0, eremaMonth: 0, yesterday: 0, ecoB: 0, borra: 0, stops: 0, activeMin: 0 };
    const yesterdayStr = new Date(Date.now() - 86400000).toISOString().split('T')[0];

    productionData.forEach(e => {
      if (e.date.startsWith(dashboardMonth)) {
        if (e.machine.toLowerCase().includes('erema')) res.eremaMonth += (e.netWeight || 0);
        else res.month += (e.netWeight || 0);
        res.ecoB += (e.ecoBP || 0) + (e.ecoBM || 0);
        res.borra += (e.borraTotal || 0);
        res.stops += (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0);
        res.activeMin += 720;
      }
      if (e.date === yesterdayStr) res.yesterday += (e.netWeight || 0);
    });
    return res;
  }, [productionData, dashboardMonth]);

  const stats = useMemo(() => {
    const is: any = {};
    operators.forEach(op => is[op] = { name: op, prod: 0, ecoA: 0, ecoB: 0, borra: 0, manut: 0, proc: 0, stops: 0 });
    productionData.filter(e => e.date.startsWith(dashboardMonth)).forEach(e => {
      if (!is[e.operator]) is[e.operator] = { name: e.operator, prod: 0, ecoA: 0, ecoB: 0, borra: 0, manut: 0, proc: 0, stops: 0 };
      if (!e.machine.toLowerCase().includes('erema')) is[e.operator].prod += (e.netWeight || 0);
      is[e.operator].ecoA += (e.ecoA || 0);
      is[e.operator].ecoB += (e.ecoBP || 0) + (e.ecoBM || 0);
      is[e.operator].borra += (e.borraTotal || 0);
      is[e.operator].manut += (e.manutencaoMin || 0);
      is[e.operator].proc += (e.processoMin || 0);
      is[e.operator].stops += (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0);
    });
    return Object.values(is);
  }, [productionData, dashboardMonth, operators]);

  const renderTwoColumnLegend = (props: any, type: 'weight' | 'time') => {
    const { payload } = props;
    return (
      <ul className="grid grid-cols-2 gap-x-2 gap-y-1 mt-4 px-2">
        {payload.map((entry: any, i: number) => (
          <li key={i} className="flex items-center gap-1.5 text-[9px] font-black text-slate-700 uppercase">
            <div className="w-2 h-2 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
            <span className="truncate">{entry.value} — {type === 'weight' ? formatWeightTon(entry.payload.value) : formatMinutes(entry.payload.value)}</span>
          </li>
        ))}
      </ul>
    );
  };

  const findEmployee = (s: string, m: string, sh: string, r: string) => 
    employees.find(e => e.sector === s && e.machine === m && e.shift === sh && e.role === r && e.status === 'Ativo');

  const renderSlot = (sector: string, machine: string, shift: string, role: string, label: string, color: string) => {
    const emp = findEmployee(sector, machine, shift, role);
    return (
      <div onClick={() => { setSelectedEmployee(emp || null); setSelectedSlot(emp ? null : { sector, machine, shift, role }); setIsEmployeeModalOpen(true); }}
           className="flex items-center justify-between p-2 bg-white border border-slate-100 rounded-lg cursor-pointer hover:border-blue-400 transition-all">
        <span className={`text-[10px] font-bold ${emp ? 'text-slate-800' : 'text-red-400 italic'}`}>{emp ? emp.name : '(Adicionar)'}</span>
        <span className={`text-[8px] font-black px-1.5 py-0.5 rounded ${color}`}>{label}</span>
      </div>
    );
  };

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-3xl p-8 w-full max-w-md text-center shadow-2xl">
        <div className="w-16 h-16 bg-blue-600 rounded-2xl flex items-center justify-center text-white mx-auto mb-6 shadow-lg"><ShieldCheck size={32} /></div>
        <h1 className="text-2xl font-black text-slate-800 uppercase mb-8">Manupackaging</h1>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 text-white font-black py-4 rounded-2xl shadow-xl hover:bg-blue-700 transition-all">Acessar Sistema</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <header className="bg-white px-4 py-3 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 shadow-sm">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={20} /></div>
          <h1 className="text-sm md:text-base font-black text-slate-800 uppercase tracking-tighter">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-2.5 rounded-xl shadow-lg hover:bg-blue-700"><Plus size={20} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-2.5 text-slate-400 hover:bg-slate-100 rounded-xl"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 mt-6">
        <div className="flex p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm">
          <button onClick={() => setActiveTab('dashboard')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Indicadores</button>
          <button onClick={() => setActiveTab('reports')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Relatórios</button>
          <button onClick={() => setActiveTab('personnel')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Gestão de Pessoal</button>
        </div>
      </div>

      <main className="max-w-7xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
                <div className="lg:col-span-8 bg-blue-600 text-white p-6 rounded-[2rem] shadow-xl relative overflow-hidden flex flex-col justify-between">
                    <div className="flex justify-between items-start mb-4">
                        <div><p className="text-[10px] font-bold opacity-70 uppercase mb-1">Mês: {dashboardMonth}</p><h2 className="text-2xl font-black uppercase">Performance Global</h2></div>
                        <Target size={32} className="opacity-30" />
                    </div>
                    <div className="flex items-baseline gap-2 mb-4">
                        <span className="text-5xl font-black">{formatWeight(totals.month)}</span>
                        <span className="text-lg font-bold opacity-70">/ {((totals.month/goalValue)*100).toFixed(1)}%</span>
                    </div>
                    <div className="w-full bg-black/20 h-3 rounded-full mb-6 overflow-hidden">
                        <div className="bg-white h-full rounded-full transition-all duration-1000" style={{ width: `${Math.min((totals.month/goalValue)*100, 100)}%` }}></div>
                    </div>
                    <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                        <div className="bg-white/10 p-3 rounded-xl"><p className="text-[9px] font-bold opacity-60 uppercase mb-1">Objetivo</p><p className="text-sm font-bold">{formatWeight(goalValue)}</p></div>
                        <div className="bg-white/10 p-3 rounded-xl"><p className="text-[9px] font-bold opacity-60 uppercase mb-1">Produção Ontem</p><p className="text-sm font-bold">{formatWeight(totals.yesterday)}</p></div>
                        <div className="bg-white/10 p-3 rounded-xl"><p className="text-[9px] font-bold opacity-60 uppercase mb-1">Erema Mensal</p><p className="text-sm font-bold">{formatWeight(totals.eremaMonth)}</p></div>
                        <div className="bg-white/10 p-3 rounded-xl"><p className="text-[9px] font-bold opacity-60 uppercase mb-1">Perda Eco B</p><p className="text-sm font-bold">{formatWeight(totals.ecoB)}</p></div>
                    </div>
                </div>
                <div className="lg:col-span-4 grid grid-cols-1 gap-4">
                    <div className="bg-white p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between shadow-sm">
                        <div><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Total Paradas</p><p className="text-3xl font-black text-slate-800">{formatMinutes(totals.stops)}</p></div>
                        <div className="w-12 h-12 bg-red-50 text-red-600 rounded-2xl flex items-center justify-center"><Clock size={24}/></div>
                    </div>
                    <div className="bg-white p-6 rounded-[2rem] border border-slate-100 flex items-center justify-between shadow-sm">
                        <div><p className="text-[10px] font-black text-slate-400 uppercase mb-1">Eficiência Tempo</p><p className="text-3xl font-black text-emerald-600">{(((totals.activeMin - totals.stops)/totals.activeMin)*100).toFixed(1)}%</p></div>
                        <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center"><TrendingUp size={24}/></div>
                    </div>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
                {[
                  { title: 'Produção Líquida por Operador', key: 'prod', type: 'weight' },
                  { title: 'Tempo Parada por Operador', key: 'stops', type: 'time' },
                  { title: 'Eco B por Operador', key: 'ecoB', type: 'weight' },
                  { title: 'Borra por Operador', key: 'borra', type: 'weight' },
                  { title: 'Tempo Manutenção por Operador', key: 'manut', type: 'time' },
                  { title: 'Eco A por Operador', key: 'ecoA', type: 'weight' }
                ].map((conf, i) => {
                    const data = stats.map((s: any) => ({ name: s.name, value: s[conf.key] })).filter(d => d.value > 0).sort((a,b) => b.value - a.value);
                    if (data.length === 0) return null;
                    return (
                        <div key={i} className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm h-[520px] flex flex-col">
                            <h3 className="text-[10px] font-black text-center uppercase text-slate-800 mb-6">{conf.title}</h3>
                            <ResponsiveContainer width="100%" height="100%">
                                <PieChart>
                                    <Pie data={data} cx="50%" cy="35%" innerRadius={60} outerRadius={80} paddingAngle={4} dataKey="value" label={renderCustomizedLabel}>
                                        {data.map((_, idx) => <Cell key={idx} fill={COLORS[idx % COLORS.length]} />)}
                                    </Pie>
                                    <Tooltip formatter={(v: any) => conf.type === 'weight' ? formatWeight(v) : formatMinutes(v)} />
                                    <Legend content={(p) => renderTwoColumnLegend(p, conf.type as any)} />
                                </PieChart>
                            </ResponsiveContainer>
                        </div>
                    );
                })}
            </div>
          </div>
