  Save, X, Edit2, LogOut, Target, ChevronRight, RotateCcw, Clock, FileDown, Users, HardHat, Factory, Briefcase, History, TrendingUp, Calendar, MapPin, AlertCircle
} from 'lucide-react';
import { 
  Tooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid 
} from 'recharts';
