          <li key={i} className="flex items-center gap-2 text-[9px] font-black text-slate-700 uppercase">
            <div className="w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: entry.color }} />
            <span className="truncate">{entry.value} — {formatWeight(entry.payload.value)}</span>
          </li>
        ))}
      </ul>
    );
  };

  const findEmployee = (s: string, m: string, sh: string, r: string) => 
    employees.find(e => e.sector === s && e.machine === m && e.shift === sh && e.role === r && e.status === 'Ativo');

  const renderSlot = (sector: string, machine: string, shift: string, role: string, label: string, color: string) => {
    const emp = findEmployee(sector, machine, shift, role);
    return (
      <div onClick={() => { setSelectedEmployee(emp || null); setSelectedSlot(emp ? null : { sector, machine, shift, role }); setIsEmployeeModalOpen(true); }}
           className="flex items-center justify-between p-2.5 bg-white border border-slate-100 rounded-xl cursor-pointer hover:border-blue-400 transition-all shadow-sm">
        <span className={`text-[10px] font-bold truncate max-w-[100px] ${emp ? 'text-slate-800' : 'text-red-400 italic'}`}>{emp ? emp.name : '(Adicionar)'}</span>
        <span className={`text-[8px] font-black px-1.5 py-0.5 rounded-md shrink-0 ${color}`}>{label}</span>
      </div>
    );
  };

  if (!isAuthenticated) return (
    <div className="min-h-screen bg-slate-900 flex items-center justify-center p-4">
      <div className="bg-white rounded-[2.5rem] p-10 w-full max-w-md text-center shadow-2xl">
        <div className="w-20 h-20 bg-blue-600 rounded-3xl flex items-center justify-center text-white mx-auto mb-8 shadow-xl"><ShieldCheck size={40} /></div>
        <h1 className="text-3xl font-black text-slate-800 uppercase tracking-tighter mb-10">Manupackaging</h1>
        <button onClick={() => { localStorage.setItem('manupackaging_session', 'true'); setIsAuthenticated(true); }} className="w-full bg-blue-600 text-white font-black py-5 rounded-2xl shadow-xl hover:bg-blue-700 transition-all">Acessar Sistema</button>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <header className="bg-white px-4 py-4 flex items-center justify-between sticky top-0 z-40 border-b border-slate-100 shadow-sm no-print">
        <div className="flex items-center gap-3">
          <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-lg"><Cpu size={22} /></div>
          <h1 className="text-base font-black text-slate-800 uppercase tracking-tighter">Controle de Produção</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => { setEditingEntry(null); setIsModalOpen(true); }} className="bg-blue-600 text-white p-3 rounded-xl shadow-lg hover:bg-blue-700 active:scale-90 transition-all"><Plus size={20} /></button>
          <button onClick={() => setIsMenuOpen(true)} className="p-3 text-slate-400 hover:bg-slate-100 rounded-xl transition-all"><Settings size={20} /></button>
        </div>
      </header>

      <div className="max-w-7xl mx-auto px-4 mt-6 no-print">
        <div className="flex p-1 bg-white border border-slate-100 rounded-2xl w-fit shadow-sm overflow-x-auto no-scrollbar">
          <button onClick={() => setActiveTab('dashboard')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'dashboard' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Indicadores</button>
          <button onClick={() => setActiveTab('reports')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'reports' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Relatórios</button>
          <button onClick={() => setActiveTab('personnel')} className={`px-6 py-2.5 rounded-xl text-[10px] font-black uppercase transition-all whitespace-nowrap ${activeTab === 'personnel' ? 'bg-slate-100 text-blue-600' : 'text-slate-400'}`}>Gestão de Pessoal</button>
        </div>
      </div>

      <main className="max-w-7xl mx-auto p-4 space-y-6">
        {activeTab === 'dashboard' && (
          <div className="space-y-6 animate-in fade-in duration-300">
            {/* CARD META MENSAL (CONFORME O PRINT) */}
