          </div>
        )}
      </main>

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/40 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}>
            <div className="w-[85%] sm:w-80 bg-white h-full shadow-2xl p-8 animate-in slide-in-from-right duration-300" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-10"><h2 className="text-xl font-black uppercase text-slate-800">Definições</h2><button onClick={() => setIsMenuOpen(false)}><X size={28} className="text-slate-400" /></button></div>
                <div className="space-y-8">
                    <div><label className="text-[10px] font-black text-slate-400 mb-2.5 block uppercase tracking-widest">Meta Produção (KG)</label><input type="number" value={goalValue} onChange={e => setGoalValue(Number(e.target.value))} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 font-bold text-sm" /></div>
                    <div><label className="text-[10px] font-black text-slate-400 mb-2.5 block uppercase tracking-widest">Mês Referência</label><input type="month" value={dashboardMonth} onChange={e => setDashboardMonth(e.target.value)} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 font-bold text-sm" /></div>
