              <button className="px-8 py-3.5 bg-emerald-600 text-white rounded-2xl font-black text-[11px] uppercase flex items-center justify-center gap-2 shadow-lg shadow-emerald-100"><FileDown size={18}/> Exportar</button>
            </div>
            <div className="bg-white rounded-[2.5rem] border border-slate-100 shadow-sm overflow-hidden">
                <div className="overflow-x-auto custom-scrollbar">
                    <table className="w-full text-left">
                        <thead className="bg-slate-50 border-b border-slate-100">
                            <tr><th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Data</th><th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Operador / Máquina</th><th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Peso Líquido</th><th className="px-6 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Ações</th></tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50">
                            {productionData
                              .filter(e => e.date.startsWith(dashboardMonth) && (e.operator.toLowerCase().includes(searchTerm.toLowerCase()) || e.machine.toLowerCase().includes(searchTerm.toLowerCase())))
                              .map(entry => (
                                <tr key={entry.id} className="hover:bg-slate-50/50 transition-colors group">
                                    <td className="px-6 py-4"><div className="flex flex-col"><span className="text-xs font-black text-slate-700">{new Date(entry.date).toLocaleDateString('pt-BR')}</span><span className="text-[9px] font-bold text-slate-400 uppercase">{entry.shift}</span></div></td>
                                    <td className="px-6 py-4"><div className="flex flex-col"><span className="text-xs font-bold text-slate-800">{entry.operator}</span><span className="text-[9px] font-black text-blue-500 uppercase">{entry.machine}</span></div></td>
                                    <td className="px-6 py-4"><span className={`text-sm font-black ${entry.netWeight > 0 ? 'text-emerald-600' : 'text-slate-400'}`}>{formatWeight(entry.netWeight)}</span></td>
                                    <td className="px-6 py-4"><div className="flex items-center justify-center gap-2 opacity-0 group-hover:opacity-100 transition-opacity"><button onClick={() => { setEditingEntry(entry); setIsModalOpen(true); }} className="p-2 text-blue-600 hover:bg-blue-50 rounded-lg"><Edit2 size={16}/></button><button onClick={() => setProductionData(p => p.filter(x => x.id !== entry.id))} className="p-2 text-red-600 hover:bg-red-50 rounded-lg"><Trash2 size={16}/></button></div></td>
                                </tr>
                            ))}
                        </tbody>
                    </table>
                </div>
            </div>
          </div>
        )}

        {activeTab === 'personnel' && (
          <div className="space-y-6 animate-in fade-in duration-300">
            <div className="grid grid-cols-2 md:grid-cols-4 gap-5">
                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center group transition-all">
                    <div><p className="text-[10px] font-black text-blue-400 uppercase mb-1">Colaboradores</p><p className="text-3xl font-black text-slate-800">{employees.filter(e => e.status === 'Ativo').length}</p></div>
                    <div className="w-12 h-12 bg-blue-50 text-blue-600 rounded-2xl flex items-center justify-center"><Users size={24}/></div>
                </div>
                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center group transition-all">
                    <div><p className="text-[10px] font-black text-emerald-400 uppercase mb-1">Operadores</p><p className="text-3xl font-black text-slate-800">{employees.filter(e => e.status === 'Ativo' && e.role.includes('Operador')).length}</p></div>
                    <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center"><HardHat size={24}/></div>
                </div>
                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center group transition-all">
                    <div><p className="text-[10px] font-black text-orange-400 uppercase mb-1">Auxiliares</p><p className="text-3xl font-black text-slate-800">{employees.filter(e => e.status === 'Ativo' && e.role.includes('Auxiliar')).length}</p></div>
                    <div className="w-12 h-12 bg-orange-50 text-orange-600 rounded-2xl flex items-center justify-center"><Briefcase size={24}/></div>
                </div>
                <div className="bg-white p-5 rounded-3xl border border-slate-100 shadow-sm flex justify-between items-center group transition-all">
                    <div><p className="text-[10px] font-black text-red-400 uppercase mb-1">Vagas</p><p className="text-3xl font-black text-slate-800">3</p></div>
                    <div className="w-12 h-12 bg-red-50 text-red-600 rounded-2xl flex items-center justify-center"><Target size={24}/></div>
                </div>
            </div>

            <div className="flex justify-end"><button onClick={() => setIsHistoryModalOpen(true)} className="bg-slate-800 text-white px-6 py-3 rounded-2xl text-[11px] font-black uppercase flex items-center gap-2"><History size={18}/> Histórico de RH</button></div>

            {/* Setor: EXTRUSÃO (AZUL) */}
            <div className="bg-[#1e293b] rounded-[2.5rem] overflow-hidden shadow-xl border border-slate-800">
                <div className="p-6 flex items-center gap-5 bg-slate-900 border-b border-slate-800">
                    <div className="w-12 h-12 bg-blue-500/20 rounded-2xl flex items-center justify-center text-blue-400"><Factory size={24}/></div>
                    <div><h2 className="text-lg font-black text-white uppercase">Setor: Extrusão</h2><p className="text-[10px] text-slate-400 font-bold uppercase">Escala de Turnos</p></div>
                </div>
                <div className="p-5 grid grid-cols-1 md:grid-cols-2 gap-5 bg-slate-100/30">
                    {['Diurno 1', 'Noturno 1', 'Diurno 2', 'Noturno 2'].map(sh => (
                        <div key={sh} className="bg-white border border-slate-200 rounded-[2rem] p-6 shadow-sm">
