                                ))}
                            </div>
                        </div>
                        <div className="bg-white border border-orange-100 rounded-3xl p-6 shadow-sm">
                            <h3 className="text-[11px] font-black text-orange-800 uppercase mb-4 flex items-center gap-2 tracking-widest"><div className="w-2.5 h-2.5 rounded-full bg-orange-500"/> Lintech</h3>
                            <div className="grid grid-cols-2 gap-4">
                                {['Diurno 1', 'Diurno 2'].map(sh => (
                                    <div key={sh} className="space-y-2">
                                        <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{sh}</p>
