                <div className="flex items-center gap-2 cursor-pointer"><h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">EREMA MENSAL</h3><ChevronRight size={18} className="text-slate-300" /></div>
                <p className="text-5xl font-black text-slate-800 mt-3">{formatWeight(dashboardStats.eremaMonth)}</p>
                <p className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mt-2">Recuperado este mês</p>
              </div>
              <div className="w-16 h-16 bg-[#ecfdf5] text-[#10b981] rounded-[1.8rem] flex items-center justify-center border border-[#d1fae5] shadow-sm"><RotateCcw size={32}/></div>
