                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Operador</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Máquina</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest">Turno</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">T. Bruto</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Tara</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Peso Líquido</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Volumes</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Tubetes</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Eco A</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Eco B (P)</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">Eco B (M)</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right text-red-500">Borra</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">P. Manut.</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">P. Proc.</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-right">P. Outros</th>
                              <th className="px-4 py-5 text-[10px] font-black text-slate-400 uppercase tracking-widest text-center">Ações</th>
                            </tr>
                        </thead>
                        <tbody className="divide-y divide-slate-50 text-[11px] whitespace-nowrap">
                            {filteredReportsData.map(entry => (
                                <tr key={entry.id} className="hover:bg-slate-50/50 transition-colors group">
                                    <td className="px-4 py-3 font-bold text-slate-700">{entry.date.split('-').reverse().join('/')}</td>
