                                    <td className="px-4 py-3 text-right">{(entry.volumes || 0)}</td>
                                    <td className="px-4 py-3 text-right">{(entry.tubetes || 0)}</td>
                                    <td className="px-4 py-3 text-right">{(entry.ecoA || 0).toLocaleString('pt-BR')}</td>
                                    <td className="px-4 py-3 text-right">{(entry.ecoBP || 0).toLocaleString('pt-BR')}</td>
