              <div className="w-12 h-12 bg-emerald-50 text-emerald-600 rounded-2xl flex items-center justify-center border border-emerald-100"><RotateCcw size={24}/></div>
              <div>
                <h3 className="text-xl font-black text-slate-800 uppercase tracking-tight">Produção Erema por Operador</h3>
                <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Referência: {filterDay || dashboardMonth}</p>
              </div>
            </div>
            <div className="h-[400px]">
              {eremaOperatorStats.length > 0 ? (
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie data={eremaOperatorStats} cx="50%" cy="32%" innerRadius={70} outerRadius={100} paddingAngle={5} dataKey="value" label={renderCustomizedLabel}>
                      {eremaOperatorStats.map((_, idx: number) => <Cell key={idx} fill={COLORS[idx % COLORS.length]} />)}
                    </Pie>
                    <RechartsTooltip formatter={(v: any) => v.toLocaleString('pt-BR') + ' kg'} />
                    <Legend verticalAlign="bottom" content={(props) => renderTwoColumnLegend(props)} />
                  </PieChart>
                </ResponsiveContainer>
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-slate-400 gap-4">
                  <Activity size={48} className="opacity-20" />
                  <p className="font-bold uppercase text-[11px] tracking-widest">Nenhum dado para este filtro</p>
                </div>
              )}
            </div>
            <button onClick={() => setShowEremaChart(false)} className="w-full mt-8 py-4 bg-slate-900 text-white rounded-2xl font-black text-[11px] uppercase tracking-widest shadow-xl hover:bg-black transition-all">Fechar Análise</button>
          </div>
        </div>
      )}

      {isMenuOpen && (
        <div className="fixed inset-0 z-50 flex justify-end bg-black/40 backdrop-blur-sm" onClick={() => setIsMenuOpen(false)}>
            <div className="w-[85%] sm:w-80 bg-white h-full shadow-2xl p-8 animate-in slide-in-from-right duration-300 flex flex-col" onClick={e => e.stopPropagation()}>
                <div className="flex justify-between items-center mb-8"><h2 className="text-xl font-black uppercase text-slate-800 tracking-tight">Filtros & Definições</h2><button onClick={() => setIsMenuOpen(false)}><X size={28} className="text-slate-400 hover:text-slate-800" /></button></div>
                <div className="space-y-6 flex-1 overflow-y-auto no-scrollbar pb-10">

                    <div className="p-4 bg-blue-50/50 rounded-2xl border border-blue-100 space-y-4">
                      <p className="text-[10px] font-black text-blue-400 uppercase tracking-widest ml-1">Filtros de Busca</p>

                      <div>
                        <label className="text-[9px] font-black text-slate-400 mb-1.5 block uppercase tracking-widest">Operador</label>
                        <select 
                          value={filterOperator} 
                          onChange={e => setFilterOperator(e.target.value)} 
                          className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-xs outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500"
                        >
                          <option value="Todos">Todos os Operadores</option>
                          {operators.map(op => <option key={op} value={op}>{op}</option>)}
                        </select>
                      </div>

                      <div>
                        <label className="text-[9px] font-black text-slate-400 mb-1.5 block uppercase tracking-widest">Dia Específico</label>
                        <input 
                          type="date" 
                          value={filterDay} 
                          onChange={e => setFilterDay(e.target.value)} 
                          className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-xs outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500" 
                        />
                        {filterDay && <button onClick={() => setFilterDay('')} className="mt-2 text-[8px] font-black text-blue-600 uppercase hover:underline">Limpar filtro de dia</button>}
                      </div>

                      <div>
                        <label className="text-[9px] font-black text-slate-400 mb-1.5 block uppercase tracking-widest">Mês/Ano Referência</label>
                        <input 
                          type="month" 
                          value={dashboardMonth} 
                          onChange={e => setDashboardMonth(e.target.value)} 
                          className="w-full bg-white border border-slate-200 rounded-xl px-4 py-3 font-bold text-xs outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500" 
                        />
                      </div>
                    </div>

                    <div className="pt-2">
                      <label className="text-[10px] font-black text-slate-400 mb-2.5 block uppercase tracking-widest ml-1">Meta Produção ({dashboardMonth})</label>
                      <input 
                        type="number" 
                        value={goals[dashboardMonth] || GOAL_VALUE} 
                        onChange={e => setGoals(prev => ({...prev, [dashboardMonth]: Number(e.target.value)}))} 
                        className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 font-bold text-sm outline-none focus:ring-2 focus:ring-blue-500/10 focus:border-blue-500" 
                      />
                    </div>

                    <div className="space-y-3 pt-6 border-t border-slate-100">
                        <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest ml-1 mb-2">Configurações Base</p>
                        <button onClick={() => setIsOperatorModalOpen(true)} className="w-full px-5 py-3.5 bg-slate-50 text-slate-700 rounded-2xl font-black text-[11px] uppercase flex items-center gap-3 border border-slate-100 hover:bg-slate-100 transition-all"><Users size={18} className="text-blue-500"/> Gerenciar Operadores</button>
                        <button onClick={() => setIsRoleModalOpen(true)} className="w-full px-5 py-3.5 bg-slate-50 text-slate-700 rounded-2xl font-black text-[11px] uppercase flex items-center gap-3 border border-slate-100 hover:bg-slate-100 transition-all"><Briefcase size={18} className="text-indigo-500"/> Gerenciar Funções</button>
                        <button onClick={() => setIsShiftModalOpen(true)} className="w-full px-5 py-3.5 bg-slate-50 text-slate-700 rounded-2xl font-black text-[11px] uppercase flex items-center gap-3 border border-slate-100 hover:bg-slate-100 transition-all"><Clock size={18} className="text-orange-500"/> Gerenciar Turnos</button>
                    </div>

                    <div className="pt-8 border-t border-slate-100 space-y-4">
                        <button onClick={downloadBackup} className="w-full py-4 bg-emerald-50 text-emerald-600 rounded-2xl font-black text-[11px] uppercase flex items-center justify-center gap-2 border border-emerald-100 hover:bg-emerald-100 transition-all"><FileDown size={18}/> Baixar Backup</button>
                        <button onClick={() => fileInputRef.current?.click()} className="w-full py-4 bg-blue-50 text-blue-600 rounded-2xl font-black text-[11px] uppercase flex items-center justify-center gap-2 border border-blue-100 hover:bg-blue-100 transition-all"><Upload size={18}/> Restaurar Backup</button>
                        <button onClick={() => { localStorage.removeItem('manupackaging_session'); setIsAuthenticated(false); }} className="w-full py-4 bg-slate-800 text-white rounded-2xl font-black text-[11px] uppercase flex items-center justify-center gap-2 shadow-xl hover:bg-slate-900 transition-all"><LogOut size={18}/> Sair</button>
                    </div>
                </div>
            </div>
        </div>
      )}

      <input type="file" ref={fileInputRef} onChange={(e) => {
        const file = e.target.files?.[0];
        if (file) {
            const reader = new FileReader();
            reader.onload = (ev) => {
                try {
                    const data = JSON.parse(ev.target?.result as string);
                    if (data.productionData) setProductionData(data.productionData);
                    if (data.employees) setEmployees(data.employees);
                    if (data.operators) setOperators(data.operators);
                    if (data.availableRoles) setAvailableRoles(data.availableRoles);
                    if (data.availableShifts) setAvailableShifts(data.availableShifts);
                    if (data.goals) setGoals(data.goals);
                    if (data.dashboardMonth) setDashboardMonth(data.dashboardMonth);
                    if (data.personnelLogs) setPersonnelLogs(data.personnelLogs);
                    alert('Backup restaurado com sucesso!');
                } catch (err) {
                    alert('Erro ao processar arquivo de backup.');
                }
            };
            reader.readAsText(file);
        }
      }} accept=".json" className="hidden" />

      <LaunchModal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} onSave={(e) => {
        if(editingEntry) setProductionData(p => p.map(x => x.id === editingEntry.id ? {...e, id: editingEntry.id} as any : x));
        else setProductionData(p => [{...e, id: Math.random().toString(36).substr(2, 9)} as any, ...p]);
        setEditingEntry(null);
      }} operators={operators} activeMachines={activeMachines} availableShifts={availableShifts} initialData={editingEntry} />

      <EmployeeModal isOpen={isEmployeeModalOpen} onClose={() => { setIsEmployeeModalOpen(false); setSelectedEmployee(null); setSelectedSlot(null); }} onSave={(data, action, details) => {
          const now = new Date().toISOString();
          if (action === 'Contratação') setEmployees(prev => [...prev, {...data, id: Math.random().toString(36).substr(2, 9), updatedAt: now} as Employee]);
          else if (action === 'Exclusão') setEmployees(prev => prev.filter(e => e.id !== data.id));
          else setEmployees(prev => prev.map(e => e.id === data.id ? {...e, ...data, updatedAt: now} : e));
          setPersonnelLogs(prev => [{id: Math.random().toString(36).substr(2, 9), date: now, employeeName: data.name || 'Vaga', action: action as any, details: details || '', user: 'Admin'}, ...prev]);
      }} availableShifts={availableShifts} availableMachines={activeMachines} availableRoles={availableRoles} initialData={selectedEmployee} slotInfo={selectedSlot} />

      <OperatorModal isOpen={isOperatorModalOpen} onClose={() => setIsOperatorModalOpen(false)} operators={operators} onUpdate={setOperators} />
      <RoleModal isOpen={isRoleModalOpen} onClose={() => setIsRoleModalOpen(false)} roles={availableRoles} onUpdate={setAvailableRoles} />
      <ShiftModal isOpen={isShiftModalOpen} onClose={() => setIsShiftModalOpen(false)} onSave={(s) => setAvailableShifts(prev => [...prev, {...s, id: Math.random().toString(36).substr(2, 9)}])} />
      <HistoryModal isOpen={isHistoryModalOpen} onClose={() => setIsHistoryModalOpen(false)} logs={personnelLogs} />
    </div>
  );
};

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, Settings, Cpu, ShieldCheck, Target, TrendingUp, Clock, FileDown, 
  Users, HardHat, Factory, Briefcase, History, RotateCcw, X, Edit2, Trash2, 
  LogOut, Search, Activity, Package, ChevronRight, TrendingDown, Upload, Info,
  UserPlus, Download, AlertCircle, FileSpreadsheet
} from 'lucide-react';
import { 
  Tooltip as RechartsTooltip, ResponsiveContainer, Cell, PieChart, Pie, Legend,
  BarChart, Bar, XAxis, YAxis, CartesianGrid
} from 'recharts';
import html2canvas from 'html2canvas';
import { ProductionEntry, Shift, Employee, PersonnelLog } from './types';
import { INITIAL_DATA, GOAL_VALUE, DEFAULT_OPERATORS, INITIAL_EMPLOYEES, INITIAL_LOGS } from './constants';
import LaunchModal from './components/LaunchModal';
import EmployeeModal from './components/EmployeeModal';
import HistoryModal from './components/HistoryModal';
import OperatorModal from './components/OperatorModal';
import RoleModal from './components/RoleModal';
import ShiftModal from './components/ShiftModal';

const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316', '#64748b', '#1e293b', '#64748b', '#475569', '#94a3b8'];

const renderCustomizedLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }: any) => {
  if (percent < 0.05) return null;
  const RADIAN = Math.PI / 180;
  const radius = outerRadius * 1.15;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);
  return (
    <text x={x} y={y} fill="#1e293b" textAnchor={x > cx ? 'start' : 'end'} dominantBaseline="central" className="text-[10px] font-black">
      {`${(percent * 100).toFixed(0)}%`}
    </text>
  );
};

export const App: React.FC = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => !!localStorage.getItem('manupackaging_session'));
  const [activeTab, setActiveTab] = useState<'dashboard' | 'reports' | 'personnel'>(() => 
    (localStorage.getItem('manupackaging_active_tab') as any) || 'dashboard'
  );

  const [productionData, setProductionData] = useState<ProductionEntry[]>(() => {
    const saved = localStorage.getItem('manupackaging_data');
    return saved ? JSON.parse(saved) : INITIAL_DATA;
  });

  const [dashboardMonth, setDashboardMonth] = useState(() => {
    const saved = localStorage.getItem('manupackaging_dashboard_month');
    if (saved) return saved;
    const now = new Date();
    return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`;
  });

  // Novos estados de filtro
  const [filterOperator, setFilterOperator] = useState('Todos');
  const [filterDay, setFilterDay] = useState('');

  const [goals, setGoals] = useState<Record<string, number>>(() => {
    const saved = localStorage.getItem('manupackaging_goals');
    if (saved) return JSON.parse(saved);
    const oldGoal = localStorage.getItem('manupackaging_goal');
    return oldGoal ? { [dashboardMonth]: Number(oldGoal) } : {};
  });

  const [operators, setOperators] = useState<string[]>(() => JSON.parse(localStorage.getItem('manupackaging_operators') || JSON.stringify(DEFAULT_OPERATORS)));
  const [availableRoles, setAvailableRoles] = useState<string[]>(() => JSON.parse(localStorage.getItem('manupackaging_roles') || JSON.stringify(['Operador 1', 'Operador 2', 'Auxiliar 1', 'Auxiliar 2', 'Líder', 'Supervisor'])));
  const [employees, setEmployees] = useState<Employee[]>(() => JSON.parse(localStorage.getItem('manupackaging_employees') || JSON.stringify(INITIAL_EMPLOYEES)));
  const [personnelLogs, setPersonnelLogs] = useState<PersonnelLog[]>(() => JSON.parse(localStorage.getItem('manupackaging_personnel_logs') || JSON.stringify(INITIAL_LOGS)));
  const [availableShifts, setAvailableShifts] = useState<Shift[]>(() => JSON.parse(localStorage.getItem('manupackaging_shifts') || JSON.stringify([
    { id: '1', name: 'Diurno 1', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
    { id: '2', name: 'Noturno 1', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
    { id: '3', name: 'Diurno 2', startTime: '07:00', endTime: '19:00', type: 'Diurno' },
    { id: '4', name: 'Noturno 2', startTime: '19:00', endTime: '07:00', type: 'Noturno' },
    { id: '5', name: 'Comercial', startTime: '08:00', endTime: '18:00', type: 'Diurno' },
  ])));

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isEmployeeModalOpen, setIsEmployeeModalOpen] = useState(false);
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [isOperatorModalOpen, setIsOperatorModalOpen] = useState(false);
  const [isRoleModalOpen, setIsRoleModalOpen] = useState(false);
  const [isShiftModalOpen, setIsShiftModalOpen] = useState(false);
  const [showEremaChart, setShowEremaChart] = useState(false);
  const [editingEntry, setEditingEntry] = useState<ProductionEntry | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [selectedSlot, setSelectedSlot] = useState<any>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  const activeMachines = useMemo(() => ["Cast 1", "Cast 2", "Erema 1", "Ghezzi", "Lintech", "Wutec"], []);

  useEffect(() => { localStorage.setItem('manupackaging_data', JSON.stringify(productionData)); }, [productionData]);
  useEffect(() => { localStorage.setItem('manupackaging_employees', JSON.stringify(employees)); }, [employees]);
  useEffect(() => { localStorage.setItem('manupackaging_operators', JSON.stringify(operators)); }, [operators]);
  useEffect(() => { localStorage.setItem('manupackaging_roles', JSON.stringify(availableRoles)); }, [availableRoles]);
  useEffect(() => { localStorage.setItem('manupackaging_shifts', JSON.stringify(availableShifts)); }, [availableShifts]);
  useEffect(() => { localStorage.setItem('manupackaging_personnel_logs', JSON.stringify(personnelLogs)); }, [personnelLogs]);
  useEffect(() => { localStorage.setItem('manupackaging_active_tab', activeTab); }, [activeTab]);
  useEffect(() => { localStorage.setItem('manupackaging_dashboard_month', dashboardMonth); }, [dashboardMonth]);
  useEffect(() => { localStorage.setItem('manupackaging_goals', JSON.stringify(goals)); }, [goals]);

  const formatWeight = (val: number) => (val / 1000).toLocaleString('pt-BR', { minimumFractionDigits: 3 }) + ' T';
  const formatMinutes = (val: number) => val >= 60 ? `${Math.floor(val / 60)}h ${val % 60}m` : `${val} min`;

  // Centraliza a filtragem de dados para respeitar os novos filtros
  const filteredDashboardData = useMemo(() => {
    return productionData.filter(e => {
      const matchDay = filterDay ? e.date === filterDay : true;
      const matchMonth = !filterDay ? e.date.startsWith(dashboardMonth) : true;
      const matchOperator = filterOperator === 'Todos' ? true : e.operator === filterOperator;
      return matchDay && matchMonth && matchOperator;
    });
  }, [productionData, dashboardMonth, filterOperator, filterDay]);

  const dashboardStats = useMemo(() => {
    const currentGoal = goals[dashboardMonth] || GOAL_VALUE;
    const res = { month: 0, eremaMonth: 0, yesterday: 0, goal: currentGoal, projection: 0, avgReq: 0, prevMonthTotal: 0, prevMonthGoal: 0 };

    // Dados para o mês anterior (comparativo)
    const [year, month] = dashboardMonth.split('-').map(Number);
    const prevDate = new Date(year, month - 2, 1);
    const prevMonthStr = `${prevDate.getFullYear()}-${String(prevDate.getMonth() + 1).padStart(2, '0')}`;
    productionData.filter(e => e.date.startsWith(prevMonthStr)).forEach(e => { 
      if (!e.machine.toLowerCase().includes('erema')) res.prevMonthTotal += (e.netWeight || 0); 
    });
    res.prevMonthGoal = goals[prevMonthStr] || GOAL_VALUE;

    // Produção "Ontem" (Dia anterior ao atual real)
    const yesterdayDate = new Date(); yesterdayDate.setDate(yesterdayDate.getDate() - 1);
    const yesterdayStr = yesterdayDate.toLocaleDateString('sv-SE');
    productionData.filter(e => e.date === yesterdayStr).forEach(e => { 
      if (!e.machine.toLowerCase().includes('erema')) res.yesterday += (e.netWeight || 0); 
    });

    // Lógica principal baseada nos dados filtrados (Dia/Operador/Mês/Ano)
    filteredDashboardData.forEach(e => { 
      if (e.machine.toLowerCase().includes('erema')) res.eremaMonth += (e.netWeight || 0); 
      else res.month += (e.netWeight || 0); 
    });

    const today = new Date();
    const currentDay = dashboardMonth === today.toISOString().slice(0, 7) ? today.getDate() : 30;
    res.projection = (res.month / Math.max(1, currentDay)) * 30;
    res.avgReq = Math.max(0, (res.goal - res.month) / Math.max(1, 30 - currentDay));
    return res;
  }, [productionData, dashboardMonth, goals, filteredDashboardData]);

  const dashboardChartsData = useMemo(() => {
    const ops: any = {};
    const machines: any = {};
    const shifts: any = {};

    filteredDashboardData.forEach(e => {
      if (!ops[e.operator]) ops[e.operator] = { name: e.operator, net: 0, borra: 0, ecoA: 0, ecoBP: 0, ecoBM: 0, ecoTotal: 0, manut: 0, proc: 0, outros: 0, stops: 0 };
      if (!machines[e.machine]) machines[e.machine] = { name: e.machine, net: 0, borra: 0, stops: 0 };
      if (!shifts[e.shift]) shifts[e.shift] = { name: e.shift, net: 0 };

      if (!e.machine.toLowerCase().includes('erema')) {
        ops[e.operator].net += (e.netWeight || 0);
        machines[e.machine].net += (e.netWeight || 0);
        shifts[e.shift].net += (e.netWeight || 0);
      }
      ops[e.operator].borra += (e.borraTotal || 0);
      ops[e.operator].ecoA += (e.ecoA || 0);
      ops[e.operator].ecoBP += (e.ecoBP || 0);
      ops[e.operator].ecoBM += (e.ecoBM || 0);
      ops[e.operator].ecoTotal += (e.ecoA || 0) + (e.ecoBP || 0) + (e.ecoBM || 0);
      ops[e.operator].manut += (e.manutencaoMin || 0);
      ops[e.operator].proc += (e.processoMin || 0);
      ops[e.operator].outros += (e.outrosMin || 0);
      ops[e.operator].stops += (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0);

      machines[e.machine].borra += (e.borraTotal || 0);
      machines[e.machine].stops += (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0);
    });

    return {
      ops: Object.values(ops).sort((a: any, b: any) => b.net - a.net),
      machines: Object.values(machines).sort((a: any, b: any) => b.net - a.net),
      shifts: Object.values(shifts).sort((a: any, b: any) => b.net - a.net)
    };
  }, [filteredDashboardData]);

  // Nova lógica para motivos de parada detalhados
  const machineStopsDetails = useMemo(() => {
    const results: Record<string, { total: number; motifs: { type: string; min: number; reason: string; operator: string; date: string }[] }> = {};

    filteredDashboardData.forEach(e => {
      if (!results[e.machine]) results[e.machine] = { total: 0, motifs: [] };

      const entryTotal = (e.manutencaoMin || 0) + (e.processoMin || 0) + (e.outrosMin || 0);
      results[e.machine].total += entryTotal;

      if (e.manutencaoMin > 0) {
        results[e.machine].motifs.push({ type: 'Manutenção', min: e.manutencaoMin, reason: e.manutencaoMotivo || 'Não informado', operator: e.operator, date: e.date });
      }
      if (e.processoMin > 0) {
        results[e.machine].motifs.push({ type: 'Processo', min: e.processoMin, reason: e.processoMotivo || 'Não informado', operator: e.operator, date: e.date });
      }
      if (e.outrosMin > 0) {
        results[e.machine].motifs.push({ type: 'Outros', min: e.outrosMin, reason: e.outrosMotivo || 'Não informado', operator: e.operator, date: e.date });
      }
    });

    return Object.entries(results)
      .sort(([a], [b]) => a.localeCompare(b))
      .filter(([_, data]) => data.total > 0);
  }, [filteredDashboardData]);

  const eremaOperatorStats = useMemo(() => {
    const stats: any = {};
    filteredDashboardData
      .filter(e => e.machine.toLowerCase().includes('erema'))
      .forEach(e => {
        if (!stats[e.operator]) stats[e.operator] = 0;
        stats[e.operator] += (e.netWeight || 0);
      });
    return Object.entries(stats)
      .map(([name, value]) => ({ name, value: value as number }))
      .sort((a, b) => b.value - a.value);
  }, [filteredDashboardData]);

  const filteredReportData = useMemo(() => {
    return filteredDashboardData.filter(e => {
      const matchSearch = e.operator.toLowerCase().includes(searchTerm.toLowerCase()) || 
                          e.machine.toLowerCase().includes(searchTerm.toLowerCase());
      return matchSearch;
    }).sort((a, b) => b.date.localeCompare(a.date));
  }, [filteredDashboardData, searchTerm]);

  const reportTotals = useMemo(() => {
    return filteredReportData.reduce((acc, curr) => ({
      grossWeight: acc.grossWeight + (curr.grossWeight || 0),
      tara: acc.tara + (curr.tara || 0),
      netWeight: acc.netWeight + (curr.netWeight || 0),
      ecoA: acc.ecoA + (curr.ecoA || 0),
      ecoBP: acc.ecoBP + (curr.ecoBP || 0),
      ecoBM: acc.ecoBM + (curr.ecoBM || 0),
      borraTotal: acc.borraTotal + (curr.borraTotal || 0),
      manutencaoMin: acc.manutencaoMin + (curr.manutencaoMin || 0),
      processoMin: acc.processoMin + (curr.processoMin || 0),
      outrosMin: acc.outrosMin + (curr.outrosMin || 0),
